USHORT AllocateGameLogicSessionID()
{
	constexpr USHORT kFirstGameLogicSessionID = 2;
	constexpr USHORT kLastGameLogicSessionID = 0x7FFF;
	static std::mutex allocatorMutex;
	static USHORT nextCandidate = kFirstGameLogicSessionID;

	std::lock_guard<std::mutex> allocatorLock(allocatorMutex);
	std::lock_guard<std::recursive_mutex> clientsLock(ClientMutex);
	for (UINT attempt = kFirstGameLogicSessionID; attempt <= kLastGameLogicSessionID; ++attempt)
	{
		const USHORT candidate = nextCandidate;
		nextCandidate = candidate == kLastGameLogicSessionID
			? kFirstGameLogicSessionID
			: static_cast<USHORT>(candidate + 1);

		bool inUse = false;
		for (const auto& entry : Clients)
		{
			const std::shared_ptr<ClientNode>& Client = entry.second;
			if (Client && Client->GameID == candidate)
			{
				inUse = true;
				break;
			}
		}
		if (!inUse)
			return candidate;
	}
	return 0;
}

void ResetNormalRaceWireState(const std::shared_ptr<ClientNode>& Client)
{
	if (!Client)
		return;
	{
		std::lock_guard<std::mutex> sequenceLock(Client->NormalRaceWireSequenceMutex);
		Client->NormalRaceWireActive = false;
		Client->NormalRaceKartPhysReady = false;
		Client->NormalRaceWireRouteID = 0;
		Client->NormalRaceWireLastMsgSeq = 0;
	}
	{
		std::lock_guard<std::mutex> frameLock(Client->RankedGameFrameMutex);
		Client->RankedFrameReport = RankedGameFrameReport{};
		Client->RankedFrameForward = RankedGameFrameForward{};
		Client->RankedFrameCheck = RankedGameFrameCheck{};
	}
}



