struct SpeedLadderTrophyLevelCfg
{
	WORD Level;
	DWORD BestTime;
};

struct SpeedLadderTrophyMapCfg
{
	WORD MapID;
	std::vector<SpeedLadderTrophyLevelCfg> Levels;
};

static bool SL_YamlTryInt(const YAML::Node& node, int& out)
{
	if (!node || !node.IsScalar()) return false;
	return YAML::convert<int>::decode(node, out);
}

static bool SL_YamlTryBool(const YAML::Node& node, bool& out)
{
	if (!node || !node.IsScalar()) return false;
	if (YAML::convert<bool>::decode(node, out)) return true;
	int intValue = 0;
	if (YAML::convert<int>::decode(node, intValue))
	{
		out = (intValue != 0);
		return true;
	}
	return false;
}

static int SL_YIntAny(const YAML::Node& node, std::initializer_list<const char*> keys, int def)
{
	if (!node || !node.IsMap()) return def;
	for (const char* key : keys)
	{
		if (!key) continue;
		int value = def;
		if (SL_YamlTryInt(node[key], value)) return value;
	}
	return def;
}

static std::vector<SpeedLadderTrophyLevelCfg> SL_DefaultTrophyLevels()
{
	return {
		{ 1, 220000 },
		{ 2, 210000 },
		{ 3, 200000 },
		{ 4, 190000 },
		{ 5, 180000 },
		{ 6, 170000 },
		{ 7, 160000 },
		{ 8, 150000 },
		{ 9, 145000 },
		{ 10, 140000 },
		{ 11, 135000 },
		{ 12, 130000 },
		{ 13, 125000 },
	};
}

static std::vector<SpeedLadderTrophyMapCfg> SL_DefaultTrophyMaps(const std::vector<SpeedLadderTrophyLevelCfg>& defaultLevels)
{
	const WORD defaultMapIds[] = { 143, 253, 268, 277, 260 };
	std::vector<SpeedLadderTrophyMapCfg> maps;
	for (WORD mapId : defaultMapIds)
	{
		SpeedLadderTrophyMapCfg map;
		map.MapID = mapId;
		map.Levels = defaultLevels;
		maps.push_back(map);
	}
	return maps;
}

static void SL_AddUniquePath(std::vector<std::string>& paths, const std::string& path)
{
	if (path.empty()) return;
	if (std::find(paths.begin(), paths.end(), path) == paths.end()) paths.push_back(path);
}

static std::vector<std::string> SL_SpeedLadderConfigPaths()
{
	std::vector<std::string> paths;
	SL_AddUniquePath(paths, ".\\Config\\SpeedLadderMaps.yml");
	SL_AddUniquePath(paths, "Config\\SpeedLadderMaps.yml");
	SL_AddUniquePath(paths, ".\\x64\\Release\\Config\\SpeedLadderMaps.yml");
	char modulePath[MAX_PATH] = { 0 };
	DWORD moduleLen = GetModuleFileNameA(NULL, modulePath, MAX_PATH);
	if (moduleLen > 0 && moduleLen < MAX_PATH)
	{
		std::filesystem::path exePath(modulePath);
		std::filesystem::path exeDir = exePath.parent_path();
		SL_AddUniquePath(paths, (exeDir / "Config" / "SpeedLadderMaps.yml").string());
		SL_AddUniquePath(paths, (exeDir / ".." / ".." / "Config" / "SpeedLadderMaps.yml").lexically_normal().string());
	}
	return paths;
}

UINT SpeedLadder_GetCurrentSeasonID()
{
	for (const std::string& path : SL_SpeedLadderConfigPaths())
	{
		try
		{
			if (!std::filesystem::exists(path)) continue;
			YAML::Node file = YAML::LoadFile(path);
			YAML::Node root = file["speed_ladder_maps"] ? file["speed_ladder_maps"] : file;
			int seasonID = 1;
			if (SL_YamlTryInt(root["season_id"], seasonID) || SL_YamlTryInt(root["SeasonID"], seasonID))
			{
				return static_cast<UINT>(seasonID > 0 ? seasonID : 1);
			}
		}
		catch (const std::exception&)
		{
		}
	}
	return 1;
}

static std::vector<SpeedLadderTrophyLevelCfg> SL_ParseLevelsNode(const YAML::Node& node, const std::vector<SpeedLadderTrophyLevelCfg>& fallback)
{
	std::vector<SpeedLadderTrophyLevelCfg> levels;
	if (!node || !node.IsSequence()) return fallback;
	for (size_t i = 0; i < node.size(); ++i)
	{
		YAML::Node row = node[i];
		if (!row || !row.IsMap()) continue;
		int level = SL_YIntAny(row, { "level", "Level", "rank", "Rank" }, static_cast<int>(i) + 1);
		int bestTime = SL_YIntAny(row, { "best_time", "bestTime", "time", "BestTime" }, 0);
		if (level <= 0 || level > 65535 || bestTime <= 0) continue;
		SpeedLadderTrophyLevelCfg cfg;
		cfg.Level = static_cast<WORD>(level);
		cfg.BestTime = static_cast<DWORD>(bestTime);
		levels.push_back(cfg);
	}
	return levels.empty() ? fallback : levels;
}

static std::vector<SpeedLadderTrophyMapCfg> SL_LoadSpeedLadderMaps(std::vector<SpeedLadderTrophyLevelCfg>& outDefaultLevels, std::string* outLoadedPath = nullptr, bool* outEnabled = nullptr)
{
	outDefaultLevels = SL_DefaultTrophyLevels();
	std::vector<SpeedLadderTrophyMapCfg> maps = SL_DefaultTrophyMaps(outDefaultLevels);
	if (outLoadedPath) outLoadedPath->clear();
	if (outEnabled) *outEnabled = true;

	for (const std::string& path : SL_SpeedLadderConfigPaths())
	{
		try
		{
			if (!std::filesystem::exists(path)) continue;
			YAML::Node file = YAML::LoadFile(path);
			YAML::Node root = file["speed_ladder_maps"] ? file["speed_ladder_maps"] : file;
			if (!root || !root.IsMap()) continue;

			bool enabled = true;
			SL_YamlTryBool(root["enabled"], enabled);
			if (outEnabled) *outEnabled = enabled;
			if (outLoadedPath) *outLoadedPath = path;
			if (!enabled)
			{
				return std::vector<SpeedLadderTrophyMapCfg>();
			}

			outDefaultLevels = SL_ParseLevelsNode(root["default_levels"], outDefaultLevels);
			std::vector<SpeedLadderTrophyMapCfg> parsedMaps;
			YAML::Node mapsNode = root["maps"];
			if (mapsNode && mapsNode.IsSequence())
			{
				for (size_t i = 0; i < mapsNode.size(); ++i)
				{
					YAML::Node row = mapsNode[i];
					int mapId = 0;
					if (row.IsMap()) mapId = SL_YIntAny(row, { "map_id", "mapId", "MapID", "id" }, 0);
					else SL_YamlTryInt(row, mapId);
					if (mapId <= 0 || mapId > 65535) continue;

					SpeedLadderTrophyMapCfg map;
					map.MapID = static_cast<WORD>(mapId);
					map.Levels = row.IsMap() ? SL_ParseLevelsNode(row["levels"], outDefaultLevels) : outDefaultLevels;
					parsedMaps.push_back(map);
				}
			}

			return parsedMaps.empty() ? SL_DefaultTrophyMaps(outDefaultLevels) : parsedMaps;
		}
		catch (const std::exception& e)
		{
			QQS_DebugPrintf10001("[MsgID-FIXED] 28457 SpeedLadder yml load failed path=%s error=%s\n", path.c_str(), e.what());
		}
	}
	return maps;
}

static bool SL_CalcTrophyForLevels(const std::vector<SpeedLadderTrophyLevelCfg>& levels, DWORD BestTime, BYTE& TrophyLevel, BYTE& TrophyCount)
{
	TrophyLevel = 0;
	TrophyCount = 0;
	if (BestTime == 0 || BestTime == 0xFFFFFFFF) return false;

	WORD bestLevel = 0;
	for (const auto& level : levels)
	{
		if (BestTime <= level.BestTime)
		{
			if (level.Level > bestLevel) bestLevel = level.Level;
		}
	}
	TrophyLevel = static_cast<BYTE>(std::min<WORD>(bestLevel, 255));
	TrophyCount = bestLevel == 0 ? 0 : static_cast<BYTE>(std::min<WORD>((bestLevel + 2) / 3, 255));
	return true;
}

bool SpeedLadder_CalcTrophyForMap(UINT MapID, DWORD BestTime, BYTE& TrophyLevel, BYTE& TrophyCount)
{
	TrophyLevel = 0;
	TrophyCount = 0;
	if (MapID == 0 || BestTime == 0 || BestTime == 0xFFFFFFFF) return false;

	std::vector<SpeedLadderTrophyLevelCfg> defaultLevels;
	std::vector<SpeedLadderTrophyMapCfg> maps = SL_LoadSpeedLadderMaps(defaultLevels);
	for (const auto& map : maps)
	{
		if (map.MapID != MapID) continue;
		return SL_CalcTrophyForLevels(map.Levels, BestTime, TrophyLevel, TrophyCount);
	}
	return false;
}

bool SpeedLadder_IsConfiguredMap(UINT MapID)
{
	if (MapID == 0) return false;

	std::vector<SpeedLadderTrophyLevelCfg> defaultLevels;
	const std::vector<SpeedLadderTrophyMapCfg> maps = SL_LoadSpeedLadderMaps(defaultLevels);
	for (const auto& map : maps)
	{
		if (map.MapID == MapID) return true;
	}
	return false;
}

bool SpeedLadder_IsLobbyArmed(std::shared_ptr<ClientNode> Client)
{
	if (!Client) return false;
	if (Client->SpeedLadderLobbyStage < QQS_SPEED_LADDER_LOBBY_STAGE_28458) return false;
	if (Client->SpeedLadderLobbyTick == 0) return false;
	const DWORD delta = GetTickCount() - Client->SpeedLadderLobbyTick;
	return delta <= QQS_SPEED_LADDER_RACE_GATE_MS;
}

bool SpeedLadder_IsReturnContextArmed(std::shared_ptr<ClientNode> Client)
{
	if (!Client) return false;
	if (!Client->SpeedLadderReturnPending) return false;
	if (Client->SpeedLadderReturnTick == 0) return false;
	const DWORD delta = GetTickCount() - Client->SpeedLadderReturnTick;
	return delta <= QQS_SPEED_LADDER_RACE_GATE_MS;
}

void SpeedLadder_MarkReturnContext(std::shared_ptr<ClientNode> Client, UINT MapID, UINT SeasonID, const char* Reason)
{
	if (!Client) return;
	Client->SpeedLadderReturnPending = true;
	Client->SpeedLadderReturnTick = GetTickCount();
	Client->SpeedLadderReturnMapID = MapID;
	Client->SpeedLadderReturnSeasonID = SeasonID;
	if (ShouldPrintDebugForUin10001(Client))
	{
		QQS_DebugPrintf10001("[SpeedLadder-RETURN] mark Uin=%u Reason=%s MapID=%u Season=%u Tick=%u\n",
			Client->Uin, Reason ? Reason : "", Client->SpeedLadderReturnMapID,
			Client->SpeedLadderReturnSeasonID, Client->SpeedLadderReturnTick);
	}
}

void SpeedLadder_ClearRaceContext(std::shared_ptr<ClientNode> Client, const char* Reason)
{
	if (!Client) return;
	const bool hadContext = Client->SpeedLadderRacePending || Client->SpeedLadderRaceActive ||
		Client->SpeedLadderRaceMapID != 0 || Client->SpeedLadderRaceSeasonID != 0 || Client->SpeedLadderRaceArmTick != 0;
	if (hadContext && ShouldPrintDebugForUin10001(Client))
	{
		QQS_DebugPrintf10001("[SpeedLadder-RACE] clear Uin=%u Reason=%s Pending=%u Active=%u MapID=%u Season=%u ArmTick=%u\n",
			Client->Uin, Reason ? Reason : "", Client->SpeedLadderRacePending ? 1 : 0, Client->SpeedLadderRaceActive ? 1 : 0,
			Client->SpeedLadderRaceMapID, Client->SpeedLadderRaceSeasonID, Client->SpeedLadderRaceArmTick);
	}
	Client->SpeedLadderRacePending = false;
	Client->SpeedLadderRaceActive = false;
	Client->SpeedLadderRaceMapID = 0;
	Client->SpeedLadderRaceSeasonID = 0;
	Client->SpeedLadderRaceArmTick = 0;
}

void SpeedLadder_ClearReturnContext(std::shared_ptr<ClientNode> Client, const char* Reason)
{
	if (!Client) return;
	const bool hadContext = Client->SpeedLadderReturnPending || Client->SpeedLadderReturnTick != 0 ||
		Client->SpeedLadderReturnMapID != 0 || Client->SpeedLadderReturnSeasonID != 0;
	if (hadContext && ShouldPrintDebugForUin10001(Client))
	{
		QQS_DebugPrintf10001("[SpeedLadder-RETURN] clear Uin=%u Reason=%s Pending=%u MapID=%u Season=%u Tick=%u\n",
			Client->Uin, Reason ? Reason : "", Client->SpeedLadderReturnPending ? 1 : 0,
			Client->SpeedLadderReturnMapID, Client->SpeedLadderReturnSeasonID, Client->SpeedLadderReturnTick);
	}
	Client->SpeedLadderReturnPending = false;
	Client->SpeedLadderReturnTick = 0;
	Client->SpeedLadderReturnMapID = 0;
	Client->SpeedLadderReturnSeasonID = 0;
}

static const SpeedLadderTrophyMapCfg* SL_FindTrophyMapCfg(const std::vector<SpeedLadderTrophyMapCfg>& maps, UINT MapID)
{
	for (const auto& map : maps)
	{
		if (map.MapID == MapID) return &map;
	}
	return nullptr;
}

static void SL_WriteTrophyMapCfg(BYTE*& p, const SpeedLadderTrophyMapCfg& map)
{
	BYTE* pMap = p;
	Write16(pMap, 0); // Len
	Write16(pMap, map.MapID);
	const size_t levelCount = std::min<size_t>(map.Levels.size(), 255);
	Write16(pMap, static_cast<WORD>(levelCount));
	for (size_t i = 0; i < levelCount; ++i)
	{
		BYTE* pLevel = pMap;
		Write16(pLevel, 8); // Len
		Write16(pLevel, map.Levels[i].Level);
		Write32(pLevel, map.Levels[i].BestTime);
		pMap = pLevel;
	}
	const size_t len = static_cast<size_t>(pMap - p);
	Set16(p, static_cast<WORD>(len));
	p = pMap;
}

static void NotifySpeedLadderTrophyMore28459(std::shared_ptr<ClientNode> Client, const std::vector<SpeedLadderTrophyMapCfg>& maps, size_t startIndex)
{
	if (!Client || startIndex >= maps.size()) return;

	std::vector<BYTE> response(819200);
	BYTE* p = response.data();
	// SendToClient 会把 MSGHEAD.BodyLen 写成 len + 2；payload 不能再手写长度字段。
	// 客户端 Lua 的 DecodeShort 读取的是 MSGHEAD.BodyLen，然后才进入这里的 m_ushMapCount。
	const size_t count = std::min<size_t>(maps.size() - startIndex, 65535);
	Write16(p, static_cast<WORD>(count));
	for (size_t i = 0; i < count; ++i)
	{
		SL_WriteTrophyMapCfg(p, maps[startIndex + i]);
	}
	const bool hasNext = (startIndex + count) < maps.size();
	Write8(p, hasNext ? 1 : 0);

	const DWORD len = static_cast<DWORD>(p - response.data());
	SendToClient(Client, 28459, response.data(), len, Client->ConnID, FE_PLAYER, 1, Notify);
	Client->SpeedLadderLobbyTick = GetTickCount();
	Client->SpeedLadderLobbyStage = QQS_SPEED_LADDER_LOBBY_STAGE_28459;
	if (ShouldPrintDebugForUin10001(Client))
	{
		QQS_DebugPrintf10001("[SpeedLadder-Lobby] stage=28459 Uin=%u Tick=%u map_count=%u hasNext=%u\n",
			Client->Uin, Client->SpeedLadderLobbyTick, static_cast<unsigned>(count), hasNext ? 1 : 0);
		printf("[MsgID-FIXED] 28459 SpeedLadder yml trophy-more DataLen=%u MsgHeadBodyLen=%u map_count=%u hasNext=%u\n", len, len + 2, static_cast<unsigned>(count), hasNext ? 1 : 0);
	}
}

static void ResponseFixedMapChallengeRank28457(std::shared_ptr<ClientNode> Client)
{
	if (!Client)
	{
		return;
	}

	std::vector<SpeedLadderTrophyLevelCfg> defaultLevels;
	std::string loadedPath;
	bool enabled = true;
	std::vector<SpeedLadderTrophyMapCfg> maps = SL_LoadSpeedLadderMaps(defaultLevels, &loadedPath, &enabled);
	const size_t firstCount = std::min<size_t>(maps.size(), 200);
	const bool hasMore = maps.size() > firstCount;

	std::vector<BYTE> response(819200);
	BYTE* p = response.data();
	// SendToClient 会把 MSGHEAD.BodyLen 写成 len + 2；payload 从 m_uiUin 开始。
	// 这里如果再写一个内部长度，会把 Uin/Time/ResultId/MapCount 全部错位。
	Write32(p, Client->Uin);
	Write32(p, static_cast<DWORD>(time(nullptr)));
	Write32(p, 0); // ResultId
	Write16(p, static_cast<WORD>(firstCount)); // MapCount
	for (size_t i = 0; i < firstCount; ++i)
	{
		SL_WriteTrophyMapCfg(p, maps[i]);
	}
	Write8(p, hasMore ? 1 : 0); // HasMoreInfo

	const DWORD len = static_cast<DWORD>(p - response.data());
	SendToClient(Client, 28457, response.data(), len, Client->ConnID, FE_PLAYER, 1, Response);
	Client->SpeedLadderLobbyTick = GetTickCount();
	Client->SpeedLadderLobbyStage = QQS_SPEED_LADDER_LOBBY_STAGE_28457;

	if (ShouldPrintDebugForUin10001(Client))
	{
		QQS_DebugPrintf10001("[SpeedLadder-Lobby] stage=28457 Uin=%u Tick=%u map_count=%u HasMore=%u total_maps=%u\n",
			Client->Uin, Client->SpeedLadderLobbyTick, static_cast<unsigned>(firstCount), hasMore ? 1 : 0, static_cast<unsigned>(maps.size()));
		printf("[SpeedLadder-REQ] 28457 trophy-config requested Uin=%u DataLen=%u MsgHeadBodyLen=%u map_count=%u HasMore=%u total_maps=%u\n", Client ? Client->Uin : 0, len, len + 2, static_cast<unsigned>(firstCount), hasMore ? 1 : 0, static_cast<unsigned>(maps.size()));
		printf("[MsgID-FIXED] 28457 SpeedLadder yml trophy-config DataLen=%u MsgHeadBodyLen=%u map_count=%u level_default=%u\n", len, len + 2, static_cast<unsigned>(firstCount), static_cast<unsigned>(defaultLevels.size()));
		if (!loadedPath.empty())
		{
			QQS_DebugPrintf10001("[MsgID-FIXED] 28457 SpeedLadder yml path=%s enabled=%u total_maps=%u\n", loadedPath.c_str(), enabled ? 1 : 0, static_cast<unsigned>(maps.size()));
		}
	}

	if (hasMore)
	{
		NotifySpeedLadderTrophyMore28459(Client, maps, firstCount);
	}
}



void ResponseFixedMapChallengeRank28458(std::shared_ptr<ClientNode> Client)
{
	if (!Client)
	{
		return;
	}

	struct MapPlayerDataRecord
	{
		WORD MapID;
		DWORD BestTime;
		BYTE TrophyLevel;
		BYTE TrophyCount;
		std::string Md5;
		std::string Path;
	};

	static const char kMapRankUrl[] = "http://maprank-70415.cos.njc.vod.tencent-cloud.com";
	std::vector<SpeedLadderTrophyLevelCfg> defaultLevels;
	const std::vector<SpeedLadderTrophyMapCfg> fullMaps = SL_LoadSpeedLadderMaps(defaultLevels);
	const UINT seasonID = SpeedLadder_GetCurrentSeasonID();
	std::vector<SpeedLadderPlayerMapRow> dbRows;
	const bool dbOk = PlayerDB_GetSpeedLadderPlayerMapsBySource(Client->Uin, seasonID, SPEED_LADDER_RECORD_SOURCE_SPEED_LADDER, dbRows);
	std::vector<MapPlayerDataRecord> records;
	UINT skippedInvalidTime = 0;
	UINT skippedNoMapCfg = 0;
	UINT skippedNoTrophy = 0;

	for (const auto& row : dbRows)
	{
		if (row.BestTime == 0 || row.BestTime == 0xFFFFFFFF)
		{
			++skippedInvalidTime;
			continue;
		}

		const SpeedLadderTrophyMapCfg* mapCfg = SL_FindTrophyMapCfg(fullMaps, row.MapID);
		if (!mapCfg)
		{
			++skippedNoMapCfg;
			continue;
		}

		BYTE trophyLevel = 0;
		BYTE trophyCount = 0;
		if (!SL_CalcTrophyForLevels(mapCfg->Levels, row.BestTime, trophyLevel, trophyCount))
		{
			++skippedNoTrophy;
			continue;
		}

		std::string md5 = "00000000000000000000000000000000";
		std::string path;
		if (!row.ReplayMd5.empty()) md5 = row.ReplayMd5;
		if (!row.ReplayPath.empty()) path = row.ReplayPath;
		if (path.empty())
		{
			char pathBuf[128] = { 0 };
			snprintf(pathBuf, sizeof(pathBuf), "local-%u-%u-%u", Client->Uin, row.MapID, row.BestTime);
			path = pathBuf;
		}
		records.push_back({ static_cast<WORD>(row.MapID), row.BestTime, trophyLevel, trophyCount, md5, path });
	}

	std::vector<BYTE> response(819200);
	BYTE* p = response.data();
	// 28458 严格官服语义：只发真实 source=2 记录；无记录时 map_count=0，不再发兼容假记录。

	Write32(p, Client->Uin);
	Write32(p, static_cast<DWORD>(time(nullptr)));
	Write32(p, 0); // ResultId

	const WORD urlLen = static_cast<WORD>(strlen(kMapRankUrl));
	Write16(p, urlLen);
	memcpy(p, kMapRankUrl, urlLen);
	p += urlLen;

	Write16(p, static_cast<WORD>(std::min<size_t>(records.size(), 65535)));

	for (const auto& record : records)
	{
		const std::string md5 = record.Md5.empty() ? "00000000000000000000000000000000" : record.Md5;
		const std::string path = record.Path.empty() ? "local" : record.Path;
		const WORD md5Len = static_cast<WORD>(std::min<size_t>(md5.size(), 63) + 1); // official body includes trailing NUL
		const WORD pathLen = static_cast<WORD>(std::min<size_t>(path.size(), 255));
		const WORD shadowLen = static_cast<WORD>(sizeof(WORD) + sizeof(WORD) + md5Len + sizeof(WORD) + pathLen);
		const WORD itemLen = static_cast<WORD>(sizeof(WORD) + sizeof(WORD) + sizeof(DWORD) + sizeof(BYTE) + sizeof(BYTE) + shadowLen);

		Write16(p, itemLen);
		Write16(p, record.MapID);
		Write32(p, record.BestTime);
		Write8(p, record.TrophyLevel);
		Write8(p, record.TrophyCount);

		Write16(p, shadowLen);
		Write16(p, md5Len);
		memcpy(p, md5.data(), md5Len - 1);
		p += md5Len - 1;
		Write8(p, 0);
		Write16(p, pathLen);
		memcpy(p, path.data(), pathLen);
		p += pathLen;
	}

	const DWORD len = static_cast<DWORD>(p - response.data());

	SendToClient(Client, 28458, response.data(), len, Client->ConnID, FE_PLAYER, 1, Response);
	Client->SpeedLadderLobbyTick = GetTickCount();
	Client->SpeedLadderLobbyStage = QQS_SPEED_LADDER_LOBBY_STAGE_28458;

	if (ShouldPrintDebugForUin10001(Client))
	{
		QQS_DebugPrintf10001("[SpeedLadder-Lobby] stage=28458 Uin=%u Tick=%u source=ladder-db-official map_count=%u\n",
			Client->Uin, Client->SpeedLadderLobbyTick, static_cast<unsigned>(records.size()));
		QQS_DebugPrintf10001("[SpeedLadder-28458] official-len-check Uin=%u OfficialSampleDataLen=146 ActualDataLen=%u MapCount=%u Comparable=%u Note=path/u-in-dependent\n",
			Client->Uin, len, static_cast<unsigned>(records.size()), records.size() == 1 ? 1 : 0);
		printf("[MsgID-FIXED] 28458 SpeedLadder player-data source=ladder-db-official DataLen=%u MsgHeadBodyLen=%u map_count=%u db_rows=%u db_ok=%u skipped_invalid_time=%u skipped_no_map=%u skipped_no_trophy=%u season=%u\n",
			len, len + 2, static_cast<unsigned>(records.size()), static_cast<unsigned>(dbRows.size()), dbOk ? 1 : 0,
			skippedInvalidTime, skippedNoMapCfg, skippedNoTrophy, seasonID);
	}
}

static constexpr size_t kQQSOfficialInventoryPageLimit = 1000;

static std::vector<ItemInfo> QQS_PrepareOfficialInventoryItems(
	const std::shared_ptr<ClientNode>& Client,
	const std::vector<ItemInfo>& source)
{
	std::vector<ItemInfo> items;
	items.reserve(source.size());
	for (const auto& original : source)
	{
		ItemInfo item = original;
		const UINT itemType = GetItemType(item.ItemID);
		if (itemType == EAIT_CAR && Client && Client->KartID != 0)
			item.Status = item.ItemID == Client->KartID;
		else if (itemType == EAIT_SKIN)
			item.Status = 0;
		item.ItemType = 0;
		items.push_back(item);
	}
	return items;
}

static bool QQS_SendOfficialInventory28346(
	const std::shared_ptr<ClientNode>& Client,
	USHORT innerMsg,
	const std::vector<ItemInfo>& items,
	bool hasNext,
	USHORT totalItemNum,
	UINT responseTime,
	int wireMsgSeq)
{
	std::vector<BYTE> body;
	std::string diag;
	const DWORD clientPid = Client ? static_cast<DWORD>(Client->LoginClientPID) : 0;
	const bool built = innerMsg == 437
		? BuildOfficialSafePlayerItems437(Client->Uin, responseTime, clientPid, items, hasNext, totalItemNum, body, &diag)
		: BuildOfficialSafePlayerItems438(Client->Uin, responseTime, clientPid, items, hasNext, body, &diag);
	if (!built)
	{
		QQS_DebugPrintf10001(
			"[INVENTORY][BUILD-FAIL] Uin=%u InnerMsg=%u Items=%zu HasNext=%u Total=%u ClientPID=%u Error=%s\n",
			Client ? Client->Uin : 0,
			static_cast<UINT>(innerMsg),
			items.size(),
			hasNext ? 1u : 0u,
			static_cast<UINT>(totalItemNum),
			clientPid,
			diag.c_str());
		return false;
	}

	const USHORT routeId = GetClientWirePlayerID16(Client);
	if (routeId == 0)
	{
		QQS_DebugPrintf10001(
			"[INVENTORY][SEND-FAIL] Uin=%u InnerMsg=%u Items=%zu Error=invalid-player-route\n",
			Client->Uin,
			static_cast<UINT>(innerMsg),
			items.size());
		return false;
	}
	if (!SendToClientWithWireDstIDAndMsgSeq(
			Client,
			28346,
			body.data(),
			static_cast<DWORD>(body.size()),
			static_cast<short>(routeId),
			FE_PLAYER,
			static_cast<short>(routeId),
			wireMsgSeq,
			Notify))
	{
		QQS_DebugPrintf10001(
			"[INVENTORY][SEND-FAIL] Uin=%u InnerMsg=%u Items=%zu PayloadLen=%zu\n",
			Client->Uin,
			static_cast<UINT>(innerMsg),
			items.size(),
			body.size());
		return false;
	}

	QQS_DebugPrintf10001(
		"[INVENTORY][SEND] Uin=%u InnerMsg=%u Items=%zu HasNext=%u Total=%u PayloadLen=%zu FirstItem=%u LastItem=%u\n",
		Client->Uin,
		static_cast<UINT>(innerMsg),
		items.size(),
		hasNext ? 1u : 0u,
		static_cast<UINT>(totalItemNum),
		body.size(),
		items.empty() ? 0 : items.front().ItemID,
		items.empty() ? 0 : items.back().ItemID);
	return true;
}

static void RequestOfficialSafe28346(
	const std::shared_ptr<ClientNode>& Client,
	const BYTE* body,
	size_t bodyLen)
{
	// OnRecvFromClient 传入 MSGHEAD::BodyLen；该值包含自身 2 字节，body 指针
	// 已经位于实际 payload 起点。
	if (bodyLen < sizeof(USHORT))
	{
		QQS_DebugPrintf10001("[28346][REQUEST-REJECT] Uin=%u BodyLen=%zu Reason=declared-body-too-short\n",
			Client ? Client->Uin : 0,
			bodyLen);
		return;
	}
	const size_t payloadLen = bodyLen - sizeof(USHORT);

	Msg28346Envelope envelope;
	Msg28346ParseDiag parseDiag;
	if (!TryParseOfficialMsg28346Envelope(body, payloadLen, 0, envelope, &parseDiag))
	{
		QQS_DebugPrintf10001(
			"[28346][REQUEST-REJECT] Uin=%u BodyLen=%zu PayloadLen=%zu Reason=%s InnerMsg=%u InnerLen=%u Mode=%u\n",
			Client ? Client->Uin : 0,
			bodyLen,
			payloadLen,
			parseDiag.Reason.c_str(),
			static_cast<UINT>(parseDiag.InnerMsg),
			static_cast<UINT>(parseDiag.InnerLen),
			static_cast<UINT>(parseDiag.Mode));
		return;
	}

	if (!Client || envelope.OuterUin != Client->Uin)
	{
		QQS_DebugPrintf10001(
			"[28346][REQUEST-REJECT] Uin=%u OuterUin=%u InnerMsg=%u InnerLen=%u Reason=outer-uin-mismatch\n",
			Client ? Client->Uin : 0,
			envelope.OuterUin,
			static_cast<UINT>(envelope.InnerMsg),
			static_cast<UINT>(envelope.InnerLen));
		return;
	}

	// Ranked gameplay arrives on the dedicated PVP transport, while room,
	// ready and settlement state remains on the authenticated player session.
	// Rebind only when ResolveActiveRaceStateClient proves the exact transport
	// ownership; non-room and non-ranked safe requests retain their packet client.
	std::shared_ptr<ClientNode> raceStateClient = Client;
	if (envelope.InnerMsg == 120 || envelope.InnerMsg == 123)
	{
		std::shared_ptr<ClientNode> resolvedClient;
		std::shared_ptr<RoomNode> activeRaceRoom;
		if (ResolveActiveRaceStateClient(
				Client,
				envelope.OuterUin,
				resolvedClient,
				activeRaceRoom))
		{
			raceStateClient = resolvedClient;
		}
	}

	if (envelope.InnerMsg == 103)
	{
		QQSpeedMsg103::RequestFields fields;
		std::vector<std::uint8_t> plainBody;
		std::string decodeError;
		if (!QQSpeedMsg103::DecodeSafeRequestToPlain(
			envelope.InnerBody,
			envelope.InnerBodyLen,
			plainBody,
			&fields,
			&decodeError))
		{
			QQS_DebugPrintf10001(
				"[28346][103-REJECT] Uin=%u InnerLen=%u Reason=%s\n",
				Client->Uin,
				static_cast<UINT>(envelope.InnerLen),
				decodeError.c_str());
			return;
		}
		if (fields.uin != Client->Uin || fields.uin != envelope.OuterUin)
		{
			QQS_DebugPrintf10001(
				"[28346][103-REJECT] Uin=%u OuterUin=%u InnerUin=%u Reason=inner-uin-mismatch\n",
				Client->Uin,
				envelope.OuterUin,
				fields.uin);
			return;
		}

		QQS_DebugPrintf10001(
			"[28346][103-DECODE] Uin=%u Time=%u Base=%u Sub=%u SeatNum=%u ChatRoomType=%u SceneID=%u PresetOB=%u PlainLen=%zu\n",
			fields.uin,
			fields.timestamp,
			static_cast<UINT>(fields.baseGameMode),
			static_cast<UINT>(fields.subGameMode),
			static_cast<UINT>(fields.seatNum),
			static_cast<UINT>(fields.chatRoomType),
			static_cast<UINT>(fields.sceneId),
			static_cast<UINT>(fields.presetObNum),
			plainBody.size());
		CompleteOfficialEscFlow(Client, 103);
		RequestCreateRoom(Client, plainBody.data(), plainBody.size() + sizeof(USHORT));
		return;
	}

	if (envelope.InnerMsg == 110)
	{
		std::vector<std::uint8_t> plainBody;
		std::string decodeError;
		if (!QQSpeedMsg110::DecodeSafeRequestToPlain(
			envelope.InnerBody,
			envelope.InnerBodyLen,
			plainBody,
			&decodeError))
		{
			QQS_DebugPrintf10001(
				"[28346][110-REJECT] Uin=%u InnerLen=%u Reason=%s\n",
				Client->Uin,
				static_cast<UINT>(envelope.InnerLen),
				decodeError.c_str());
			return;
		}
		if (plainBody.size() != 9)
		{
			QQS_DebugPrintf10001(
				"[28346][110-REJECT] Uin=%u PlainLen=%zu Reason=plain-length-mismatch\n",
				Client->Uin,
				plainBody.size());
			return;
		}
		const UINT innerUin =
			(static_cast<UINT>(plainBody[0]) << 24) |
			(static_cast<UINT>(plainBody[1]) << 16) |
			(static_cast<UINT>(plainBody[2]) << 8) |
			static_cast<UINT>(plainBody[3]);
		if (innerUin != Client->Uin || innerUin != envelope.OuterUin)
		{
			QQS_DebugPrintf10001(
				"[28346][110-REJECT] Uin=%u OuterUin=%u InnerUin=%u Reason=inner-uin-mismatch\n",
				Client->Uin,
				envelope.OuterUin,
				innerUin);
			return;
		}
		RequestStartGame(Client, plainBody.data(), plainBody.size() + sizeof(USHORT));
		return;
	}

	if (envelope.InnerMsg == 112)
	{
		std::vector<std::uint8_t> plainBody;
		std::string decodeError;
		if (!QQSpeedMsg112::DecodeSafeRequestToPlain(
			envelope.InnerBody,
			envelope.InnerBodyLen,
			plainBody,
			&decodeError))
		{
			QQS_DebugPrintf10001(
				"[28346][112-REJECT] Uin=%u InnerLen=%u Reason=%s\n",
				Client->Uin,
				static_cast<UINT>(envelope.InnerLen),
				decodeError.c_str());
			return;
		}
		if (plainBody.size() != 8)
		{
			QQS_DebugPrintf10001(
				"[28346][112-REJECT] Uin=%u PlainLen=%zu Reason=plain-length-mismatch\n",
				Client->Uin,
				plainBody.size());
			return;
		}
		const UINT innerUin =
			(static_cast<UINT>(plainBody[0]) << 24) |
			(static_cast<UINT>(plainBody[1]) << 16) |
			(static_cast<UINT>(plainBody[2]) << 8) |
			static_cast<UINT>(plainBody[3]);
		if (innerUin != Client->Uin || innerUin != envelope.OuterUin)
		{
			QQS_DebugPrintf10001(
				"[28346][112-REJECT] Uin=%u OuterUin=%u InnerUin=%u Reason=inner-uin-mismatch\n",
				Client->Uin,
				envelope.OuterUin,
				innerUin);
			return;
		}
		RequestHello(Client, plainBody.data(), plainBody.size() + sizeof(USHORT));
		return;
	}

	if (envelope.InnerMsg == 120)
	{
		std::vector<std::uint8_t> plainBody;
		std::string decodeError;
		if (!QQSpeedMsg120::DecodeSafeRequestToPlain(
			envelope.InnerBody,
			envelope.InnerBodyLen,
			plainBody,
			&decodeError))
		{
			QQS_DebugPrintf10001(
				"[28346][120-REJECT] Uin=%u InnerLen=%u Reason=%s\n",
				Client->Uin,
				static_cast<UINT>(envelope.InnerLen),
				decodeError.c_str());
			return;
		}
		if (plainBody.size() != 0x2E)
		{
			QQS_DebugPrintf10001(
				"[28346][120-REJECT] Uin=%u PlainLen=%zu Reason=plain-length-mismatch\n",
				Client->Uin,
				plainBody.size());
			return;
		}
		const UINT innerUin = QQS_ReadBE32(plainBody.data());
		if (innerUin != Client->Uin || innerUin != envelope.OuterUin)
		{
			QQS_DebugPrintf10001(
				"[28346][120-REJECT] Uin=%u OuterUin=%u InnerUin=%u Reason=inner-uin-mismatch\n",
				Client->Uin,
				envelope.OuterUin,
				innerUin);
			return;
		}

		// 与直接 Msg120 分发保持同一原生门条件。
		if (raceStateClient->TaskID == 0x06A5)
			RequestPurplePracticePrepareReady(
				raceStateClient, plainBody.data(), plainBody.size() + sizeof(USHORT));
		else if (raceStateClient->TaskID == 0 || raceStateClient->TaskID == 0xFFFC || raceStateClient->TaskID == 0xFFFD)
			RequestPrepareReady(
				raceStateClient, plainBody.data(), plainBody.size() + sizeof(USHORT));
		return;
	}

	if (envelope.InnerMsg == 123)
	{
		std::vector<std::uint8_t> legacyBody;
		QQSpeedMsg123::LegacyGameplaySummary summary;
		std::string decodeError;
		if (!QQSpeedMsg123::DecodeSafeRequestToLegacy(
			envelope.InnerBody,
			envelope.InnerBodyLen,
			Client->Uin,
			legacyBody,
			&summary,
			&decodeError))
		{
			QQS_DebugPrintf10001(
				"[28346][123-REJECT] Uin=%u InnerLen=%u Reason=%s\n",
				Client->Uin,
				static_cast<UINT>(envelope.InnerLen),
				decodeError.c_str());
			return;
		}
		if (summary.uin != envelope.OuterUin ||
			summary.bytesConsumed != legacyBody.size())
		{
			QQS_DebugPrintf10001(
				"[28346][123-REJECT] Uin=%u OuterUin=%u InnerUin=%u LegacyLen=%zu Consumed=%zu Reason=validated-body-mismatch\n",
				Client->Uin,
				envelope.OuterUin,
				summary.uin,
				legacyBody.size(),
				summary.bytesConsumed);
			return;
		}

		// 与直接 Msg123 分发保持同一原生门条件。
		if (raceStateClient->IsFinish != TRUE)
			RequestReportCurrentInfo(
				raceStateClient, legacyBody.data(), legacyBody.size() + sizeof(USHORT));
		return;
	}

	if (envelope.InnerMsg == 138)
	{
		std::vector<std::uint8_t> plainBody;
		QQSpeedMsg138::RequestFields fields;
		std::string decodeError;
		if (!QQSpeedMsg138::DecodeSafeRequestToPlain(
			envelope.InnerBody,
			envelope.InnerBodyLen,
			Client->Uin,
			plainBody,
			&fields,
			&decodeError))
		{
			QQS_DebugPrintf10001(
				"[28346][138-REJECT] Uin=%u InnerLen=%u Reason=%s\n",
				Client->Uin,
				static_cast<UINT>(envelope.InnerLen),
				decodeError.c_str());
			return;
		}
		if (plainBody.size() < 26 ||
			fields.uin != Client->Uin ||
			fields.uin != envelope.OuterUin)
		{
			QQS_DebugPrintf10001(
				"[28346][138-REJECT] Uin=%u OuterUin=%u InnerUin=%u PlainLen=%zu Reason=validated-body-mismatch\n",
				Client->Uin,
				envelope.OuterUin,
				fields.uin,
				plainBody.size());
			return;
		}

		// 与直接 Msg138 分发保持相同门条件和传参位置：
		// 普通 Body 的 Uin/Time 后即为 StartSingleGame 所读的 TaskID/MapID。
		BYTE* singleTaskBody = plainBody.data() + 8;
		if (fields.taskId == 0x06A5)
		{
			if (plainBody.size() + sizeof(USHORT) >= 22)
				StartPurplePractice(Client, fields.mapId);
		}
		else
		{
			StartSingleGame(Client, singleTaskBody);
		}
		return;
	}

	if (envelope.InnerMsg == 271)
	{
		std::vector<std::uint8_t> plainBody;
		std::string decodeError;
		if (!QQSpeedMsg271::DecodeSafeRequestToPlain(
			envelope.InnerBody,
			envelope.InnerBodyLen,
			plainBody,
			&decodeError))
		{
			QQS_DebugPrintf10001(
				"[28346][271-REJECT] Uin=%u InnerLen=%u Reason=%s\n",
				Client->Uin,
				static_cast<UINT>(envelope.InnerLen),
				decodeError.c_str());
			return;
		}
		if (plainBody.size() != 8)
		{
			QQS_DebugPrintf10001(
				"[28346][271-REJECT] Uin=%u PlainLen=%zu Reason=plain-length-mismatch\n",
				Client->Uin,
				plainBody.size());
			return;
		}
		const UINT innerUin = QQS_ReadBE32(plainBody.data());
		if (innerUin != Client->Uin || innerUin != envelope.OuterUin)
		{
			QQS_DebugPrintf10001(
				"[28346][271-REJECT] Uin=%u OuterUin=%u InnerUin=%u Reason=inner-uin-mismatch\n",
				Client->Uin,
				envelope.OuterUin,
				innerUin);
			return;
		}
		RequestKartRefitInfo(
			Client, plainBody.data(), plainBody.size() + sizeof(USHORT));
		return;
	}

	if (envelope.InnerMsg == 24251)
	{
		std::vector<std::uint8_t> plainBody;
		std::string decodeError;
		if (!QQSpeedMsg24251::DecodeSafeRequestToPlain(
			envelope.InnerBody,
			envelope.InnerBodyLen,
			plainBody,
			&decodeError))
		{
			QQS_DebugPrintf10001(
				"[28346][24251-REJECT] Uin=%u InnerLen=%u Reason=%s\n",
				Client->Uin,
				static_cast<UINT>(envelope.InnerLen),
				decodeError.c_str());
			return;
		}
		if (plainBody.size() < 17)
		{
			QQS_DebugPrintf10001(
				"[28346][24251-REJECT] Uin=%u PlainLen=%zu Reason=plain-body-too-short\n",
				Client->Uin,
				plainBody.size());
			return;
		}
		const UINT innerUin =
			(static_cast<UINT>(plainBody[2]) << 24) |
			(static_cast<UINT>(plainBody[3]) << 16) |
			(static_cast<UINT>(plainBody[4]) << 8) |
			static_cast<UINT>(plainBody[5]);
		if (innerUin != Client->Uin || innerUin != envelope.OuterUin)
		{
			QQS_DebugPrintf10001(
				"[28346][24251-REJECT] Uin=%u OuterUin=%u InnerUin=%u Reason=inner-uin-mismatch\n",
				Client->Uin,
				envelope.OuterUin,
				innerUin);
			return;
		}
		RequestQuickRPC(Client, plainBody.data(), plainBody.size() + sizeof(USHORT));
		return;
	}

	if (envelope.InnerMsg != 437)
	{
		QQS_DebugPrintf10001(
			"[28346][REQUEST-REJECT] Uin=%u InnerMsg=%u InnerLen=%u Reason=unsupported-inner-msg\n",
			Client->Uin,
			static_cast<UINT>(envelope.InnerMsg),
			static_cast<UINT>(envelope.InnerLen));
		return;
	}

	int requestProtocolSeq = -1;
	if (!TryGetCurrentInboundProtocolSeq(Client, requestProtocolSeq))
	{
		QQS_DebugPrintf10001(
			"[INVENTORY][REQUEST-REJECT] Uin=%u Reason=missing-protocol-seq\n",
			Client->Uin);
		return;
	}
	// 官服 437/438 的 28346 外壳共用 request CSHEAD::Seq + 1
	// 作为 MSGHEAD::MsgSeq；CSHEAD::Seq 本身仍由发送层写 -1。
	const int responseWireMsgSeq =
		static_cast<int>(static_cast<UINT>(requestProtocolSeq) + 1u);

	std::vector<ItemInfo> dbItems;
	PlayerDB_LoginSelectItems(Client->Uin, dbItems);
	std::vector<ItemInfo> allItems = QQS_PrepareOfficialInventoryItems(Client, dbItems);
	if (allItems.size() > 0xFFFFu)
	{
		QQS_DebugPrintf10001(
			"[INVENTORY][REQUEST-REJECT] Uin=%u Items=%zu Reason=total-item-count-overflow\n",
			Client->Uin,
			allItems.size());
		return;
	}

	const USHORT totalItemNum = static_cast<USHORT>(allItems.size());
	const UINT responseTime = static_cast<UINT>(time(nullptr));
	size_t offset = 0;
	const size_t firstCount = (std::min)(kQQSOfficialInventoryPageLimit, allItems.size());
	std::vector<ItemInfo> firstPage(allItems.begin(), allItems.begin() + firstCount);
	offset += firstCount;
	if (!QQS_SendOfficialInventory28346(
			Client, 437, firstPage, offset < allItems.size(),
			totalItemNum, responseTime, responseWireMsgSeq))
		return;

	while (offset < allItems.size())
	{
		const size_t count = (std::min)(kQQSOfficialInventoryPageLimit, allItems.size() - offset);
		std::vector<ItemInfo> page(allItems.begin() + offset, allItems.begin() + offset + count);
		offset += count;
		if (!QQS_SendOfficialInventory28346(
				Client, 438, page, offset < allItems.size(),
				totalItemNum, responseTime, responseWireMsgSeq))
			return;
	}
}

struct QQSAuroraStorageConfig
{
	std::string Host;
	std::string PublicBaseUrl;
	std::string AuthInfo;
};

static int QQS_AuroraOperationalLog(const char* format, ...)
{
	char buffer[4096] = {};
	va_list arguments;
	va_start(arguments, format);
	const int written =
		vsnprintf(buffer, sizeof(buffer), format, arguments);
	va_end(arguments);
	buffer[sizeof(buffer) - 1u] = '\0';
	if (written < 0) return written;

	fputs(buffer, stdout);
	auto logger = spdlog::get("SpeedServer_logger");
	if (logger)
	{
		logger->info("{}", buffer);
		logger->flush();
	}
	return written;
}

static std::string QQS_StorageConfigPath()
{
	char executablePath[32768] = {};
	const DWORD pathLength = GetModuleFileNameA(
		nullptr, executablePath,
		static_cast<DWORD>(sizeof(executablePath)));
	if (pathLength == 0u ||
		pathLength >= static_cast<DWORD>(sizeof(executablePath)))
		return "mysql.ini";

	std::string path(executablePath, pathLength);
	const auto separator = path.find_last_of("\\/");
	if (separator == std::string::npos)
		return "mysql.ini";
	path.resize(separator + 1u);
	path += "mysql.ini";
	return path;
}

static bool QQS_LoadAuroraStorageConfig(
	std::uint8_t command,
	QQSAuroraStorageConfig& config,
	std::string& error)
{
	if (command != QQSpeedAuroraOfficial::kCosCommandRender &&
		command != QQSpeedAuroraOfficial::kCosCommandSettingsJson)
	{
		error = "unsupported Aurora COS command";
		return false;
	}

	struct CachedStorageConfig
	{
		std::once_flag Once;
		QQSAuroraStorageConfig Value;
		std::string Error;
		bool Ready = false;
	};
	static CachedStorageConfig cached;

	std::call_once(cached.Once, []() {
		const std::string path = QQS_StorageConfigPath();
		ini::iniReader reader;
		if (!reader.ReadConfig(path))
		{
			cached.Error = "mysql.ini could not be read: " + path;
			return;
		}

		cached.Value.Host = reader.ReadString(
			"aurora_storage", "upload_host", "");
		cached.Value.PublicBaseUrl = reader.ReadString(
			"aurora_storage", "public_base_url", "");
		cached.Value.AuthInfo = reader.ReadString(
			"aurora_storage", "upload_auth_info", "");

		if (cached.Value.Host.empty() ||
			cached.Value.Host.size() > 255u ||
			cached.Value.Host.find('/') != std::string::npos ||
			cached.Value.Host.find("://") != std::string::npos)
		{
			cached.Error =
				"aurora_storage.upload_host must be host[:port]";
			return;
		}
		if (cached.Value.PublicBaseUrl.empty() ||
			cached.Value.PublicBaseUrl.back() == '/' ||
			(cached.Value.PublicBaseUrl.rfind("https://", 0) != 0u &&
				cached.Value.PublicBaseUrl.rfind("http://", 0) != 0u))
		{
			cached.Error =
				"aurora_storage.public_base_url must be absolute "
				"without trailing slash";
			return;
		}
		if (cached.Value.AuthInfo.empty() ||
			cached.Value.AuthInfo.size() >
				(std::numeric_limits<std::uint16_t>::max)())
		{
			cached.Error =
				"aurora_storage.upload_auth_info is missing or too long";
			return;
		}
		cached.Ready = true;
		cached.Error = "ok";
	});

	if (!cached.Ready)
	{
		config = {};
		error = cached.Error;
		return false;
	}
	config = cached.Value;
	error = "ok";
	return true;
}

static void CompleteOfficialEscFlow(std::shared_ptr<ClientNode> Client, USHORT nextMsgID)
{
	if (!Client ||
		Client->OfficialEscPhase != QQS_OFFICIAL_ESC_PHASE_LEFT_AWAITING_NEXT)
	{
		return;
	}

	const bool expectedSingleNext =
		Client->OfficialEscFlowKind == QQS_OFFICIAL_ESC_FLOW_SINGLE_RETURN_ROOM &&
		nextMsgID == 103;
	const bool expectedMultiNext =
		(Client->OfficialEscFlowKind == QQS_OFFICIAL_ESC_FLOW_MULTI_RETURN_HALL ||
		 Client->OfficialEscFlowKind == QQS_OFFICIAL_ESC_FLOW_BORDER_RETURN_HALL) &&
		nextMsgID == 102;
	if (!expectedSingleNext && !expectedMultiNext)
		return;

	QQS_DebugPrintf10001("[FLOW][ESC-OFFICIAL-COMPLETE] Uin=%u Flow=%u OldRoomID=%u NextMsgID=%u Since105=%u\n",
		Client->Uin, (unsigned)Client->OfficialEscFlowKind,
		(unsigned)Client->OfficialEscRoomID, (unsigned)nextMsgID,
		Client->OfficialEscLast105Tick
			? (unsigned)(GetTickCount() - Client->OfficialEscLast105Tick)
			: 0);
	Client->OfficialEscFlowKind = QQS_OFFICIAL_ESC_FLOW_NONE;
	Client->OfficialEscPhase = QQS_OFFICIAL_ESC_PHASE_NONE;
	Client->OfficialEscStartedTick = 0;
	Client->OfficialEscLast105Tick = 0;
	Client->OfficialEscRoomID = 0;
	Client->OfficialEscBaseGameMode = 0;
	Client->OfficialEscSubGameMode = 0;
}


