void RequestGetTaskAwardInfo(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)

{

	BYTE* p = Body;



	UINT Uin = Read32(p);

	UINT Type = Read32(p);

	UINT TaskNum = Read32(p);

	std::vector<UINT> TaskList;

	for (size_t i = 0; i < TaskNum; i++)

	{

		TaskList.push_back(Read32(p));

	}



	UCHAR TaskStrNum = Read8(p);

	std::string TaskStr = ReadString(p, TaskStrNum);



	ResponseGetTaskAwardInfo(Client, Type, TaskList, TaskStr);

}

void ResponseGetTaskAwardInfo(std::shared_ptr<ClientNode> Client, UINT Type, std::vector<UINT> TaskList, std::string TaskStr)

{

	BYTE buf[8192]; BYTE* p = buf; size_t len;



	Write32(p, Client->Uin); //Uin

	Write16(p, 0); //ResultID

	Write32(p, Type); //Type

	WriteString_MC(p, TaskStr.c_str());

	Write32(p, TaskList.size()); //TaskInfoNum

	for (size_t i = 0; i < TaskList.size(); i++)

	{ //TaskAwardInfo

		BYTE* pTaskAwardInfo = p;

		Write16(pTaskAwardInfo, 0); //len



		Write32(pTaskAwardInfo, TaskList[i]); //TaskID

		Write32(pTaskAwardInfo, 0); //FirstAwardNum

		for (size_t i = 0; i < 0; i++)

		{ //TaskFirstAward

			BYTE* pTaskFirstAward = pTaskAwardInfo;

			Write16(pTaskFirstAward, 0); //len



			Write32(pTaskFirstAward, 0); //AwardMoney

			Write32(pTaskFirstAward, 0); //TotalMoney

			Write32(pTaskFirstAward, 0); //AwardSuperMoney

			Write32(pTaskFirstAward, 0); //TotalSuperMoney

			Write32(pTaskFirstAward, 0); //AwardExp

			Write32(pTaskFirstAward, 0); //TotalExp

			Write32(pTaskFirstAward, 0); //AwardItemNum

			for (size_t i = 0; i < 0; i++)

			{ //AwardItemInfo

				BYTE* pAwardItemInfo = pTaskFirstAward;

				Write16(pAwardItemInfo, 0); //len



				Write32(pAwardItemInfo, 0); //ItemID

				Write32(pAwardItemInfo, 0); //ItemNum

				Write32(pAwardItemInfo, 0); //AvailPeriod

				Write8(pAwardItemInfo, 0); //Status

				WriteUn(pAwardItemInfo, 0); //ObtainTime

				Write32(pAwardItemInfo, 0); //OtherAttribute

				Write16(pAwardItemInfo, 0); //ItemType



				len = pAwardItemInfo - pTaskFirstAward;

				Set16(pTaskFirstAward, (WORD)len);

				pTaskFirstAward += len;

			}

			Write32(pTaskFirstAward, 0); //AwardCoupons

			Write32(pTaskFirstAward, 0); //TotalCoupons

			Write32(pTaskFirstAward, 0); //AwardLuckMoney

			Write32(pTaskFirstAward, 0); //TotalLuckMoney

			Write32(pTaskFirstAward, 0); //AwardTeamWorkExp

			Write32(pTaskFirstAward, 0); //TotalTeamWorkExp

			Write32(pTaskFirstAward, 0); //AwardWlCash

			Write32(pTaskFirstAward, 0); //AwardWlCrystal

			Write32(pTaskFirstAward, 0); //AwardWlDegree

			Write32(pTaskFirstAward, 0); //ChumCircleActivity

			Write32(pTaskFirstAward, 0); //GuildScore

			Write16(pTaskFirstAward, 0); //AppellcationID

			Write16(pTaskFirstAward, 0); //ScoreJingJi

			Write8(pTaskFirstAward, 0); //ExtendInfoNum

			for (size_t i = 0; i < 0; i++)

			{ //ExtendInfoAward

				BYTE* pExtendInfoAward = pTaskFirstAward;

				Write16(pExtendInfoAward, 0); //len



				Write16(pExtendInfoAward, 0); //Key

				Write32(pExtendInfoAward, 0); //AddValue

				Write32(pExtendInfoAward, 0); //TotalValue

				Write8(pExtendInfoAward, 0); //ShowPriority

				Write16(pExtendInfoAward, 0); //BuyNeedScore

				Write8(pExtendInfoAward, 0); //OneMatchMaxNum



				len = pExtendInfoAward - pTaskFirstAward;

				Set16(pTaskFirstAward, (WORD)len);

				pTaskFirstAward += len;

			}

			Write32(pTaskFirstAward, 0); //LiveExp

			Write32(pTaskFirstAward, 0); //AwardSpeedCoin

			Write32(pTaskFirstAward, 0); //TotalSpeedCoin



			len = pTaskFirstAward - pTaskAwardInfo;

			Set16(pTaskAwardInfo, (WORD)len);

			pTaskAwardInfo += len;

		}

		Write32(pTaskAwardInfo, 0); //OtherAwardNum

		for (size_t i = 0; i < 0; i++)

		{ //TaskOtherAward

			BYTE* pTaskOtherAward = pTaskAwardInfo;

			Write16(pTaskOtherAward, 0); //len



			Write32(pTaskOtherAward, 0); //AwardMoney

			Write32(pTaskOtherAward, 0); //TotalMoney

			Write32(pTaskOtherAward, 0); //AwardSuperMoney

			Write32(pTaskOtherAward, 0); //TotalSuperMoney

			Write32(pTaskOtherAward, 0); //AwardExp

			Write32(pTaskOtherAward, 0); //TotalExp

			Write32(pTaskOtherAward, 0); //AwardItemNum

			for (size_t i = 0; i < 0; i++)

			{ //AwardItemInfo

				BYTE* pAwardItemInfo = pTaskOtherAward;

				Write16(pAwardItemInfo, 0); //len



				Write32(pAwardItemInfo, 0); //ItemID

				Write32(pAwardItemInfo, 0); //ItemNum

				Write32(pAwardItemInfo, 0); //AvailPeriod

				Write8(pAwardItemInfo, 0); //Status

				WriteUn(pAwardItemInfo, 0); //ObtainTime

				Write32(pAwardItemInfo, 0); //OtherAttribute

				Write16(pAwardItemInfo, 0); //ItemType



				len = pAwardItemInfo - pTaskOtherAward;

				Set16(pTaskOtherAward, (WORD)len);

				pTaskOtherAward += len;

			}

			Write32(pTaskOtherAward, 0); //AwardCoupons

			Write32(pTaskOtherAward, 0); //TotalCoupons

			Write32(pTaskOtherAward, 0); //AwardLuckMoney

			Write32(pTaskOtherAward, 0); //TotalLuckMoney

			Write32(pTaskOtherAward, 0); //AwardTeamWorkExp

			Write32(pTaskOtherAward, 0); //TotalTeamWorkExp

			Write32(pTaskOtherAward, 0); //AwardWlCash

			Write32(pTaskOtherAward, 0); //AwardWlCrystal

			Write32(pTaskOtherAward, 0); //AwardWlDegree

			Write32(pTaskOtherAward, 0); //ChumCircleActivity

			Write32(pTaskOtherAward, 0); //GuildScore

			Write16(pTaskOtherAward, 0); //AppellcationID

			Write16(pTaskOtherAward, 0); //ScoreJingJi

			Write8(pTaskOtherAward, 0); //ExtendInfoNum

			for (size_t i = 0; i < 0; i++)

			{ //ExtendInfoAward

				BYTE* pExtendInfoAward = pTaskOtherAward;

				Write16(pExtendInfoAward, 0); //len



				Write16(pExtendInfoAward, 0); //Key

				Write32(pExtendInfoAward, 0); //AddValue

				Write32(pExtendInfoAward, 0); //TotalValue

				Write8(pExtendInfoAward, 0); //ShowPriority

				Write16(pExtendInfoAward, 0); //BuyNeedScore

				Write8(pExtendInfoAward, 0); //OneMatchMaxNum



				len = pExtendInfoAward - pTaskOtherAward;

				Set16(pTaskOtherAward, (WORD)len);

				pTaskOtherAward += len;

			}

			Write32(pTaskOtherAward, 0); //LiveExp

			Write32(pTaskOtherAward, 0); //AwardSpeedCoin

			Write32(pTaskOtherAward, 0); //TotalSpeedCoin



			len = pTaskOtherAward - pTaskAwardInfo;

			Set16(pTaskAwardInfo, (WORD)len);

			pTaskAwardInfo += len;

		}

		Write32(pTaskAwardInfo, 0); //DBTaskInfoNum

		for (size_t i = 0; i < 0; i++)

		{ //DBTaskInfo

			BYTE* pDBTaskInfo = pTaskAwardInfo;

			Write16(pDBTaskInfo, 0); //len



			Write32(pDBTaskInfo, 0); //TaskID

			Write16(pDBTaskInfo, 0); //OptionID

			Write8(pDBTaskInfo, 0); //Status

			Write8(pDBTaskInfo, 0); //PrevStatus

			Write32(pDBTaskInfo, 0); //ProgressRate

			Write32(pDBTaskInfo, 0); //Other

			Write32(pDBTaskInfo, 0); //TakeTime

			Write32(pDBTaskInfo, 0); //LastUpdateTime



			len = pDBTaskInfo - pTaskAwardInfo;

			Set16(pTaskAwardInfo, (WORD)len);

			pTaskAwardInfo += len;

		}

		Write16(pTaskAwardInfo, 0); //FinTaskNeedNum

		Write8(pTaskAwardInfo, 0); //TaskParaToClientNum

		Write32(pTaskAwardInfo, 0); //TaskParaToClient[]



		len = pTaskAwardInfo - p;

		Set16(p, (WORD)len);

		p += len;

	}



	len = p - buf;

	SendToClient(Client, 28380, buf, len, Client->ConnID, FE_PLAYER, 1, Response);

}





void RequestPlayerActionPara(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)

{

	BYTE* pStart = Body;

	// OnRecvFromClient 传进来的 Body 指针已经跳过 MSGHEAD.BodyLen 这 2 字节，

	// 但 BodyLen 参数仍是 MSGHEAD.BodyLen 的值（包含这 2 字节）。

	// 真正 payload 长度必须减 2，避免按“抓包 body”再读一遍长度。

	size_t PayloadLen = (BodyLen >= sizeof(USHORT)) ? (BodyLen - sizeof(USHORT)) : BodyLen;

	BYTE* pEnd = pStart + PayloadLen;



	UINT DebugUin = (PayloadLen >= 4) ? Get32(pStart) : 0;

	if (QQS_ShouldPrintDebugUin10001(DebugUin))

	{

		printf("[24640] recv Uin=%u BodyLen=%zu hex head: ", DebugUin, BodyLen);

		for (size_t di = 0; di < 32 && di < PayloadLen; di++) printf("%02x", pStart[di]);

		printf("\n");

	}



	UINT Uin = Read32(Body);                // m_uiUin

	UINT ClientTick = Read32(Body);         // m_uiClientTick

	USHORT ActionType = Read16(Body);       // m_shActionType

	UINT Para0 = Read32(Body);              // m_iPara0

	UINT Para1 = Read32(Body);              // m_iPara1

	UINT Para2 = Read32(Body);              // m_iPara2

	UINT Para3 = Read32(Body);              // m_iPara3

	UINT Para4 = Read32(Body);              // m_iPara4



	// m_szPara0[25]

	BYTE n0 = (Body < pEnd) ? Read8(Body) : 0;

	if (n0 > 25) n0 = 25;

	Body += n0;



	// m_szPara1[25]

	BYTE n1 = (Body < pEnd) ? Read8(Body) : 0;

	if (n1 > 25) n1 = 25;

	Body += n1;



	// m_uiPara0 / m_uiPara1

	UINT UiPara0 = (Body + 4 <= pEnd) ? Read32(Body) : 0;

	UINT UiPara1 = (Body + 4 <= pEnd) ? Read32(Body) : 0;



	// m_aucClientFlag (u32 len + data)

	UINT clientFlagLen = (Body + 4 <= pEnd) ? Read32(Body) : 0;

	if (clientFlagLen > 0x1000) clientFlagLen = 0;

	Body += clientFlagLen;



	// m_uchUintArrayCount -> CommonParaArray (length-wrapped)

	if (Body < pEnd) {

		BYTE commonCount = Read8(Body);

		if (commonCount > 32) commonCount = 0;

		for (BYTE i = 0; i < commonCount && Body + 2 <= pEnd; i++) {

			USHORT cLen = Read16(Body);

			if (cLen < 2) break;

			Body += cLen - 2;

		}

	}



	// m_ucHasSpringPropData -> SpringPropData (length-wrapped)

	if (Body < pEnd) {

		BYTE springCount = Read8(Body);

		if (springCount > 1) springCount = 0;

		for (BYTE i = 0; i < springCount && Body + 2 <= pEnd; i++) {

			USHORT sLen = Read16(Body);

			if (sLen < 2) break;

			Body += sLen - 2;

		}

	}



	// m_ucHasCustomScheme -> CustomScheme (length-wrapped)

	bool hasCustom = false;

	std::vector<BYTE> schemeWire;

	BYTE allocSvr = 14;

	USHORT baseMode = 0, subMode = 0;

	BYTE roundNum = 0, mapNum = 0, n2oMode = 0;

	int n2oEffect = 100;

	BYTE collision = 0, gem = 1, costume = 0, modification = 1;

	BYTE smallSpray = 1, noCollisionSec = 5;

	UINT schemeID = 0;

	UINT mapList[3] = { 0, 0, 0 };



	if (Body < pEnd) {

		BYTE customCount = Read8(Body);

		if (customCount == 1 && Body + 2 <= pEnd) {

			USHORT wireLen = Read16(Body);           // nested len (bao han zi shen 2 zi jie)

			USHORT payloadLen = wireLen - 2;

			BYTE* wireStart = Body;



			if (Body + payloadLen <= pEnd) {

				schemeWire.assign(wireStart, wireStart + payloadLen);



				schemeID = Read32(Body);              // m_uiSchemeID: fang an ID

				Body += 0x80;                         // m_szSchemeName[128]: fang an ming cheng

				Read32(Body);                         // m_uiCreateTime: chuang jian shi jian

				Read32(Body);                         // m_uiUpdateTime: geng xin shi jian

				baseMode = Read16(Body);              // m_sBaseGameMode: ji chu mo shi

				subMode = Read16(Body);               // m_sSubGameMode: zi mo shi

				allocSvr = Read8(Body);               // m_ucAllocSvrType: fen pei fu wu qi lei xing

				Read8(Body);                          // m_ucEliminationIntervalTs: tao tai jian ge

				Read8(Body);                          // m_ucEliminationRanking: tao tai pai ming

				roundNum = Read8(Body);               // m_ucRoundNum: hui he shu

				n2oMode = Read8(Body);                // m_ucN2OMode: dan qi mo shi

				n2oEffect = (int)Read32(Body);        // m_iN2OEffect: ji qi xiao lv

				smallSpray = Read8(Body);             // m_ucSmallSpray: xiao pen

				collision = Read8(Body);              // m_ucCollision: peng zhuang

				gem = Read8(Body);                    // m_ucGem: bao shi

				costume = Read8(Body);                // m_ucCostume: shi zhuang

				modification = Read8(Body);           // m_ucModification: gai zhuang

				mapNum = Read8(Body);                 // m_ucMapNum: di tu shu liang

				mapList[0] = Read32(Body);            // m_aiMapIDList[0]: di tu 1

				mapList[1] = Read32(Body);            // m_aiMapIDList[1]: di tu 2

				mapList[2] = Read32(Body);            // m_aiMapIDList[2]: di tu 3



				// m_ucNoCollisionSeconds (extra byte if present)

				if (Body < wireStart + payloadLen)

					noCollisionSec = Read8(Body);



				Body = wireStart + payloadLen;

				hasCustom = true;

			}

		}

	}



	if (ActionType == 64) {

		bool updated = false;
		bool saved = false;

		if (Client && Para0 <= QQS_CLIENT_SAVED_FLAG_MAX_BIT) {

			const UINT byteIndex = Para0 >> 3;
			const BYTE bitMask = (BYTE)(1u << (Para0 & 7u));

			if (Para1 != 0)
				Client->ClientSavedFlags[byteIndex] |= bitMask;
			else
				Client->ClientSavedFlags[byteIndex] &= (BYTE)~bitMask;

			updated = true;
			saved = PlayerDB_UpdateClientSavedFlagHex(Client->Uin ? Client->Uin : Uin, Client->ClientSavedFlags, QQS_CLIENT_SAVED_FLAG_BYTES);

		}

		QQS_DebugPrintf10001("[24640] client saved flag AT=64 Uin=%u Para0=%u Para1=%u Updated=%u Saved=%u Byte0=0x%02X\n",
			Client ? Client->Uin : Uin, Para0, Para1, updated ? 1 : 0, saved ? 1 : 0,
			Client ? Client->ClientSavedFlags[0] : 0);

		if (Client)
			ResponsePlayerActionParaClientFlags(Client, ActionType, Para0, Para1, Para2, Para3, Para4, Client->ClientSavedFlags, QQS_CLIENT_SAVED_FLAG_BYTES);

		return;

	}



	// AT=62 同时用于普通查询和跑完回房事务。回房路径必须由显式事务判定：
	// normal: C24640 -> S504/S609 -> S24640 ACK；
	// custom/border: 104/500/504/609 -> C24640 -> S24640 ACK(no scheme)。
	// 不能再用 LastRoomReturnTick 的 60 秒窗口猜测，否则普通查询、赛道天梯或旧房间状态
	// 都可能被误判为赛后 ACK。

	if (ActionType == 62 && !hasCustom) {
		if (TryHandleOfficialRoomReturnAction62(Client))
			return;

		std::shared_ptr<RoomNode> Room = Client ? GetRoom(Client->RoomID) : nullptr;

		if (Room && IsTwelvePlayerRoom(Room))

			EnsureTwelvePlayerDefaultCustomScheme(Room, "24640-at62-seat12");

		if (Room && Room->HasCustomScheme && !Room->CustomSchemeWire.empty()) {

			NormalizeCustomSchemeForOfficial(Room, "24640-at62-restore");

			UINT restoreSchemeID = Room->CustomSchemeID ? Room->CustomSchemeID : 1;

			QQS_DebugPrintf10001("[24640] custom restore/query response AT=62 Uin=%u RoomID=%u SchemeID=%u CustomLen=%zu Map=[%u,%u,%u] SpeFlag=%u\n",

				Uin, Room->ID, restoreSchemeID, Room->CustomSchemeWire.size(),

				Room->CustomMapIDList[0], Room->CustomMapIDList[1], Room->CustomMapIDList[2], Room->SpeFlag);

			ResponsePlayerActionParaCustomScheme(Client, ActionType, restoreSchemeID, Room->CustomSchemeWire);

			return;

		}

	}



	if (hasCustom && (ActionType == 67 || ActionType == 69)) {

		std::shared_ptr<RoomNode> Room = GetRoom(Client->RoomID);

		if (Room) {

			// 客户端点“完成”(67)时常会把 SchemeID 发 0，服务端必须先分配

			// 一个有效 SchemeID，再写回 Room 和回包。否则 24640 响应里的

			// Para0 / CustomScheme.SchemeID 对不上，客户端 UI 不知道刷新哪个方案。

			if (schemeID == 0) {

				schemeID = Room->CustomSchemeID ? (Room->CustomSchemeID + 1) : 1;

			}

			// patch CustomSchemeWire 开头 4B SchemeID，大端序。

			if (schemeWire.size() >= 4) {

				schemeWire[0] = (BYTE)(schemeID >> 24);

				schemeWire[1] = (BYTE)(schemeID >> 16);

				schemeWire[2] = (BYTE)(schemeID >> 8);

				schemeWire[3] = (BYTE)(schemeID);

			}



			Room->HasCustomScheme = true;

			Room->SpeFlag = 9;

			Room->CustomSchemeID = schemeID;

			Room->CustomAllocSvrType = allocSvr;

			Room->CustomBaseGameMode = baseMode;

			Room->CustomSubGameMode = subMode;

			Room->CustomRoundNum = roundNum;

			Room->CustomN2OMode = n2oMode;

			Room->CustomN2OEffect = n2oEffect;

			Room->CustomSmallSpray = smallSpray;

			Room->CustomCollision = collision;

			Room->CustomGem = gem;

			Room->CustomCostume = costume;

			Room->CustomModification = modification;

			Room->CustomMapNum = (mapNum > 3) ? 3 : mapNum;

			Room->CustomNoCollisionSeconds = noCollisionSec;

			for (int i = 0; i < 3; i++)

				Room->CustomMapIDList[i] = mapList[i];

			Room->CustomSchemeWire = schemeWire;

			Room->CustomStageMapOrder[0] = 0;

			Room->CustomStageMapOrder[1] = 0;

			Room->CustomStageMapOrder[2] = 0;

			Room->CustomStageMapOrderNum = 0;

			Room->CustomStageMapSeed = 0;

			NormalizeCustomSchemeForOfficial(Room, "24640-apply");

			Room->CustomCurrentStageIndex = 0;

			Room->CustomLastFinishStageIndex = 0xFF;

			Room->CustomLastStageFinishTick = 0;



			for (int i = 0; i < 3; i++) {

				if (Room->CustomMapIDList[i] != 0) {

					Room->MapID = Room->CustomMapIDList[i];

					break;

				}

			}



			QQS_DebugPrintf10001("[24640] Uin=%u AT=%u Custom: SpeFlag=%u Base=%u Sub=%u RawRound=%u RawMap=[%u,%u,%u] NormRound=%u NormMapNum=%u NormMap=[%u,%u,%u] N2O=%d/%d RoomMap=%u\n",

				Uin, ActionType, Room->SpeFlag, baseMode, subMode, roundNum,

				mapList[0], mapList[1], mapList[2],

				Room->CustomRoundNum, Room->CustomMapNum,

				Room->CustomMapIDList[0], Room->CustomMapIDList[1], Room->CustomMapIDList[2],

				n2oMode, n2oEffect, Room->MapID);

		}



		// 24640 ActionType=67/69 只保存/确认当前自定义方案。

		// 不要在这里主动发 28460/28461，否则点“完成”会被客户端当成

		// “方案”按钮流程，弹出最近使用方案 UI。方案面板由客户端后续

		// 主动请求 28460 时再响应。

		{

			std::shared_ptr<RoomNode> Room = GetRoom(Client->RoomID);

			if (Room && Room->HasCustomScheme && !Room->CustomSchemeWire.empty()) {

				const UINT finalSchemeID = Room->CustomSchemeID ? Room->CustomSchemeID : schemeID;
				const int seatLimit = GetRoomSeatLimit(Room);
				const size_t playerSlots = Room->Player.size();
				int sent = 0;

				// AT=67/69 是房主“完成/确认”自定义方案。之前只回给发起者，
				// 已经在房内的其他客户端仍停留在 104 进房时的普通房状态
				// (SpeFlag=0/Custom=0)，后续服务端却按 SpeFlag=9 开局，
				// 会造成准备显示、120 加载 ready、跑图看人不完整不同步。
				for (int i = 0; i < seatLimit && (size_t)i < playerSlots; ++i) {
					std::shared_ptr<ClientNode> RoomClient = Room->Player[i];
					if (!RoomClient || RoomClient->deleteflag || !RoomClient->IsLogin || RoomClient->Uin == 0)
						continue;

					ResponsePlayerActionParaCustomScheme(RoomClient, ActionType, finalSchemeID, Room->CustomSchemeWire);
					++sent;
				}

				QQS_DebugPrintf10001("[24640] custom broadcast AT=%u FromUin=%u RoomID=%u SchemeID=%u Sent=%d SeatLimit=%d CustomLen=%zu\n",
					ActionType, Client ? Client->Uin : 0, Room->ID, finalSchemeID, sent, seatLimit, Room->CustomSchemeWire.size());

			}

			else

				ResponsePlayerActionParaCustomScheme(Client, ActionType, schemeID, schemeWire);

		}

	}

	else {

		if (!hasCustom && (ActionType == 67 || ActionType == 69)) {

			std::shared_ptr<RoomNode> Room = GetRoom(Client->RoomID);

			if (Room && IsTwelvePlayerRoom(Room)) {

				EnsureTwelvePlayerDefaultCustomScheme(Room, "24640-empty-apply-seat12-keep");

				QQS_DebugPrintf10001("[24640] keep 12P default custom on empty apply AT=%u Uin=%u RoomID=%u PayloadLen=%zu\n",

					ActionType, Uin, Room->ID, PayloadLen);

			}

			else if (Room && (Room->HasCustomScheme || Room->SpeFlag == 9)) {

				QQS_DebugPrintf10001("[24640] clear custom by empty apply AT=%u Uin=%u RoomID=%u PayloadLen=%zu\n",

					ActionType, Uin, Room->ID, PayloadLen);

				ClearCustomRoomState(Room, "24640-empty-apply");

			}

		}

		ResponsePlayerActionPara(Client, ActionType, Para0, Para1, Para2, Para3, Para4);

	}

}



void ResponsePlayerActionPara(std::shared_ptr<ClientNode> Client, USHORT ActionType, UINT Para0, UINT Para1, UINT Para2, UINT Para3, UINT Para4)

{

	BYTE buf[8192]; BYTE* p = buf; size_t len;



	Write32(p, Client->Uin);           // m_uiUin

	Write16(p, 0);                      // m_shResultID

	Write16(p, ActionType);             // m_shActionType

	Write32(p, Para0);                  // m_iPara0

	Write32(p, Para1);                  // m_iPara1

	Write32(p, Para2);                  // m_iPara2

	Write32(p, Para3);                  // m_iPara3

	Write32(p, Para4);                  // m_iPara4

	memset(p, 0, 25); p += 25;        // m_szPara0[25]

	memset(p, 0, 25); p += 25;        // m_szPara1[25]

	Write32(p, 0);                      // m_uiPara0

	Write32(p, 0);                      // m_uiPara1

	Write8(p, 0);                       // m_uchUintArrayCount: CommonPara shu liang

	Write8(p, 0);                       // m_ucHasSpringPropData: gai zhuang shu ju shu liang

	Write16(p, 0);                      // m_ucClientFlagLen: response is u16

	Write8(p, 0);                       // m_ucHasCustomScheme: 0=bu dai zi ding yi fang an

	len = p - buf;

	// SendToClient 会把 MSGHEAD.BodyLen 写成 len + 2；抓包里 body 开头的

	// 0x005D 就是这个 MSGHEAD.BodyLen。这里不能手写 WireLen，否则会重复。

	QQS_DebugPrintf10001("[24640] simple response Uin=%u AT=%u ResultID=0 Para=[%u,%u,%u,%u,%u] PayloadLen=%zu WireBodyLen=0x%04X\n",

		Client ? Client->Uin : 0, ActionType, Para0, Para1, Para2, Para3, Para4, len, (unsigned int)(len + 2));

	SendToClient(Client, 24640, buf, len, Client->ConnID, FE_PLAYER, 1, Response);

}

void ResponsePlayerActionParaClientFlags(std::shared_ptr<ClientNode> Client, USHORT ActionType, UINT Para0, UINT Para1, UINT Para2, UINT Para3, UINT Para4, const BYTE* ClientFlags, USHORT ClientFlagLen)

{

	if (!Client)
		return;

	if (!ClientFlags)
		ClientFlagLen = 0;

	if (ClientFlagLen > QQS_CLIENT_SAVED_FLAG_BYTES)
		ClientFlagLen = QQS_CLIENT_SAVED_FLAG_BYTES;

	BYTE buf[8192]; BYTE* p = buf; size_t len;



	Write32(p, Client->Uin);           // m_uiUin

	Write16(p, 0);                      // m_shResultID

	Write16(p, ActionType);             // m_shActionType

	Write32(p, Para0);                  // m_iPara0

	Write32(p, Para1);                  // m_iPara1

	Write32(p, Para2);                  // m_iPara2

	Write32(p, Para3);                  // m_iPara3

	Write32(p, Para4);                  // m_iPara4

	memset(p, 0, 25); p += 25;        // m_szPara0[25]

	memset(p, 0, 25); p += 25;        // m_szPara1[25]

	Write32(p, 0);                      // m_uiPara0

	Write32(p, 0);                      // m_uiPara1

	Write8(p, 0);                       // m_uchUintArrayCount: CommonPara shu liang

	Write8(p, 0);                       // m_ucHasSpringPropData: gai zhuang shu ju shu liang

	Write16(p, ClientFlagLen);          // m_ucClientFlagLen: response is u16

	if (ClientFlagLen > 0) {
		memcpy(p, ClientFlags, ClientFlagLen); // m_aucClientFlag
		p += ClientFlagLen;
	}

	Write8(p, 0);                       // m_ucHasCustomScheme: 0=bu dai zi ding yi fang an

	len = p - buf;

	QQS_DebugPrintf10001("[24640] client flag response Uin=%u AT=%u FlagLen=%u FirstBytes=%02X%02X%02X%02X PayloadLen=%zu WireBodyLen=0x%04X\n",

		Client ? Client->Uin : 0, ActionType, ClientFlagLen,
		(ClientFlagLen > 0) ? ClientFlags[0] : 0,
		(ClientFlagLen > 1) ? ClientFlags[1] : 0,
		(ClientFlagLen > 2) ? ClientFlags[2] : 0,
		(ClientFlagLen > 3) ? ClientFlags[3] : 0,
		len, (unsigned int)(len + 2));

	SendToClient(Client, 24640, buf, len, Client->ConnID, FE_PLAYER, 1, Response);

}



// zi ding yi wan fa xiang ying (dai CustomScheme)

void ResponsePlayerActionParaCustomScheme(

	std::shared_ptr<ClientNode> Client,

	USHORT ActionType,

	UINT schemeID,

	const std::vector<BYTE>& schemeWire)

{

	if (!Client || schemeWire.empty())

	{

		if (Client && QQS_ShouldPrintDebugUin10001(Client->Uin))

			printf("[24640] custom response skip Uin=%u AT=%u Client=%p CustomLen=%zu\n",

				Client->Uin, ActionType, Client.get(), schemeWire.size());

		return;

	}

	BYTE buf[8192]; BYTE* p = buf; size_t len;



	Write32(p, Client->Uin);           // m_uiUin

	Write16(p, 0);                      // m_shResultID: jie guo (0=cheng gong)

	Write16(p, ActionType);             // m_shActionType: dong zuo lei xing

	Write32(p, schemeID);               // m_iPara0: fang an ID (SchemeID)

	Write32(p, 0);                      // m_iPara1

	Write32(p, 0);                      // m_iPara2

	Write32(p, 0);                      // m_iPara3

	Write32(p, 0);                      // m_iPara4

	memset(p, 0, 25); p += 25;         // m_szPara0[25]: zi fu chuan can shu 0

	memset(p, 0, 25); p += 25;         // m_szPara1[25]: zi fu chuan can shu 1

	Write32(p, 0);                      // m_uiPara0

	Write32(p, 0);                      // m_uiPara1

	Write8(p, 0);                       // m_uchUintArrayCount: CommonPara shu liang

	Write8(p, 0);                       // m_ucHasSpringPropData: gai zhuang shu ju shu liang

	Write16(p, 0);                      // m_ucClientFlagLen: ke hu duan biao zhi chang du (xiang ying yong u16)

	Write8(p, 1);                       // m_ucHasCustomScheme: 1=dai zi ding yi fang an

	USHORT nestedLen = (USHORT)(schemeWire.size() + 2); // length-wrapped

	if (schemeWire.size() + 128 > sizeof(buf))

	{

		if (Client && QQS_ShouldPrintDebugUin10001(Client->Uin))

			printf("[24640] custom response skip Uin=%u AT=%u SchemeID=%u CustomLen=%zu exceeds buffer\n",

				Client->Uin, ActionType, schemeID, schemeWire.size());

		return;

	}

	Write16(p, nestedLen);              // CustomScheme nested chang du

	memcpy(p, schemeWire.data(), schemeWire.size());

	p += schemeWire.size();



	len = p - buf;



	if (Client && QQS_ShouldPrintDebugUin10001(Client->Uin))

	{

		printf("[24640] custom response Uin=%u AT=%u SchemeID=%u CustomLen=%zu PayloadLen=%zu WireBodyLen=%zu\n",

			Client->Uin, ActionType, schemeID, schemeWire.size(), len, len + 2);

		// debug: dump qian 40 zi jie

		printf("[24640] resp hex head Uin=%u: ", Client->Uin);

		for (size_t di = 0; di < 40 && di < len; di++) printf("%02x", buf[di]);

		printf("\n");

	}



	SendToClient(Client, 24640, buf, len, Client->ConnID, FE_PLAYER, 1, Response);

}



// 24640 简化响应：HasCustomScheme=0，不带 scheme 数据，body 固定 91B（不含 2B 长度前缀）。

// 21043 官方 pcap（8号老街）赛后回房 6P 自定义只发 1 次 AT=62 的这个最小响应。

// 客户端 scheme 信息已经在 104 自定义尾部传过，24640 在赛后回房只是确认动作类型，

// 不重复传 scheme，否则会触发客户端 UI 重建，破坏 104 已建立的 self.PlayerID 绑定。

void ResponsePlayerActionParaAck(std::shared_ptr<ClientNode> Client, USHORT ActionType)

{

	if (!Client)

		return;

	BYTE buf[256]; BYTE* p = buf; size_t len;



	Write32(p, Client->Uin);            // m_uiUin

	Write16(p, 0);                       // m_shResultID

	Write16(p, ActionType);              // m_shActionType

	Write32(p, 0);                       // m_iPara0（赛后回房 SchemeID 官方写 0，不是真实 schemeID）

	Write32(p, 0);                       // m_iPara1

	Write32(p, 0);                       // m_iPara2

	Write32(p, 0);                       // m_iPara3

	Write32(p, 0);                       // m_iPara4

	memset(p, 0, 25); p += 25;           // m_szPara0[25]

	memset(p, 0, 25); p += 25;           // m_szPara1[25]

	Write32(p, 0);                       // m_uiPara0

	Write32(p, 0);                       // m_uiPara1

	Write8(p, 0);                        // m_uchUintArrayCount

	Write8(p, 0);                        // m_ucHasSpringPropData

	Write16(p, 0);                       // m_ucClientFlagLen

	Write8(p, 0);                        // m_ucHasCustomScheme = 0（不带 scheme）



	len = p - buf;

	if (Client && QQS_ShouldPrintDebugUin10001(Client->Uin))

	{

		printf("[24640-ACK] Uin=%u AT=%u PayloadLen=%zu (no scheme, HasCustomScheme=0)\n",

			Client->Uin, ActionType, len);

	}

	SendToClient(Client, 24640, buf, len, Client->ConnID, FE_PLAYER, 1, Response);

}



// 28461 S2C: zi ding yi wan fa ke xuan di tu lie biao

// ge shi: u16 bufLen + u16 resultID + u8 count + count*u32 MapID

// guan fang gu ding fan hui 25 ge di tu, bu zu bu fen tian 0

void ResponseCustomSchemeMapList28461(std::shared_ptr<ClientNode> Client)

{

	BYTE buf[1024]; BYTE* p = buf; size_t len;



	Write16(p, 0);                      // m_shResultID: 0=cheng gong

	

	// ke xuan di tu lie biao (zui duo 25 ge)

	static const UINT CustomMaps[] = {

		467, 460, 415, 427, 396, 455, 390, 391, 392, 393,

		133, 456, 354, 449, 446, 360, 368, 305, 227, 277,

		153, 7, 387, 421, 342

	};

	constexpr BYTE mapCount = 25;

	Write8(p, mapCount);                // m_ucMapCount: di tu shu liang

	for (BYTE i = 0; i < mapCount; i++) {

		Write32(p, CustomMaps[i]);      // m_aiMapID[i]

	}

	// sheng yu tian 0 dao 128 ge cao wei (guan fang 517 zi jie)

	int remaining = 128 - mapCount;

	for (int i = 0; i < remaining; i++) {

		Write32(p, 0);

	}



	len = p - buf;

	SendToClient(Client, 28461, buf, len, Client->ConnID, FE_PLAYER, 1, Response);

}



// 28460 S2C: zi ding yi wan fa fang an lie biao

// ge shi: u16 bufLen + u16 resultID + u8 schemeCount + schemeCount*[u16 nestedLen + CustomSchemeWire]

void ResponseCustomSchemeList28460(std::shared_ptr<ClientNode> Client, std::shared_ptr<RoomNode> Room)

{

	BYTE buf[2048]; BYTE* p = buf; size_t len;



	Write16(p, 0);                      // m_shResultID: 0=cheng gong



	bool hasScheme = (Room && Room->HasCustomScheme && !Room->CustomSchemeWire.empty());

	if (hasScheme) {

		Write8(p, 1);                   // m_ucSchemeCount: fang an shu liang

		USHORT nestedLen = (USHORT)(Room->CustomSchemeWire.size() + 2);

		Write16(p, nestedLen);          // nested chang du (bao han zi shen 2B)

		memcpy(p, Room->CustomSchemeWire.data(), Room->CustomSchemeWire.size());

		p += Room->CustomSchemeWire.size();

	}

	else {

		Write8(p, 0);                   // m_ucSchemeCount: wu fang an

	}



	len = p - buf;

	SendToClient(Client, 28460, buf, len, Client->ConnID, FE_PLAYER, 1, Response);

}



void RequestC2GGetMapOwner(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)

{

	BYTE* p = Body;



	UINT Uin = Read32(p);

	UINT Time = Read32(p);

	USHORT MapID = Read16(p);

	bool Lastest = Read8(p);

	ResponseC2GGetMapOwner(Client, MapID);

}



void ResponseC2GGetMapOwner(std::shared_ptr<ClientNode> Client, UINT MapId)

{

	BYTE buf[8192]; BYTE* p = buf; size_t len;



	Write32(p, Client->Uin); //Uin

	Write16(p, MapId); //MapID

	{ //Brief

		BYTE* pBrief = p;

		Write16(pBrief, 0); //len



		Write16(pBrief, MapId); //MapID

		Write32(pBrief, 0); //ChallengeCnt

		Write16(pBrief, 0); //FreeRank

		Write32(pBrief, 0); //MaxFiniTime

		Write32(pBrief, 0); //MinFiniTime



		len = pBrief - p;

		Set16(p, (WORD)len);

		p += len;

	}

	Write8(p, 0); //HasOwner

	for (size_t i = 0; i < 0; i++)

	{ //MapOwner

		BYTE* pMapOwner = p;

		Write16(pMapOwner, 0); //len



		Write16(pMapOwner, 0); //Rank

		Write32(pMapOwner, 0); //Uin

		WriteString_MC(pMapOwner, "屌大"); //NameLen

		Write32(pMapOwner, 0); //GuildID

		Write8(pMapOwner, 0); //GuildNameLen

		Write32(pMapOwner, 0); //UseTime

		Write32(pMapOwner, 0); //KartID

		Write16(pMapOwner, 0); //UUidLen



		len = pMapOwner - p;

		Set16(p, (WORD)len);

		p += len;

	}



	len = p - buf;

	SendToClient(Client, 11216, buf, len, Client->ConnID, FE_PLAYER, 1, Response);

}



