struct SelectBox168Item
{
	UINT ItemID = 0;
	UINT ItemNum = 1;
	int AvailPeriod = 0;
	UINT ObtainTime = 0;
	BYTE Status = 0;
	UINT OtherAttribute = 0;
	USHORT ItemType = 0;
};

enum SB168OpenMode
{
	SB168_MODE_SELECT = 1,
	SB168_MODE_ALL = 2,
	SB168_MODE_RANDOM = 3
};

struct SelectBox168Pool
{
	UINT Seed = 0;
	USHORT ItemType = 0;
	std::vector<SelectBox168Item> Items;
};

struct SelectBox168Cfg
{
	UINT BoxID = 0;
	UINT BoxType = 3;
	USHORT MaxSelectNum = 1;
	int LuckyValue = 0;
	UINT ExtraItemID = 0;
	UINT ExtraItemNum = 0;
	int ExtraItemPeriod = 0;
	USHORT ExtraItemType = 2;
	SB168OpenMode OpenMode = SB168_MODE_SELECT;
	std::vector<SelectBox168Item> Items;
	std::vector<SelectBox168Pool> Pool;
};

struct SB168AwardIndexInfo
{
	BYTE AwardIdx = 0;
	UINT SelectedItemID = 0;
	WORD AwardLen = 0;
};

struct SB168OpenBoxRequest
{
	UINT Uin = 0;
	UINT Time = 0;
	UINT BoxID = 0;
	WORD KeyLen = 0;
	BYTE SpecialIdx = 0;
	BYTE Reserved0 = 0;
	BYTE Reserved1 = 0;
	BYTE Reserved2 = 0;
	USHORT MutiOpenNum = 0;
	USHORT OpenBoxSrcType = 0;
	BYTE SelectAwardNum = 0;
	UINT OpenCount = 1;
	size_t PayloadLen = 0;
	std::vector<SB168AwardIndexInfo> AwardIndexInfos;
};

static size_t SB168_PayloadLen(size_t BodyLen)
{
	// MSGHEAD.BodyLen 包含自身 2 字节，OnRecvFromClient 传入的 Body 已经跳过这 2 字节。
	return (BodyLen >= sizeof(USHORT)) ? (BodyLen - sizeof(USHORT)) : BodyLen;
}

static bool SB168_CanRead(const BYTE* p, const BYTE* end, size_t need)
{
	return p && end && p <= end && static_cast<size_t>(end - p) >= need;
}

static std::string SB168_Lower(std::string value)
{
	for (char& ch : value)
	{
		if (ch >= 'A' && ch <= 'Z') ch = static_cast<char>(ch - 'A' + 'a');
	}
	return value;
}

static bool SB168_YamlTryString(const YAML::Node& node, std::string& out)
{
	if (!node || !node.IsScalar()) return false;
	try
	{
		out = node.as<std::string>();
		return true;
	}
	catch (const std::exception&)
	{
		return false;
	}
}

static bool SB168_YamlStringAny(const YAML::Node& node, std::initializer_list<const char*> keys, std::string& out)
{
	for (const char* key : keys)
	{
		if (!key) continue;
		if (SB168_YamlTryString(node[key], out)) return true;
	}
	return false;
}

static bool SB168_YamlIntAnyExists(const YAML::Node& node, std::initializer_list<const char*> keys, int& out)
{
	for (const char* key : keys)
	{
		if (!key) continue;
		if (MCV_YamlTryInt(node[key], out)) return true;
	}
	return false;
}

static SB168OpenMode SB168_ParseOpenMode(const std::string& mode, SB168OpenMode fallback)
{
	const std::string value = SB168_Lower(mode);
	if (value == "select" || value == "choice" || value == "choose") return SB168_MODE_SELECT;
	if (value == "all" || value == "full") return SB168_MODE_ALL;
	if (value == "random" || value == "rand" || value == "pool") return SB168_MODE_RANDOM;
	return fallback;
}

static const char* SB168_OpenModeName(SB168OpenMode mode)
{
	switch (mode)
	{
	case SB168_MODE_SELECT: return "Select";
	case SB168_MODE_ALL: return "All";
	case SB168_MODE_RANDOM: return "Random";
	default: return "Unknown";
	}
}

static std::vector<std::string> SB168_ConfigPaths(UINT BoxID)
{
	const std::string fileName = std::to_string(BoxID) + ".yml";
	return {
		".\\Treasure\\168\\" + fileName,
		"..\\..\\Treasure\\168\\" + fileName,
		".\\x64\\Release\\Treasure\\168\\" + fileName
	};
}

static bool SB168_ParseItemNode(const YAML::Node& row, SelectBox168Item& item, USHORT defaultItemType = 0)
{
	item = SelectBox168Item();
	item.ItemType = defaultItemType;

	if (row.IsScalar())
	{
		int itemId = 0;
		if (!MCV_YamlTryInt(row, itemId) || itemId <= 0) return false;
		item.ItemID = (UINT)itemId;
		return true;
	}

	if (!row.IsMap()) return false;
	item.ItemID = (UINT)MCV_YamlIntAny(row, { "ItemId", "ItemID", "item_id", "id" }, 0);
	if (item.ItemID == 0) return false;

	int itemNum = MCV_YamlIntAny(row, { "ItemNum", "item_num", "num" }, 1);
	item.ItemNum = (UINT)(itemNum > 0 ? itemNum : 1);
	item.AvailPeriod = MCV_YamlIntAny(row, { "AvailPeriod", "avail_period", "Period", "period" }, 0);
	item.ObtainTime = (UINT)MCV_YamlIntAny(row, { "ObtainTime", "obtain_time" }, 0);
	item.Status = (BYTE)MCV_YamlIntAny(row, { "Status", "status" }, 0);
	item.OtherAttribute = (UINT)MCV_YamlIntAny(row, { "OtherAttribute", "other_attribute" }, 0);
	item.ItemType = (USHORT)MCV_YamlIntAny(row, { "ItemType", "item_type" }, defaultItemType);
	return true;
}

static void SB168_ParseItemsNode(const YAML::Node& itemsNode, std::vector<SelectBox168Item>& out, USHORT defaultItemType = 0)
{
	if (!itemsNode || !itemsNode.IsSequence()) return;
	for (size_t i = 0; i < itemsNode.size(); ++i)
	{
		SelectBox168Item item;
		if (SB168_ParseItemNode(itemsNode[i], item, defaultItemType))
		{
			if (item.ItemNum == 0) item.ItemNum = 1;
			out.push_back(item);
		}
	}
}

static void SB168_ParsePreviewNode(const YAML::Node& previewNode, SelectBox168Cfg& cfg)
{
	if (!previewNode || !previewNode.IsMap()) return;

	const int extraItemID = MCV_YamlIntAny(previewNode, { "ExtraItemID", "extra_item_id" }, (int)cfg.ExtraItemID);
	const int extraItemNum = MCV_YamlIntAny(previewNode, { "ExtraItemNum", "extra_item_num" }, (int)cfg.ExtraItemNum);
	const int extraItemType = MCV_YamlIntAny(previewNode, { "ExtraItemType", "extra_item_type" }, (int)cfg.ExtraItemType);
	if (extraItemID < 0 || extraItemNum < 0 || extraItemType < 0 || extraItemType > (std::numeric_limits<USHORT>::max)())
	{
		throw std::runtime_error("invalid Box168 Preview config");
	}

	cfg.ExtraItemID = (UINT)extraItemID;
	cfg.ExtraItemNum = (UINT)extraItemNum;
	cfg.ExtraItemPeriod = MCV_YamlIntAny(previewNode, { "ExtraItemPeriod", "extra_item_period" }, cfg.ExtraItemPeriod);
	cfg.ExtraItemType = (USHORT)extraItemType;
}

static bool SB168_LoadRockPartyCfg(
	UINT BoxID,
	SelectBox168Cfg& cfg,
	std::string* usedPath)
{
	const char* paths[] = {
		".\\24251\\RockParty.yml",
		".\\bin\\24251\\RockParty.yml"
	};
	for (const char* path : paths)
	{
		try
		{
			if (!std::filesystem::exists(path)) continue;
			const YAML::Node file = YAML::LoadFile(path);
			const YAML::Node root = file["rock_party"];
			if (!root || !root.IsMap()) continue;
			bool activityEnabled = false;
			if (!MCV_YamlTryBool(root["enabled"], activityEnabled) ||
				!activityEnabled)
			{
				continue;
			}
			const YAML::Node draw = root["draw"];
			const UINT configuredBoxID = static_cast<UINT>(
				MCV_YamlIntAny(
					draw,
					{ "box_item_id" },
					MCV_YamlIntAny(
						root["shop"],
						{ "commodity_id" },
						0)));
			if (configuredBoxID == 0 || configuredBoxID != BoxID) continue;

			const YAML::Node rows = root["pool"]["items"];
			if (!rows || !rows.IsSequence() || rows.size() == 0) continue;
			std::uint64_t totalWeight = 0;
			for (size_t i = 0; i < rows.size(); ++i)
			{
				const int weight =
					MCV_YamlIntAny(rows[i], { "weight" }, 0);
				if (weight <= 0)
				throw std::runtime_error("invalid RockParty pool weight");
				totalWeight += static_cast<UINT>(weight);
			}
			if (totalWeight == 0) continue;

			SelectBox168Cfg parsed;
			parsed.BoxID = configuredBoxID;
			parsed.BoxType = 9;
			parsed.OpenMode = SB168_MODE_RANDOM;
			parsed.LuckyValue = 0;
			YAML::Node previewNode = root["Preview"] ? root["Preview"] : root["preview"];
			SB168_ParsePreviewNode(previewNode, parsed);
			std::uint64_t cumulativeWeight = 0;
			for (size_t i = 0; i < rows.size(); ++i)
			{
				SelectBox168Item item;
				if (!SB168_ParseItemNode(rows[i], item, 0))
					throw std::runtime_error("invalid RockParty pool item");
				const int weight =
					MCV_YamlIntAny(rows[i], { "weight" }, 0);
				cumulativeWeight += static_cast<UINT>(weight);
				SelectBox168Pool pool;
				pool.Seed = static_cast<UINT>(
					(cumulativeWeight * 10000000ULL + totalWeight - 1) /
					totalWeight);
				if (i + 1 == rows.size()) pool.Seed = 10000000;
				pool.ItemType = item.ItemType;
				pool.Items.push_back(item);
				parsed.Pool.push_back(std::move(pool));
			}
			cfg = std::move(parsed);
			if (usedPath) *usedPath = path;
			return true;
		}
		catch (const std::exception& e)
		{
			if (ShouldPrintDebugForUin10001(SystemClient))
			{
				printf(
					"[RockParty] load box cfg error path=%s err=%s\n",
					path,
					e.what());
			}
		}
	}
	return false;
}

static bool SB168_LoadCfg(UINT BoxID, SelectBox168Cfg& cfg, std::string* usedPath = nullptr)
{
	for (const std::string& path : SB168_ConfigPaths(BoxID))
	{
		try
		{
			if (!std::filesystem::exists(path)) continue;
			YAML::Node file = YAML::LoadFile(path);
			YAML::Node root = file["Box168"] ? file["Box168"] : file;
			root = root["box168"] ? root["box168"] : root;

			SelectBox168Cfg parsed;
			parsed.BoxID = (UINT)MCV_YamlIntAny(root, { "BoxID", "BoxId", "box_id" }, (int)BoxID);

			int boxType = 0;
			const bool hasBoxType = SB168_YamlIntAnyExists(root, { "BoxType", "box_type" }, boxType);
			std::string modeText;
			const bool hasOpenMode = SB168_YamlStringAny(root, { "OpenMode", "open_mode", "Mode", "mode" }, modeText);

			YAML::Node itemsNode = root["Items"] ? root["Items"] : root["items"];
			YAML::Node poolNode = root["Pool"] ? root["Pool"] : root["pool"];

			SB168OpenMode inferredMode = SB168_MODE_SELECT;
			if (poolNode && poolNode.IsSequence()) inferredMode = SB168_MODE_RANDOM;
			else if (hasBoxType && boxType == 0) inferredMode = SB168_MODE_ALL;
			else inferredMode = SB168_MODE_SELECT;
			parsed.OpenMode = hasOpenMode ? SB168_ParseOpenMode(modeText, inferredMode) : inferredMode;

			parsed.BoxType = hasBoxType ? (UINT)boxType : (parsed.OpenMode == SB168_MODE_SELECT ? 3 : 0);
			int maxSelect = MCV_YamlIntAny(root, { "MaxSelectNum", "max_select_num" }, 1);
			parsed.MaxSelectNum = (USHORT)(maxSelect > 0 ? maxSelect : 1);
			parsed.LuckyValue = MCV_YamlIntAny(root, { "LuckyValue", "lucky_value" }, 0);
			if (parsed.LuckyValue < 0) throw std::runtime_error("invalid Box168 LuckyValue");
			YAML::Node previewNode = root["Preview"] ? root["Preview"] : root["preview"];
			SB168_ParsePreviewNode(previewNode, parsed);

			SB168_ParseItemsNode(itemsNode, parsed.Items, 0);

			if (poolNode && poolNode.IsSequence())
			{
				for (size_t i = 0; i < poolNode.size(); ++i)
				{
					YAML::Node row = poolNode[i];
					if (!row || !row.IsMap()) continue;
					SelectBox168Pool pool;
					pool.Seed = (UINT)MCV_YamlIntAny(row, { "Seed", "seed" }, 0);
					pool.ItemType = (USHORT)MCV_YamlIntAny(row, { "ItemType", "item_type" }, 0);
					YAML::Node poolItems = row["Items"] ? row["Items"] : row["items"];
					SB168_ParseItemsNode(poolItems, pool.Items, pool.ItemType);
					if (pool.Seed > 0 && !pool.Items.empty()) parsed.Pool.push_back(pool);
				}
			}

			if (parsed.BoxID == 0) parsed.BoxID = BoxID;
			if (parsed.OpenMode == SB168_MODE_RANDOM)
			{
				if (parsed.Pool.empty()) continue;
			}
			else
			{
				if (parsed.Items.empty()) continue;
			}

			cfg = parsed;
			if (usedPath) *usedPath = path;
			return true;
		}
		catch (const std::exception& e)
		{
			if (ShouldPrintDebugForUin10001(SystemClient))
			{
				printf("[Box168] load cfg error path=%s err=%s\n", path.c_str(), e.what());
			}
		}
	}
	return SB168_LoadRockPartyCfg(BoxID, cfg, usedPath);
}

static bool SB168_LoadLegacyPreviewCfg(UINT BoxID, SelectBox168Cfg& cfg, std::string* usedPath)
{
	TREASUREBOX* legacy = GetTreasureBox(BoxID);
	if (!legacy || legacy->TreasureAwards.empty()) return false;

	SelectBox168Cfg parsed;
	parsed.BoxID = BoxID;
	parsed.BoxType = 0;
	parsed.OpenMode = SB168_MODE_RANDOM;
	parsed.LuckyValue = legacy->LuckyValue;
	parsed.ExtraItemID = legacy->ExtraItemID;
	parsed.ExtraItemNum = legacy->ExtraItemNum;
	parsed.ExtraItemPeriod = legacy->ExtraItemPeriod;
	parsed.ExtraItemType = legacy->ExtraItemType;

	for (const TREASUREAWARD& legacyPool : legacy->TreasureAwards)
	{
		SelectBox168Pool pool;
		pool.Seed = legacyPool.Seed;
		pool.ItemType = (USHORT)legacyPool.ItemType;
		for (const ItemInfo& legacyItem : legacyPool.AwardItems)
		{
			if (legacyItem.ItemID == 0) continue;
			SelectBox168Item item;
			item.ItemID = legacyItem.ItemID;
			item.ItemNum = legacyItem.ItemNum > 0 ? (UINT)legacyItem.ItemNum : 1;
			item.AvailPeriod = legacyItem.AvailPeriod;
			item.ObtainTime = legacyItem.ObtainTime > 0 ? (UINT)legacyItem.ObtainTime : 0;
			item.Status = legacyItem.Status ? 1 : 0;
			item.OtherAttribute = legacyItem.OtherAttribute > 0 ? (UINT)legacyItem.OtherAttribute : 0;
			item.ItemType = pool.ItemType;
			pool.Items.push_back(item);
		}
		if (!pool.Items.empty()) parsed.Pool.push_back(std::move(pool));
	}

	if (parsed.Pool.empty()) return false;
	cfg = std::move(parsed);
	if (usedPath) *usedPath = ".\\Treasure\\" + std::to_string(BoxID) + ".yml";
	return true;
}

static const SelectBox168Item* SB168_FindItem(const SelectBox168Cfg& cfg, UINT ItemID)
{
	for (const SelectBox168Item& item : cfg.Items)
	{
		if (item.ItemID == ItemID) return &item;
	}
	return nullptr;
}

static void SB168_WriteKey(BYTE*& p)
{
	BYTE* pKey = p;
	Write16(p, 0); // len
	Write32(p, 0); // KeyType
	Write8(p, 0);  // IsNotConsume
	Set16(pKey, (WORD)(p - pKey)); // 官方无钥匙结构长度为 7
}

static void SB168_WriteItemInfo(BYTE*& p, const SelectBox168Item& item, bool useCurrentTime)
{
	BYTE* pItemInfo = p;
	Write16(p, 0); // len
	Write32(p, item.ItemID);
	Write32(p, item.ItemNum ? item.ItemNum : 1);
	Write32(p, item.AvailPeriod);
	Write8(p, item.Status);
	Write32(p, item.ObtainTime ? item.ObtainTime : (useCurrentTime ? (UINT)time(0) : 0));
	Write32(p, item.OtherAttribute);
	Write16(p, item.ItemType);
	Set16(pItemInfo, (WORD)(p - pItemInfo));
}

static void SB168_WriteAwardEntry(BYTE*& p, const std::vector<SelectBox168Item>& items, bool useCurrentTime)
{
	BYTE* pAwardEntry = p;
	Write16(p, 0); // len
	Write32(p, 0); // Exp
	Write32(p, 0); // Money
	Write32(p, 0); // SuperMoney
	Write16(p, (USHORT)items.size()); // ItemNum
	for (const SelectBox168Item& item : items)
	{
		SB168_WriteItemInfo(p, item, useCurrentTime);
	}
	Write32(p, 0); // Coupons
	Write32(p, 0); // GuildPoint
	Write32(p, 0); // LuckMoney
	Write8(p, 0);  // ExtendInfoNum
	Write32(p, 0); // SpeedCoin
	Set16(pAwardEntry, (WORD)(p - pAwardEntry));
}

static void SB168_WriteTreasureBoxToClient(BYTE*& p, const SelectBox168Cfg& cfg, const std::vector<SelectBox168Item>& items, bool useCurrentTime)
{
	BYTE* pBox = p;
	Write16(p, 0); // len
	Write32(p, cfg.BoxID);
	Write32(p, cfg.BoxType);
	SB168_WriteKey(p);
	SB168_WriteAwardEntry(p, items, useCurrentTime);
	Set16(pBox, (WORD)(p - pBox));
}

static void SB168_ResponseGetBoxItems(std::shared_ptr<ClientNode> Client, const SelectBox168Cfg& cfg, USHORT Context = 0)
{
	if (!Client) return;
	std::vector<BYTE> buf(819200);
	BYTE* p = buf.data();
	Write16(p, 0); // ResultID
	Write32(p, Client->Uin);
	SB168_WriteTreasureBoxToClient(p, cfg, cfg.Items, true);
	Write16(p, cfg.MaxSelectNum); // maxSelectNum
	Write16(p, Context); // Context
	Write32(p, 0); // OpenDate
	Write32(p, 0); // CloseDate
	Write32(p, 0); // OpenTime
	Write32(p, 0); // CloseTime
	const size_t len = p - buf.data();
	SendToClient(Client, 190, buf.data(), (DWORD)len, Client->ConnID, FE_PLAYER, 1, Response);
}

static void SB168_ResponseOpenBox(std::shared_ptr<ClientNode> Client, const SelectBox168Cfg& cfg, const std::vector<SelectBox168Item>& awards)
{
	if (!Client) return;
	std::vector<BYTE> buf(819200);
	BYTE* p = buf.data();
	Write16(p, 0); // ResultID
	Write32(p, Client->Uin);
	SB168_WriteTreasureBoxToClient(p, cfg, awards, true);
	Write8(p, 0); // ReasonLen
	UINT reserve = (cfg.OpenMode == SB168_MODE_SELECT) ? (UINT)(cfg.MaxSelectNum ? cfg.MaxSelectNum : 1) : (UINT)awards.size();
	Write32(p, reserve ? reserve : 1); // Reserve
	Write32(p, 0); // MaxLuckValue
	Write32(p, 0); // LuckValue
	Write32(p, 0); // TotalLuckValue
	Write32(p, 0); // OpenDate
	Write32(p, 0); // CloseDate
	Write32(p, 0); // OpenTime
	Write32(p, 0); // CloseTime
	const size_t len = p - buf.data();
	SendToClient(Client, 168, buf.data(), (DWORD)len, Client->ConnID, FE_PLAYER, 1, Response);
}

static bool SB168_LoadLuckyValue(std::shared_ptr<ClientNode> Client, UINT BoxID, int& luckyValue)
{
	if (!Client) return false;
	luckyValue = -1;
	try
	{
		DBConnection myDBConnection(player);
		auto conn = myDBConnection.getConnection();
		if (!conn) return false;
		{
			std::unique_ptr<sql::PreparedStatement> prep_stmt(conn->prepareStatement("select LuckyValue from TreasureLuckyInfo where Uin=? and ItemID=?;"));
			prep_stmt->clearParameters();
			prep_stmt->setUInt(1, Client->Uin);
			prep_stmt->setUInt(2, BoxID);
			std::unique_ptr<sql::ResultSet> res(prep_stmt->executeQuery());
			while (res->next()) luckyValue = res->getUInt("LuckyValue");
		}
		if (luckyValue == -1)
		{
			luckyValue = 0;
			std::unique_ptr<sql::PreparedStatement> prep_stmt(conn->prepareStatement("INSERT INTO TreasureLuckyInfo(Uin,ItemID) VALUES(?, ?);"));
			prep_stmt->clearParameters();
			prep_stmt->setUInt(1, Client->Uin);
			prep_stmt->setUInt(2, BoxID);
			prep_stmt->executeUpdate();
		}
		return true;
	}
	catch (const std::exception& e)
	{
		printf("SB168_LoadLuckyValue Error: %s\n", e.what());
		return false;
	}
}

static bool SB168_SaveLuckyValue(std::shared_ptr<ClientNode> Client, UINT BoxID, int luckyValue)
{
	if (!Client) return false;
	try
	{
		DBConnection myDBConnection(player);
		auto conn = myDBConnection.getConnection();
		if (!conn) return false;
		std::unique_ptr<sql::PreparedStatement> prep_stmt(conn->prepareStatement("UPDATE TreasureLuckyInfo SET LuckyValue=? WHERE Uin=? AND ItemID=?;"));
		prep_stmt->clearParameters();
		prep_stmt->setUInt(1, luckyValue);
		prep_stmt->setUInt(2, Client->Uin);
		prep_stmt->setUInt(3, BoxID);
		prep_stmt->executeUpdate();
		return true;
	}
	catch (const std::exception& e)
	{
		printf("SB168_SaveLuckyValue Error: %s\n", e.what());
		return false;
	}
}

static bool SB168_RollRandomAwards(std::shared_ptr<ClientNode> Client, const SelectBox168Cfg& cfg, UINT openCount, std::vector<SelectBox168Item>& awards)
{
	if (cfg.Pool.empty()) return false;
	int luckyValue = 0;
	if (!SB168_LoadLuckyValue(Client, cfg.BoxID, luckyValue)) return false;

	static thread_local std::mt19937_64 rng(std::random_device{}());
	std::uniform_int_distribution<UINT> seedDistribution(1u, 10000000u);
	const UINT count = openCount ? openCount : 1;
	for (UINT j = 0; j < count; ++j)
	{
		bool pity = false;
		size_t poolIndex = 0;
		if (cfg.LuckyValue > 0 && luckyValue >= cfg.LuckyValue)
		{
			pity = true;
			poolIndex = 0;
		}
		else
		{
			const UINT seed = seedDistribution(rng);
			poolIndex = cfg.Pool.size() - 1;
			for (size_t i = 0; i < cfg.Pool.size(); ++i)
			{
				if (cfg.Pool[i].Seed >= seed)
				{
					poolIndex = i;
					break;
				}
			}
		}

		const SelectBox168Pool& pool = cfg.Pool[poolIndex];
		if (pool.Items.empty()) continue;
		std::uniform_int_distribution<size_t> itemDistribution(0, pool.Items.size() - 1);
		SelectBox168Item award = pool.Items[itemDistribution(rng)];
		if (award.ItemType == 0) award.ItemType = pool.ItemType;
		awards.push_back(award);

		if (pity) luckyValue = 0;
		else luckyValue++;
	}

	SB168_SaveLuckyValue(Client, cfg.BoxID, luckyValue);
	return !awards.empty();
}
static std::vector<SelectBox168Item> SB168_BuildAllAwards(const SelectBox168Cfg& cfg, UINT openCount)
{
	std::vector<SelectBox168Item> awards = cfg.Items;
	const UINT count = openCount ? openCount : 1;
	if (count > 1)
	{
		for (SelectBox168Item& item : awards)
		{
			item.ItemNum = (item.ItemNum ? item.ItemNum : 1) * count;
		}
	}
	return awards;
}

static ItemInfo SB168_ToNotifyItem(const SelectBox168Item& award, UINT finalNum)
{
	ItemInfo notify = { 0 };
	notify.ItemID = award.ItemID;
	notify.ItemNum = finalNum ? finalNum : (award.ItemNum ? award.ItemNum : 1);
	notify.AvailPeriod = award.AvailPeriod;
	notify.ObtainTime = award.ObtainTime;
	notify.Status = award.Status;
	notify.OtherAttribute = award.OtherAttribute;
	notify.ItemType = award.ItemType;
	return notify;
}

static void SB168_ResponseSelOptBoxAward(std::shared_ptr<ClientNode> Client, USHORT ResultID)
{
	if (!Client) return;
	BYTE buf[16] = { 0 };
	BYTE* p = buf;
	Write16(p, ResultID);
	const size_t len = p - buf;
	SendToClient(Client, 616, buf, (DWORD)len, Client->ConnID, FE_PLAYER, 1, Response);
}

static void SB168_NotifySelOptBoxAward(std::shared_ptr<ClientNode> Client, UINT BoxID, const ItemInfo& item, bool TimeOutSel = false)
{
	if (!Client) return;
	BYTE buf[64] = { 0 };
	BYTE* p = buf;
	Write32(p, BoxID); // BoxID
	// CNotifySelOptBoxAward: BoxID + DBItemInfo + TimeOutSel. DBItemInfo here has no nested len.
	Write32(p, item.ItemID);
	Write32(p, (DWORD)item.ItemNum);
	Write32(p, (DWORD)item.AvailPeriod);
	Write8(p, item.Status ? 1 : 0);
	Write32(p, (DWORD)(item.ObtainTime ? item.ObtainTime : (int)time(0)));
	Write32(p, (DWORD)item.OtherAttribute);
	Write16(p, (WORD)item.ItemType);
	Write8(p, TimeOutSel ? 1 : 0);
	const size_t len = p - buf;
	SendToClient(Client, 617, buf, (DWORD)len, Client->ConnID, FE_PLAYER, 1, Notify);
}

static bool SB168_SelectAwardByIndexOrItemID(const SelectBox168Cfg& cfg, int SelIdx, SelectBox168Item& award, int* resolvedIndex = nullptr)
{
	if (resolvedIndex) *resolvedIndex = -1;
	if (SelIdx >= 0 && (size_t)SelIdx < cfg.Items.size())
	{
		award = cfg.Items[(size_t)SelIdx];
		if (resolvedIndex) *resolvedIndex = SelIdx;
		return true;
	}

	if (SelIdx > 0)
	{
		const UINT rawItemID = (UINT)SelIdx;
		for (size_t i = 0; i < cfg.Items.size(); ++i)
		{
			if (cfg.Items[i].ItemID == rawItemID)
			{
				award = cfg.Items[i];
				if (resolvedIndex) *resolvedIndex = (int)i;
				return true;
			}
		}
	}
	return false;
}

static bool SB168_GrantAwards(std::shared_ptr<ClientNode> Client, const SelectBox168Cfg& cfg, const std::vector<SelectBox168Item>& awards, UINT consumeNum)
{
	if (!Client || awards.empty()) return false;
	const UINT costNum = consumeNum ? consumeNum : 1;
	const int haveNum = PlayerDB_GetItemNum(Client->Uin, cfg.BoxID);
	if (ShouldPrintDebugForUin10001(Client))
	{
		printf("[Box168][Grant] Uin=%u BoxID=%u Mode=%s Have=%d Cost=%u Awards=%zu Branch=168-select\n", Client->Uin, cfg.BoxID, SB168_OpenModeName(cfg.OpenMode), haveNum, costNum, awards.size());
		fflush(stdout);
	}
	if (haveNum < (int)costNum)
	{
		if (ShouldPrintDebugForUin10001(Client))
		{
			printf("[Box168][168-fail] Uin=%u BoxID=%u OpenCount=%u SelectAwardNum=%zu AwardIdx=0 SelectedItemID=0 Have=%d Cost=%u Branch=insufficient-box Reason=insufficient-box\n",
				Client->Uin, cfg.BoxID, costNum, awards.size(), haveNum, costNum);
			fflush(stdout);
		}
		ResponseStartGame(Client, "\xBA\xD0\xD7\xD3\xB1\xD8\xD0\xEB\xC1\xF4\xD2\xBB\xB8\xF6\xD3\xB4\xB1\xA6\xB1\xB4\x21");
		return false;
	}

	NotifyUseItemResult2(Client, (int)cfg.BoxID, (int)costNum);

	std::vector<ItemInfo> notifyItems;
	notifyItems.reserve(awards.size());
	for (const SelectBox168Item& award : awards)
	{
		const UINT baseNum = award.ItemNum ? award.ItemNum : 1;
		const UINT addNum = (cfg.OpenMode == SB168_MODE_SELECT && costNum > 1) ? (baseNum * costNum) : baseNum;
		int finalNum = PlayerDB_AddItem2(Client, Client->Uin, award.ItemID, addNum, award.AvailPeriod, award.Status != 0);
		notifyItems.push_back(SB168_ToNotifyItem(award, finalNum > 0 ? (UINT)finalNum : addNum));
	}

	NotifyClientAddItem(Client, (UINT)notifyItems.size(), notifyItems);
	if (ShouldPrintDebugForUin10001(Client))
	{
		printf("[Box168][168-success] Uin=%u BoxID=%u OpenCount=%u SelectAwardNum=%zu Have=%d Cost=%u Branch=success NotifyItems=%zu\n",
			Client->Uin, cfg.BoxID, costNum, awards.size(), haveNum, costNum, notifyItems.size());
		fflush(stdout);
	}
	return true;
}


static std::vector<SelectBox168Item> SB168_BuildPreviewItems(const SelectBox168Cfg& cfg)
{
	std::vector<SelectBox168Item> preview;
	auto appendUnique = [&preview](const SelectBox168Item& item)
	{
		for (const SelectBox168Item& old : preview)
		{
			if (old.ItemID == item.ItemID &&
				old.ItemNum == item.ItemNum &&
				old.AvailPeriod == item.AvailPeriod &&
				old.ItemType == item.ItemType)
			{
				return;
			}
		}
		preview.push_back(item);
	};

	if (cfg.OpenMode == SB168_MODE_RANDOM)
	{
		for (const SelectBox168Pool& pool : cfg.Pool)
		{
			for (const SelectBox168Item& item : pool.Items)
			{
				appendUnique(item);
			}
		}
	}
	else
	{
		for (const SelectBox168Item& item : cfg.Items) appendUnique(item);
	}

	// 官服 msg313 按稀有(2) -> 极品(1) -> 普通(0)排列，同级保持配置顺序。
	std::stable_sort(preview.begin(), preview.end(), [](const SelectBox168Item& lhs, const SelectBox168Item& rhs)
	{
		auto rank = [](USHORT itemType)
		{
			switch (itemType)
			{
			case 2: return 0;
			case 1: return 1;
			case 0: return 2;
			default: return 3;
			}
		};
		return rank(lhs.ItemType) < rank(rhs.ItemType);
	});
	return preview;
}

static bool SB168_ResponseNewHandCritBoxAwardCfg(std::shared_ptr<ClientNode> Client, UINT ItemId)
{
	if (!Client || ItemId == 0) return false;

	SelectBox168Cfg cfg;
	std::string cfgPath;
	if (!SB168_LoadCfg(ItemId, cfg, &cfgPath) && !SB168_LoadLegacyPreviewCfg(ItemId, cfg, &cfgPath)) return false;
	if (cfg.OpenMode == SB168_MODE_SELECT)
	{
		// Some client resources still enter select boxes through msg 313.
		// For Treasure\168 Select boxes, swallow 313 and send the official
		// select-list response (190) directly; do not fall back to old 313 cfg.
		SB168_ResponseGetBoxItems(Client, cfg, 0);
		if (ShouldPrintDebugForUin10001(Client))
		{
			printf("[Box168][313-skip->190] Uin=%u BoxID=%u Mode=%s Items=%zu Cfg=%s\n", Client->Uin, ItemId, SB168_OpenModeName(cfg.OpenMode), cfg.Items.size(), cfgPath.c_str());
		}
		return true;
	}

	std::vector<SelectBox168Item> preview = SB168_BuildPreviewItems(cfg);
	if (preview.empty()) return false;
	if (preview.size() > (std::numeric_limits<USHORT>::max)()) return false;
	const USHORT previewCount = (USHORT)preview.size();

	int luckValue = 0;
	if (cfg.LuckyValue > 0 && !SB168_LoadLuckyValue(Client, cfg.BoxID, luckValue)) return false;

	std::vector<BYTE> buf(819200);
	BYTE* p = buf.data();
	Write16(p, 0); // ResultId
	Write32(p, Client->Uin); // Uin
	Write16(p, previewCount); // ItemNum

	for (size_t i = 0; i < preview.size(); ++i)
	{
		const SelectBox168Item& item = preview[i];
		BYTE* pLottoryAwardItem = p;
		Write16(p, 0); // len
		Write32(p, item.ItemID); // ItemID
		Write32(p, item.ItemNum ? item.ItemNum : 1); // Num
		Write32(p, item.AvailPeriod); // Period
		Write16(p, item.ItemType); // ItemType
		Set16(pLottoryAwardItem, (WORD)(p - pLottoryAwardItem));
	}

	BYTE* pMultiExtraAwardItem = p;
	Write16(p, 0); // len
	Write32(p, cfg.ExtraItemID); // ItemID
	Write32(p, cfg.ExtraItemNum); // Num
	Write32(p, cfg.ExtraItemPeriod); // Period
	Write16(p, cfg.ExtraItemType); // ItemType
	Set16(pMultiExtraAwardItem, (WORD)(p - pMultiExtraAwardItem));

	Write32(p, (UINT)luckValue); // LuckValue
	Write32(p, cfg.LuckyValue > 0 ? (UINT)cfg.LuckyValue : 0); // MaxLuckValue
	Write32(p, cfg.BoxID); // BoxID

	const size_t len = p - buf.data();
	SendToClient(Client, 313, buf.data(), (DWORD)len, Client->ConnID, FE_PLAYER, 1, Response);

	if (ShouldPrintDebugForUin10001(Client))
	{
		printf("[Box168][313] Uin=%u BoxID=%u Mode=%s Preview=%u ExtraItemID=%u Luck=%d/%d Cfg=%s\n",
			Client->Uin, cfg.BoxID, SB168_OpenModeName(cfg.OpenMode), previewCount, cfg.ExtraItemID, luckValue, cfg.LuckyValue, cfgPath.c_str());
	}
	return true;
}

void RequestGetBoxItems(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{
	if (!Client || !Body) return;
	const size_t payloadLen = SB168_PayloadLen(BodyLen);
	BYTE* p = Body;
	BYTE* end = Body + payloadLen;
	if (!SB168_CanRead(p, end, 14)) return;

	const UINT Uin = Read32(p);
	const UINT Time = Read32(p);
	const UINT BoxID = Read32(p);
	const USHORT Context = Read16(p);
	(void)Time;

	SelectBox168Cfg cfg;
	std::string cfgPath;
	if (!SB168_LoadCfg(BoxID, cfg, &cfgPath)) return;
	if (Uin != Client->Uin) return;
	if (cfg.OpenMode != SB168_MODE_SELECT) return;

	if (ShouldPrintDebugForUin10001(Client))
	{
		printf("[Box168][190] Uin=%u BoxID=%u Mode=%s Items=%zu Context=%u Cfg=%s\n", Client->Uin, BoxID, SB168_OpenModeName(cfg.OpenMode), cfg.Items.size(), Context, cfgPath.c_str());
	}
	SB168_ResponseGetBoxItems(Client, cfg, Context);
}

void RequestSelOptBoxAward(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{
	if (!Client || !Body) return;
	const size_t payloadLen = SB168_PayloadLen(BodyLen);
	BYTE* p = Body;
	BYTE* end = Body + payloadLen;
	if (!SB168_CanRead(p, end, 16))
	{
		SB168_ResponseSelOptBoxAward(Client, 1);
		ResponseStartGame(Client, "Box168 selopt data error!");
		return;
	}

	const UINT Uin = Read32(p);
	const UINT Time = Read32(p);
	const UINT BoxID = Read32(p);
	const int SelIdx = (int)Read32(p);
	(void)Time;

	SelectBox168Cfg cfg;
	std::string cfgPath;
	const bool loaded = SB168_LoadCfg(BoxID, cfg, &cfgPath);
	if (ShouldPrintDebugForUin10001(Client))
	{
		printf("[Box168][616-parse] Uin=%u ReqUin=%u BoxID=%u SelIdx=%d BodyLen=%zu PayloadLen=%zu Cfg=%s\n",
			Client->Uin, Uin, BoxID, SelIdx, BodyLen, payloadLen, loaded ? cfgPath.c_str() : "<missing>");
	}

	if (!loaded)
	{
		SB168_ResponseSelOptBoxAward(Client, 1);
		ResponseStartGame(Client, "Box168 config missing!");
		return;
	}
	if (Uin != Client->Uin)
	{
		SB168_ResponseSelOptBoxAward(Client, 1);
		ResponseStartGame(Client, "Box168 user check failed!");
		return;
	}
	if (cfg.OpenMode != SB168_MODE_SELECT)
	{
		SB168_ResponseSelOptBoxAward(Client, 1);
		ResponseStartGame(Client, "Box168 not select box!");
		return;
	}

	SelectBox168Item award;
	int resolvedIndex = -1;
	if (!SB168_SelectAwardByIndexOrItemID(cfg, SelIdx, award, &resolvedIndex))
	{
		SB168_ResponseSelOptBoxAward(Client, 1);
		ResponseStartGame(Client, "Box168 award not in config!");
		return;
	}

	const int haveNum = PlayerDB_GetItemNum(Client->Uin, cfg.BoxID);
	if (haveNum < 1)
	{
		SB168_ResponseSelOptBoxAward(Client, 1);
		ResponseStartGame(Client, "\xBA\xD0\xD7\xD3\xB1\xD8\xD0\xEB\xC1\xF4\xD2\xBB\xB8\xF6\xD3\xB4\xB1\xA6\xB1\xB4\x21");
		return;
	}

	NotifyUseItemResult2(Client, (int)cfg.BoxID, 1);

	const UINT addNum = award.ItemNum ? award.ItemNum : 1;
	const int finalNum = PlayerDB_AddItem2(Client, Client->Uin, award.ItemID, addNum, award.AvailPeriod, award.Status != 0);
	ItemInfo notify = SB168_ToNotifyItem(award, finalNum > 0 ? (UINT)finalNum : addNum);
	if (notify.ObtainTime == 0) notify.ObtainTime = (int)time(0);

	NotifyClientAddItem(Client, 1, { notify });
	SB168_ResponseSelOptBoxAward(Client, 0);
	SB168_NotifySelOptBoxAward(Client, cfg.BoxID, notify, false);

	if (ShouldPrintDebugForUin10001(Client))
	{
		printf("[Box168][616-grant] Uin=%u BoxID=%u SelIdx=%d ResolvedIndex=%d ItemID=%u Num=%u Period=%d Cfg=%s\n",
			Client->Uin, cfg.BoxID, SelIdx, resolvedIndex, award.ItemID, addNum, award.AvailPeriod, cfgPath.c_str());
	}
}

static bool SB168_ParseFail(const char** reason, const char* value)
{
	if (reason) *reason = value ? value : "bad-data";
	return false;
}

static bool SB168_ReadBE16At(const BYTE* body, size_t len, size_t offset, USHORT& out)
{
	if (!body || offset + 2 > len) return false;
	out = (USHORT)(((USHORT)body[offset] << 8) | body[offset + 1]);
	return true;
}

static bool SB168_ReadBE32At(const BYTE* body, size_t len, size_t offset, UINT& out)
{
	if (!body || offset + 4 > len) return false;
	out = ((UINT)body[offset] << 24) | ((UINT)body[offset + 1] << 16) | ((UINT)body[offset + 2] << 8) | (UINT)body[offset + 3];
	return true;
}

static std::map<UINT, UINT> SB168_LastSelectBoxByUin;
static std::shared_mutex SB168_LastSelectBoxMtx;

static void SB168_SaveLastSelectBox(std::shared_ptr<ClientNode> Client, UINT BoxID)
{
	if (!Client || BoxID == 0) return;
	std::lock_guard<std::shared_mutex> lock(SB168_LastSelectBoxMtx);
	SB168_LastSelectBoxByUin[Client->Uin] = BoxID;
}

static UINT SB168_GetLastSelectBox(std::shared_ptr<ClientNode> Client)
{
	if (!Client) return 0;
	std::shared_lock<std::shared_mutex> lock(SB168_LastSelectBoxMtx);
	auto it = SB168_LastSelectBoxByUin.find(Client->Uin);
	return it == SB168_LastSelectBoxByUin.end() ? 0 : it->second;
}

static void SB168_ClearLastSelectBox(std::shared_ptr<ClientNode> Client)
{
	if (!Client) return;
	std::lock_guard<std::shared_mutex> lock(SB168_LastSelectBoxMtx);
	SB168_LastSelectBoxByUin.erase(Client->Uin);
}

static bool SB168_BodyContainsBoxID(const BYTE* body, size_t len, UINT BoxID)
{
	if (!body || BoxID == 0 || len < 4) return false;
	for (size_t i = 0; i + 4 <= len; ++i)
	{
		UINT value = 0;
		if (SB168_ReadBE32At(body, len, i, value) && value == BoxID) return true;
	}
	return false;
}

static void SB168_LogOpenBoxEntry(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen, size_t payloadLen, UINT rawUin, UINT rawBoxID, USHORT rawKeyLen)
{
	if (!ShouldPrintDebugForUin10001(Client)) return;
	printf("[Box168][168-entry] Uin=%u BodyLen=%zu PayloadLen=%zu RawUin=%u RawBoxID=%u KeyLen=%u HexHead=",
		Client ? Client->Uin : 0, BodyLen, payloadLen, rawUin, rawBoxID, rawKeyLen);
	const size_t hexLen = payloadLen < 32 ? payloadLen : 32;
	for (size_t i = 0; Body && i < hexLen; ++i)
	{
		printf("%02X", Body[i]);
	}
	printf("\n");
	fflush(stdout);
}

static bool SB168_TryAppendAwardFromBody(const SelectBox168Cfg& cfg, BYTE* Body, size_t payloadLen, SB168OpenBoxRequest& req)
{
	if (!Body || cfg.Items.empty()) return false;
	for (const SelectBox168Item& item : cfg.Items)
	{
		for (size_t off = 0; off + 4 <= payloadLen; ++off)
		{
			UINT value = 0;
			if (!SB168_ReadBE32At(Body, payloadLen, off, value) || value != item.ItemID) continue;
			SB168AwardIndexInfo info;
			info.SelectedItemID = item.ItemID;
			info.AwardIdx = (off >= 1) ? Body[off - 1] : 0;
			if (off >= 3)
			{
				USHORT maybeLen = 0;
				if (SB168_ReadBE16At(Body, payloadLen, off - 3, maybeLen) && maybeLen >= 7 && off - 3 + maybeLen <= payloadLen)
				{
					info.AwardLen = maybeLen;
				}
			}
			if (info.AwardLen == 0) info.AwardLen = 7;
			req.AwardIndexInfos.push_back(info);
			if (req.SelectAwardNum == 0) req.SelectAwardNum = 1;
			return true;
		}
	}
	return false;
}

static bool SB168_TryRepairSelectRequestFromCfg(BYTE* Body, size_t BodyLen, const SelectBox168Cfg& cfg, SB168OpenBoxRequest& req)
{
	if (!Body || cfg.OpenMode != SB168_MODE_SELECT) return false;
	if (req.PayloadLen == 0) req.PayloadLen = SB168_PayloadLen(BodyLen);
	if (req.BoxID == 0) req.BoxID = cfg.BoxID;
	if (req.Uin == 0)
	{
		UINT rawUin = 0;
		if (SB168_ReadBE32At(Body, req.PayloadLen, 0, rawUin)) req.Uin = rawUin;
	}
	if (req.OpenCount == 0) req.OpenCount = 1;

	const size_t keyOffsets[] = { 12, 8, 10, 14, 16 };
	for (size_t i = 0; i < sizeof(keyOffsets) / sizeof(keyOffsets[0]); ++i)
	{
		const size_t keyOffset = keyOffsets[i];
		USHORT keyLen = 0;
		if (!SB168_ReadBE16At(Body, req.PayloadLen, keyOffset, keyLen)) continue;
		if (keyLen < 7 || keyOffset + keyLen + 9 > req.PayloadLen) continue;
		size_t fieldOffset = keyOffset + keyLen;
		USHORT mutiOpenNum = 0;
		USHORT srcType = 0;
		if (!SB168_ReadBE16At(Body, req.PayloadLen, fieldOffset + 4, mutiOpenNum)) continue;
		if (!SB168_ReadBE16At(Body, req.PayloadLen, fieldOffset + 6, srcType)) continue;
		BYTE selectAwardNum = Body[fieldOffset + 8];
		if (selectAwardNum > 16) continue;

		req.KeyLen = keyLen;
		req.SpecialIdx = Body[fieldOffset];
		req.Reserved0 = Body[fieldOffset + 1];
		req.Reserved1 = Body[fieldOffset + 2];
		req.Reserved2 = Body[fieldOffset + 3];
		req.MutiOpenNum = mutiOpenNum;
		req.OpenBoxSrcType = srcType;
		req.SelectAwardNum = selectAwardNum;
		req.OpenCount = req.MutiOpenNum ? req.MutiOpenNum : 1;

		BYTE* p = Body + fieldOffset + 9;
		BYTE* end = Body + req.PayloadLen;
		for (BYTE n = 0; n < req.SelectAwardNum; ++n)
		{
			if (!SB168_CanRead(p, end, 2)) break;
			BYTE* pAwardIndexInfo = p;
			SB168AwardIndexInfo info;
			info.AwardLen = Read16(p);
			if (info.AwardLen < 7 || !SB168_CanRead(pAwardIndexInfo, end, info.AwardLen) || !SB168_CanRead(p, end, 5)) break;
			info.AwardIdx = Read8(p);
			info.SelectedItemID = Read32(p);
			req.AwardIndexInfos.push_back(info);
			p = pAwardIndexInfo + info.AwardLen;
		}
		break;
	}

	if (req.SelectAwardNum > 0 && req.AwardIndexInfos.empty())
	{
		SB168_TryAppendAwardFromBody(cfg, Body, req.PayloadLen, req);
	}
	if (req.SelectAwardNum == 0)
	{
		SB168_TryAppendAwardFromBody(cfg, Body, req.PayloadLen, req);
	}
	return req.SelectAwardNum > 0 && !req.AwardIndexInfos.empty();
}

static bool SB168_ParseOpenBoxRequest(BYTE* Body, size_t BodyLen, SB168OpenBoxRequest& req, const char** reason)
{
	req = SB168OpenBoxRequest();
	req.PayloadLen = SB168_PayloadLen(BodyLen);
	BYTE* p = Body;
	BYTE* end = Body ? (Body + req.PayloadLen) : nullptr;
	if (!SB168_CanRead(p, end, 12)) return SB168_ParseFail(reason, "bad-data-head");

	req.Uin = Read32(p);
	req.Time = Read32(p);
	req.BoxID = Read32(p);

	if (!SB168_CanRead(p, end, 2)) return SB168_ParseFail(reason, "bad-key-len");
	BYTE* pKey = p;
	req.KeyLen = Read16(p);
	if (req.KeyLen < 7 || !SB168_CanRead(pKey, end, req.KeyLen)) return SB168_ParseFail(reason, "bad-key-data");
	p = pKey + req.KeyLen;

	// 2026 当前客户端实测 CRequestOpenBoxPara 在 SpecialIdx 后有 3 字节保留位。
	if (!SB168_CanRead(p, end, 9)) return SB168_ParseFail(reason, "bad-open-fields");
	req.SpecialIdx = Read8(p);
	req.Reserved0 = Read8(p);
	req.Reserved1 = Read8(p);
	req.Reserved2 = Read8(p);
	req.MutiOpenNum = Read16(p);
	req.OpenBoxSrcType = Read16(p);
	req.SelectAwardNum = Read8(p);
	req.OpenCount = req.MutiOpenNum ? req.MutiOpenNum : 1;

	for (BYTE i = 0; i < req.SelectAwardNum; ++i)
	{
		if (!SB168_CanRead(p, end, 2)) return SB168_ParseFail(reason, "bad-award-len");
		BYTE* pAwardIndexInfo = p;
		SB168AwardIndexInfo info;
		info.AwardLen = Read16(p);
		if (info.AwardLen < 7 || !SB168_CanRead(pAwardIndexInfo, end, info.AwardLen) || !SB168_CanRead(p, end, 5))
		{
			return SB168_ParseFail(reason, "bad-award-data");
		}

		info.AwardIdx = Read8(p);
		info.SelectedItemID = Read32(p);
		p = pAwardIndexInfo + info.AwardLen;
		req.AwardIndexInfos.push_back(info);
	}

	if (reason) *reason = "ok";
	return true;
}

static void SB168_LogOpenBoxFail(std::shared_ptr<ClientNode> Client, const SelectBox168Cfg& cfg, const SB168OpenBoxRequest& req,
	const char* cfgPath, const char* branch, const char* reason, BYTE awardIdx = 0, UINT selectedItemID = 0, int have = -1, UINT cost = 0)
{
	if (!ShouldPrintDebugForUin10001(Client)) return;
	printf("[Box168][168-fail] Uin=%u BoxID=%u OpenCount=%u SelectAwardNum=%u AwardIdx=%u SelectedItemID=%u Have=%d Cost=%u Branch=%s Reason=%s BodyPayloadLen=%zu KeyLen=%u Cfg=%s\n",
		Client ? Client->Uin : 0,
		cfg.BoxID ? cfg.BoxID : req.BoxID,
		req.OpenCount,
		req.SelectAwardNum,
		awardIdx,
		selectedItemID,
		have,
		cost,
		branch ? branch : "bad-data",
		reason ? reason : "bad-data",
		req.PayloadLen,
		req.KeyLen,
		cfgPath ? cfgPath : "<missing>");
	fflush(stdout);
}

static bool SB168_HandleOpenBox(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{
	if (!Client || !Body) return false;
	const size_t payloadLen = SB168_PayloadLen(BodyLen);
	UINT rawUin = 0;
	UINT rawBoxID = 0;
	USHORT rawKeyLen = 0;
	SB168_ReadBE32At(Body, payloadLen, 0, rawUin);
	SB168_ReadBE32At(Body, payloadLen, 8, rawBoxID);
	SB168_ReadBE16At(Body, payloadLen, 12, rawKeyLen);
	SB168_LogOpenBoxEntry(Client, Body, BodyLen, payloadLen, rawUin, rawBoxID, rawKeyLen);

	SB168OpenBoxRequest req;
	const char* parseReason = "ok";
	const bool parsed = SB168_ParseOpenBoxRequest(Body, BodyLen, req, &parseReason);

	SelectBox168Cfg cfg;
	std::string cfgPath;
	UINT loadedBoxID = 0;
	UINT candidates[5] = {
		req.BoxID,
		rawBoxID,
		SB168_BodyContainsBoxID(Body, payloadLen, 160463) ? (UINT)160463 : (UINT)0,
		SB168_GetLastSelectBox(Client),
		0
	};
	for (size_t i = 0; i < sizeof(candidates) / sizeof(candidates[0]); ++i)
	{
		const UINT candidate = candidates[i];
		if (candidate == 0) continue;
		bool seen = false;
		for (size_t j = 0; j < i; ++j)
		{
			if (candidates[j] == candidate)
			{
				seen = true;
				break;
			}
		}
		if (seen) continue;
		if (SB168_LoadCfg(candidate, cfg, &cfgPath))
		{
			loadedBoxID = cfg.BoxID ? cfg.BoxID : candidate;
			break;
		}
	}

	if (loadedBoxID == 0)
	{
		if (ShouldPrintDebugForUin10001(Client) && (req.BoxID != 0 || rawBoxID != 0))
		{
			SelectBox168Cfg missingCfg;
			missingCfg.BoxID = req.BoxID ? req.BoxID : rawBoxID;
			if (missingCfg.BoxID == 0 && SB168_BodyContainsBoxID(Body, payloadLen, 160463)) missingCfg.BoxID = 160463;
			req.PayloadLen = payloadLen;
			if (req.Uin == 0) req.Uin = rawUin;
			SB168_LogOpenBoxFail(Client, missingCfg, req, "<missing>", "cfg-missing", "cfg-missing");
		}
		if (req.BoxID == 160463 || rawBoxID == 160463 || SB168_BodyContainsBoxID(Body, payloadLen, 160463))
		{
			ResponseStartGame(Client, "Box168 config missing!");
			return true;
		}
		return false;
	}

	if (req.BoxID == 0 || req.BoxID != loadedBoxID) req.BoxID = loadedBoxID;
	if (req.Uin == 0) req.Uin = rawUin;
	if (!parsed && cfg.OpenMode == SB168_MODE_SELECT)
	{
		SB168_TryRepairSelectRequestFromCfg(Body, BodyLen, cfg, req);
	}

	if (!parsed && (req.SelectAwardNum == 0 || req.AwardIndexInfos.empty()))
	{
		SB168_LogOpenBoxFail(Client, cfg, req, cfgPath.c_str(), "bad-data", parseReason);
		ResponseStartGame(Client, "Box168 request data error!");
		return true;
	}

	if (req.Uin != Client->Uin)
	{
		SB168_LogOpenBoxFail(Client, cfg, req, cfgPath.c_str(), "user-check", "user-check");
		ResponseStartGame(Client, "Box168 user check failed!");
		return true;
	}

	std::vector<SelectBox168Item> awards;

	if (ShouldPrintDebugForUin10001(Client))
	{
		printf("[Box168][168-parse] Uin=%u BoxID=%u Mode=%s BodyLen=%zu PayloadLen=%zu KeyLen=%u SpecialIdx=%u Reserved3=%02X%02X%02X OpenCount=%u SrcType=%u SelectAwardNum=%u Cfg=%s\n",
			Client->Uin, cfg.BoxID, SB168_OpenModeName(cfg.OpenMode), BodyLen, req.PayloadLen, req.KeyLen, req.SpecialIdx, req.Reserved0, req.Reserved1, req.Reserved2, req.OpenCount, req.OpenBoxSrcType, req.SelectAwardNum, cfgPath.c_str());
		fflush(stdout);
	}

	if (cfg.OpenMode == SB168_MODE_SELECT)
	{
		if (req.SelectAwardNum == 0)
		{
			SB168_SaveLastSelectBox(Client, cfg.BoxID);
			SB168_ResponseGetBoxItems(Client, cfg, 0);
			if (ShouldPrintDebugForUin10001(Client))
			{
				printf("[Box168][168-open->190] Uin=%u BoxID=%u Mode=%s Items=%zu Cfg=%s\n", Client->Uin, cfg.BoxID, SB168_OpenModeName(cfg.OpenMode), cfg.Items.size(), cfgPath.c_str());
				fflush(stdout);
			}
			return true;
		}

		if (req.SelectAwardNum > cfg.MaxSelectNum)
		{
			SB168_LogOpenBoxFail(Client, cfg, req, cfgPath.c_str(), "select-count", "select-count", 0, 0, PlayerDB_GetItemNum(Client->Uin, cfg.BoxID), req.OpenCount);
			ResponseStartGame(Client, "Box168 select count error!");
			return true;
		}

		for (const SB168AwardIndexInfo& selected : req.AwardIndexInfos)
		{
			if (ShouldPrintDebugForUin10001(Client))
			{
				printf("[Box168][168-select] Uin=%u BoxID=%u AwardIdx=%u SelectedItemID=%u AwardLen=%u OpenCount=%u Branch=168-select\n",
					Client->Uin, cfg.BoxID, selected.AwardIdx, selected.SelectedItemID, selected.AwardLen, req.OpenCount);
				fflush(stdout);
			}

			SelectBox168Item selectedAward;
			int resolvedIndex = -1;
			bool foundAward = false;
			const SelectBox168Item* cfgItem = selected.SelectedItemID ? SB168_FindItem(cfg, selected.SelectedItemID) : nullptr;
			if (cfgItem)
			{
				selectedAward = *cfgItem;
				foundAward = true;
			}
			else if (SB168_SelectAwardByIndexOrItemID(cfg, (int)selected.AwardIdx, selectedAward, &resolvedIndex))
			{
				foundAward = true;
			}
			else if (selected.AwardIdx > 0 && SB168_SelectAwardByIndexOrItemID(cfg, (int)selected.AwardIdx - 1, selectedAward, &resolvedIndex))
			{
				foundAward = true;
			}

			if (!foundAward)
			{
				SB168_LogOpenBoxFail(Client, cfg, req, cfgPath.c_str(), "not-in-config", "not-in-config", selected.AwardIdx, selected.SelectedItemID, PlayerDB_GetItemNum(Client->Uin, cfg.BoxID), req.OpenCount);
				ResponseStartGame(Client, "Box168 award not in config!");
				return true;
			}
			if (ShouldPrintDebugForUin10001(Client) && selected.SelectedItemID == 0)
			{
				printf("[Box168][168-select-resolve] Uin=%u BoxID=%u AwardIdx=%u ResolvedIndex=%d ResolvedItemID=%u Branch=award-idx\n",
					Client->Uin, cfg.BoxID, selected.AwardIdx, resolvedIndex, selectedAward.ItemID);
				fflush(stdout);
			}
			awards.push_back(selectedAward);
		}
	}
	else if (cfg.OpenMode == SB168_MODE_ALL)
	{
		awards = SB168_BuildAllAwards(cfg, req.OpenCount);
	}
	else if (cfg.OpenMode == SB168_MODE_RANDOM)
	{
		if (!SB168_RollRandomAwards(Client, cfg, req.OpenCount, awards))
		{
			SB168_LogOpenBoxFail(Client, cfg, req, cfgPath.c_str(), "random-empty", "random-empty", 0, 0, PlayerDB_GetItemNum(Client->Uin, cfg.BoxID), req.OpenCount);
			ResponseStartGame(Client, "Box168 random award empty!");
			return true;
		}
	}

	if (awards.empty())
	{
		SB168_LogOpenBoxFail(Client, cfg, req, cfgPath.c_str(), "award-empty", "award-empty", 0, 0, PlayerDB_GetItemNum(Client->Uin, cfg.BoxID), req.OpenCount);
		ResponseStartGame(Client, "Box168 award empty!");
		return true;
	}

	if (!SB168_GrantAwards(Client, cfg, awards, req.OpenCount)) return true;
	RockParty_RecordBoxOpen(Client, cfg.BoxID, req.OpenCount);
	SB168_ResponseOpenBox(Client, cfg, awards);
	SB168_ClearLastSelectBox(Client);

	if (ShouldPrintDebugForUin10001(Client))
	{
		printf("[Box168][168] Uin=%u BoxID=%u Mode=%s OpenCount=%u Awards=%zu Cfg=%s Branch=success\n", Client->Uin, cfg.BoxID, SB168_OpenModeName(cfg.OpenMode), req.OpenCount, awards.size(), cfgPath.c_str());
		fflush(stdout);
	}
	return true;
}

void RequestOpenBox(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen) {

	if (propflag == 0)

	{

		ResponseStartGame(Client, "\xB3\xE9\xBD\xB1\xD4\xDD\xCA\xB1\xB9\xD8\xB1\xD5\x21");

		return;

	}

	std::lock_guard<std::shared_mutex> lock(Client->mtx);

	if (SB168_HandleOpenBox(Client, Body, BodyLen))
	{
		return;
	}

	int n = 1;

	BYTE* p = Body;

	WORD len;



	UINT Uin = Read32(p);

	UINT Time = Read32(p);

	int KeyID = 0;

	int Num = 0;

	int TreasureBoxID = Read32(p);

	{ // Key

		BYTE* pKey = p;

		len = Read16(pKey);



		int KeyType = Read32(pKey);

		for (size_t i = 0; i < n; i++)

		{ // KeyEntry

			BYTE* pKeyEntry = pKey;

			len = Read16(pKeyEntry);



			KeyID = Read32(pKeyEntry);

			Num = Read32(pKeyEntry);



			pKey += len;

		}

		UINT IsNotConsume = Read8(pKey);

		// Read8(pKey);



		p += len;

	}

	UINT SpecialIdx = Read8(p);

	USHORT MutiOpenNum = Read16(p);

	USHORT OpenBoxSrcType = Read16(p);

	UCHAR SelectAwardNum = Read8(p);

	int ItemIDNum = 1;

	for (size_t i = 0; i < n; i++)

	{ // AwardIndexInfo

		BYTE* pAwardIndexInfo = p;

		len = Read16(pAwardIndexInfo);



		UCHAR AwardIdx = Read8(pAwardIndexInfo);

		ItemIDNum = Read32(pAwardIndexInfo);

		if (ItemIDNum == 0)

		{

			ItemIDNum = 1;

		}

		p += len;

	}



	//Body += 8;

	//int TreasureBoxID = Read32(Body);//这里普通宝箱这样读取是可以的 但是其他宝箱不是

	//Body += 12;

	//int ItemIDNum = Read8(Body);//多开次数 打开次数 实际上是4位 int 你这里只是读取一位

	//if (ItemIDNum == 0) {

	//	ItemIDNum++;//星宝瓶等道具是0

	//}





	if (!isDBtHasItem(Client, TreasureBoxID, ItemIDNum))

	{

		ResponseStartGame(Client, "\xBA\xD0\xD7\xD3\xB1\xD8\xD0\xEB\xC1\xF4\xD2\xBB\xB8\xF6\xD3\xB4\xB1\xA6\xB1\xB4\x21");

		return;

	}

	if (TreasureBoxID == 62787)//魅力蝴蝶结加魅力

	{

		RequestAddCharm(Client, TreasureBoxID, ItemIDNum);

		return;

	}

	if (TreasureBoxID == 84900)//加点卡

	{

		RequestAddSuperMoney(Client, TreasureBoxID, ItemIDNum);

		return;

	}

	if (!Client->NewKartTip && (NewKart == 1 || NewKart == 2)) {

		if (NewKart == 1) {

			ResponseStartGame(Client, "\xB5\xB1\xC7\xB0\xB3\xE9\xBD\xB1\xBB\xF1\xC8\xA1\xD0\xC2\xB3\xB5\xB8\xC4\xD7\xB0\xB1\xA6\xCA\xAF\xB7\xBD\xCA\xBD\xCA\xC7\xD7\xD4\xB6\xAF\xBB\xF1\xC8\xA1\x0A\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\xCE\xDE\xB1\xA6\xCA\xAF\xB3\xB5\xC1\xBE\xBD\xCF\xB6\xE0\xBB\xE1\xD3\xD0\xCB\xF9\xBF\xA8\xB6\xD9\x0A\x2F\x43\x30\x31\xBD\xF8\xC8\xEB\xB8\xC4\xD7\xB0\xBB\xF2\xD5\xDF\xCF\xE2\xC7\xB6\xB1\xA6\xCA\xAF\xBD\xE7\xC3\xE6\xA3\xAC\xCB\xF9\xD3\xD0\xD0\xC2\xB3\xB5\xC1\xBE\xBC\xB4\xBF\xC9\xBB\xF1\xB5\xC3\xB8\xC4\xD7\xB0\xBA\xCD\xB1\xA6\xCA\xAF\xBF\xD7\x21");

		}

		else if (NewKart == 2) {

			ResponseStartGame(Client, "\xB5\xB1\xC7\xB0\xB3\xE9\xBD\xB1\xBB\xF1\xC8\xA1\xD0\xC2\xB3\xB5\xB8\xC4\xD7\xB0\xB1\xA6\xCA\xAF\xB7\xBD\xCA\xBD\xCA\xC7\xCB\xA2\xD0\xC2\xC6\xB5\xB5\xC0\x0A\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20\xCE\xDE\xB1\xA6\xCA\xAF\xB3\xB5\xC1\xBE\xBD\xCF\xB6\xE0\xBB\xE1\xD3\xD0\xCB\xF9\xBF\xA8\xB6\xD9\x0A\x2F\x43\x30\x31\xCB\xA2\xD0\xC2\xC6\xB5\xB5\xC0\xBA\xF3\xA3\xAC\xCB\xF9\xD3\xD0\xD0\xC2\xB3\xB5\xC1\xBE\xBC\xB4\xBF\xC9\xBB\xF1\xB5\xC3\xB8\xC4\xD7\xB0\xBA\xCD\xB1\xA6\xCA\xAF\xBF\xD7\x21");

		}

		Client->NewKartTip = true;

		//return;

	}



	std::vector<ItemInfo> ItemsAdd(ItemIDNum);

	std::vector<ItemInfo> Items;

	bool result = false;

	if (Uinew) {

		result = GetRandItemCJ(Client, TreasureBoxID, ItemIDNum, ItemsAdd, Items);

	}

	else {

		result = GetRandItem2(Client, TreasureBoxID, ItemIDNum, ItemsAdd, Items);

	}



	if (!result) {

		ResponseStartGame(Client, "\xB1\xA6\xCF\xE4\xBD\xB1\xC0\xF8\xC5\xE4\xD6\xC3\xCE\xAA\xBF\xD5\x21");

	}

	else

	{

		virtualsend3(Client, { Items }, ItemIDNum, TreasureBoxID, ItemsAdd);

	}

}



void ResponseGetGameBaseRecordList(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen) {

	std::vector<BYTE> buf(819200); BYTE* p = buf.data();

	//BYTE* p = buf;

	size_t len;

	int count;

	Write16(p, 0);

	Write32(p, Client->Uin);

	Write16(p, 1);



	BYTE* pInfo = p;

	Write16(pInfo, 0);//len



	{

		Write16(pInfo, 1);



		BYTE* pMapNum = pInfo;

		Write16(pInfo, 0);



		try

		{

			DBConnection myDBConnection(player); auto conn = myDBConnection.getConnection();  if (!conn) return;

			std::unique_ptr<sql::PreparedStatement> prep_stmt(conn->prepareStatement("SELECT * FROM (SELECT a.mapid, b.Ranking, a.recordid, a.gamemode, a.datetime FROM BattleRecord a JOIN battledetails b ON a.recordid = b.Recordid WHERE b.Uin = ? ORDER BY a.datetime DESC LIMIT 50) AS subquery ORDER BY datetime asc;"));

			prep_stmt->clearParameters();

			prep_stmt->setUInt(1, Client->Uin);

			// 执行查询

			std::unique_ptr<sql::ResultSet> res(prep_stmt->executeQuery());

			prep_stmt.reset();

			count = res->rowsCount();

			// 处理结果

			while (res->next()) {

				BYTE* pMapInfo = pInfo;

				Write16(pMapInfo, 0); //len



				Write32(pMapInfo, res->getUInt("mapid"));

				Write16(pMapInfo, res->getInt("Ranking"));

				Write32(pMapInfo, res->getInt("datetime"));



				Write32(pMapInfo, res->getUInt("recordid"));

				Write32(pMapInfo, res->getInt("gamemode"));



				len = pMapInfo - pInfo;

				Set16(pInfo, (WORD)len);

				pInfo += len;

			}

			res.reset();

		}

		catch (const std::exception& e)

		{

			std::cerr << e.what() << "RequestBattleRecord Error" << std::endl;

		}



		Set16(pMapNum, (WORD)count);

	}



	len = pInfo - p;

	Set16(p, (WORD)len);

	p += len;



	len = p - buf.data();

	SendToClient(Client, 1702, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);

}



