void PrintfBody(std::shared_ptr<ClientNode> Client, USHORT MsgID, BYTE* Body, size_t BodyLen)

{



	printf("MsgID:%d  Body 内容大小：%d\n", MsgID, (int)BodyLen);

	fflush(stdout);

	for (int i = 0; i < BodyLen; i++)

	{

		printf("%02X ", *(Body + i));

		fflush(stdout);

	}

	printf("\n");

	fflush(stdout);



}

void PrintfBody(BYTE* Body, size_t BodyLen)

{



	printf("Body 内容大小：%d\n", (int)BodyLen);

	fflush(stdout);

	for (int i = 0; i < BodyLen; i++)

	{

		printf("%02X ", *(Body + i));

		fflush(stdout);

	}

	printf("\n");

	fflush(stdout);



}





void PrintfBody(std::shared_ptr<ClientNode> Client, USHORT MsgID, BYTE* Body, size_t BodyLen, const char* filename)

{

	// 打开文件以进行写入

	FILE* file = nullptr;

	fopen_s(&file, filename, "a"); // 以追加模式打开文件

	if (file == nullptr) {

		printf("无法打开文件: %s\n", filename);

		return;

	}



	// 写入消息 ID 和内容大小

	fprintf(file, "MsgID:%d  Body 内容大小：%d\n", MsgID, (int)BodyLen);



	// 写入 Body 内容

	for (size_t i = 0; i < BodyLen; i++) {

		fprintf(file, "%02x ", *(Body + i)); // 以两位十六进制格式写入

	}

	fprintf(file, "\n");



	// 关闭文件

	fclose(file);

}



#pragma pack(push, 1)
struct QQS_MSGHEAD14
{
	unsigned short MsgID;
	short MsgType;
	int MsgSeq;
	char SrcFE;
	char DstFE;
	short SrcID;
	short DstID;
};
#pragma pack(pop)

static_assert(sizeof(CSHEAD) == 18, "QQSpeed CSHEAD wire size must stay 18 bytes");
static_assert(sizeof(QQS_MSGHEAD14) == 14, "QQSpeed official 14-byte msg head must stay 14 bytes");

static void QQS_BuildHex16(const BYTE* Data, DWORD Length, char* FirstHex, size_t FirstHexSize, char* LastHex, size_t LastHexSize)
{
	if (FirstHex && FirstHexSize > 0)
		FirstHex[0] = 0;
	if (LastHex && LastHexSize > 0)
		LastHex[0] = 0;

	const size_t firstCount = (Length < 16) ? Length : 16;
	const size_t lastStart = (Length > 16) ? (Length - 16) : 0;
	size_t pos = 0;
	for (size_t i = 0; FirstHex && i < firstCount && pos + 2 < FirstHexSize; ++i)
		pos += sprintf_s(FirstHex + pos, FirstHexSize - pos, "%02X", Data ? Data[i] : 0);

	pos = 0;
	for (size_t i = lastStart; LastHex && i < Length && pos + 2 < LastHexSize; ++i)
		pos += sprintf_s(LastHex + pos, LastHexSize - pos, "%02X", Data ? Data[i] : 0);
}

BOOL SendToClientOfficial14(std::shared_ptr<ClientNode> Client, short MsgID, const BYTE* Data, DWORD Length, short SrcID, char SrcFE, short WireDstID, short MsgType)
{
	if (!Client) { return 0; }
	if (Client->TransportConnID <= 0) return 0;
	if (Client->ProtocolVersion == 0)
	{
		QQS_DebugPrintf10001("[SEND-GUARD] drop unknown protocol version MsgID=%d Uin=%u TransportConnID=%llu\n",
			(int)MsgID, Client->Uin, (unsigned long long)Client->TransportConnID);
		return 0;
	}
	if (Length > 0 && Data == nullptr)
	{
		QQS_DebugPrintf10001("[SEND-GUARD] drop null data MsgID=%d Len=%u Uin=%u TransportConnID=%llu\n", (int)MsgID, (unsigned)Length, Client->Uin, (unsigned long long)Client->TransportConnID);
		return 0;
	}

	const short effectiveSrcID = NormalizeClientPlayerSrcID(Client, SrcFE, SrcID);
	// Official global notifications (for example msg 555) use DstID=0.
	// Preserve that broadcast route on the 14-byte header path; the legacy
	// MSGHEAD path still keeps its existing nonzero destination normalization.
	const short effectiveWireDstID = (WireDstID == 0)
		? 0
		: NormalizeClientWireDstID(Client, WireDstID);
	const DWORD totalLength = (DWORD)(sizeof(CSHEAD) + sizeof(QQS_MSGHEAD14) + Length);
	std::vector<BYTE> packet(totalLength);

	CSHEAD* ProtocolHead = (CSHEAD*)packet.data();
	QQS_MSGHEAD14* MsgHead = (QQS_MSGHEAD14*)(ProtocolHead + 1);
	BYTE* MsgBody = (BYTE*)(MsgHead + 1);

	MsgHead->MsgID = htons(MsgID);
	MsgHead->MsgType = htons(MsgType);
	MsgHead->MsgSeq = htonl(-1);
	MsgHead->SrcFE = SrcFE;
	MsgHead->DstFE = FE_CLIENT;
	MsgHead->SrcID = htons(effectiveSrcID);
	MsgHead->DstID = htons(effectiveWireDstID);
	if (Length > 0)
		memcpy(MsgBody, Data, Length);

	ProtocolHead->TotalLength = htonl(totalLength);
	ProtocolHead->Ver = static_cast<short>(htons(Client->ProtocolVersion));
	ProtocolHead->DialogID = htons(effectiveSrcID);
	ProtocolHead->Seq = htonl(-1);
	ProtocolHead->Uin = htonl(Client->Uin);
	ProtocolHead->BodyFlag = 0;
	ProtocolHead->OptLength = 0;

	const bool isDebug10001Send = QQS_DebugUin10001Enabled() &&
		(Client->Uin == 10001 || Client->TransportConnIDUin == 10001 || Client->TransportConnID == 10001);
	if (isDebug10001Send)
	{
		char firstHex[33] = {};
		char lastHex[33] = {};
		QQS_BuildHex16(Data, Length, firstHex, sizeof(firstHex), lastHex, sizeof(lastHex));
		QQS_DebugPrintf10001("%s Uin=%u TransportConnID=%d MsgID=%d PayloadLen=%lu WireMsgHeadLen=%u Total=%u SrcID=%d SrcFE=%d WireDstID=%d MsgType=%d Encrypt=0 First16=%s Last16=%s\n",
			MsgID == 440 ? "[SEND-440-OFFICIAL]" : "[SEND-OFFICIAL14]",
			Client->Uin,
			Client->TransportConnID,
			(int)MsgID,
			(unsigned long)Length,
			(unsigned)sizeof(QQS_MSGHEAD14),
			(unsigned)totalLength,
			(int)effectiveSrcID,
			(int)SrcFE,
			(int)effectiveWireDstID,
			(int)MsgType,
			firstHex,
			lastHex);
	}

	Client->Server->Send(Client->TransportConnID, packet.data(), totalLength);
	return 0;
}

BOOL SendToClient440Official(std::shared_ptr<ClientNode> Client, const BYTE* Data, DWORD Length, short SrcID, char SrcFE, short WireDstID, short MsgType)
{
	return SendToClientOfficial14(Client, 440, Data, Length, SrcID, SrcFE, WireDstID, MsgType);
}

static BOOL SendToClientInternal(
	std::shared_ptr<ClientNode> Client,
	short MsgID,
	const BYTE* Data,
	DWORD Length,
	short SrcID,
	char SrcFE,
	short DstIDArg,
	short WireDstID,
	short MsgType,
	char Encrypt,
	int WireBodyLenOverride = -1,
	int WireMsgSeq = -1,
	bool PreserveWireRouteIDs = false,
	int ProtocolDialogIDOverride = -65536,
	int ProtocolSeq = -1,
	std::shared_ptr<ClientNode> TransportClient = nullptr)

{



	if (!Client) { return 0; }
	const std::shared_ptr<ClientNode> WireClient = TransportClient ? TransportClient : Client;

	if (!WireClient || WireClient->TransportConnID <= 0 || WireClient->deleteflag) return 0;

	if (WireClient->ProtocolVersion == 0)

	{

		QQS_DebugPrintf10001("[SEND-GUARD] drop unknown protocol version MsgID=%d Uin=%u TransportConnID=%llu\n",

			(int)MsgID, Client->Uin, (unsigned long long)WireClient->TransportConnID);

		return 0;

	}

	if (Length > 0 && Data == nullptr)

	{

		QQS_DebugPrintf10001("[SEND-GUARD] drop null data MsgID=%d Len=%u Uin=%u TransportConnID=%llu\n", (int)MsgID, (unsigned)Length, Client->Uin, (unsigned long long)WireClient->TransportConnID);

		return 0;

	}



	CSHEAD* ProtocolHead;

	MSGHEAD* MsgHead;

	void* MsgBody;

	int TotalLength;



	int MsgLen = sizeof(MSGHEAD) + Length;

	MsgHead = (MSGHEAD*)malloc(MsgLen);

	if (!MsgHead)

	{

		return 0;

	}

	MsgHead->MsgID = htons(MsgID);

	MsgHead->MsgType = htons(MsgType);

	int effectiveWireMsgSeq = WireMsgSeq;
	bool normalRaceStreamMessage = false;
	std::unique_lock<std::mutex> normalRaceSequenceLock;
	if ((SrcFE == FE_GAMELOGIC || SrcFE == FE_PLAYER) && SrcID != 0)
	{
		normalRaceSequenceLock = std::unique_lock<std::mutex>(Client->NormalRaceWireSequenceMutex);
		normalRaceStreamMessage =
			Client->NormalRaceWireActive &&
			Client->NormalRaceWireRouteID == static_cast<USHORT>(SrcID);
		if (normalRaceStreamMessage && effectiveWireMsgSeq < 0)
			effectiveWireMsgSeq = Client->NormalRaceWireLastMsgSeq + 1;
	}

	MsgHead->MsgSeq = htonl(effectiveWireMsgSeq);

	MsgHead->SrcFE = SrcFE;

	MsgHead->DstFE = FE_CLIENT;

	const short effectiveSrcID = PreserveWireRouteIDs
		? SrcID
		: NormalizeClientPlayerSrcID(Client, SrcFE, SrcID);
	const short effectiveWireDstID = PreserveWireRouteIDs
		? WireDstID
		: NormalizeClientWireDstID(Client, WireDstID);

	MsgHead->SrcID = htons(effectiveSrcID);

	MsgHead->DstID = htons(effectiveWireDstID);

	const WORD wireBodyLen = (WireBodyLenOverride >= 0)
		? (WORD)WireBodyLenOverride
		: (WORD)(sizeof(USHORT) + USHORT(Length));

	MsgHead->BodyLen = htons(wireBodyLen);

	MsgBody = (void*)(MsgHead + 1);

	memcpy(MsgBody, Data, Length);



	if (Encrypt)

	{

		int EncryptLen = oi_symmetry_encrypt2_len(MsgLen);

		TotalLength = sizeof(CSHEAD) + EncryptLen;

		if (!(ProtocolHead = (CSHEAD*)malloc(TotalLength)))

		{

			return 0;

		}

		//加密数据包

		oi_symmetry_encrypt2((BYTE*)MsgHead, MsgLen, WireClient->Key, (BYTE*)(ProtocolHead + 1), &EncryptLen);

		TotalLength = sizeof(CSHEAD) + EncryptLen;

	}

	else

	{

		TotalLength = sizeof(CSHEAD) + MsgLen;

		if (!(ProtocolHead = (CSHEAD*)malloc(TotalLength)))

		{

			return 0;

		}

		memcpy((MSGHEAD*)(ProtocolHead + 1), MsgHead, MsgLen);

	}

	free(MsgHead);



	ProtocolHead->TotalLength = htonl(TotalLength);

	ProtocolHead->Ver = static_cast<short>(htons(WireClient->ProtocolVersion));

	const short effectiveProtocolDialogID =
		(ProtocolDialogIDOverride >= -32768 && ProtocolDialogIDOverride <= 32767)
		? static_cast<short>(ProtocolDialogIDOverride)
		: effectiveSrcID;
	ProtocolHead->DialogID = htons(effectiveProtocolDialogID);

	ProtocolHead->Seq = htonl(ProtocolSeq);

	ProtocolHead->Uin = htonl(Client->Uin);

	ProtocolHead->BodyFlag = Encrypt;

	ProtocolHead->OptLength = 0;



	const bool isDebug10001Send = QQS_DebugUin10001Enabled() &&
		(Client->Uin == 10001 || Client->TransportConnIDUin == 10001 || Client->TransportConnID == 10001);

	if (isDebug10001Send

		&& !ShouldSuppressDebugPacketMsgID(static_cast<USHORT>(MsgID)))

	{

		printf("[SEND-10001] TransportConnID=%d Uin=%u TransportConnIDUin=%u MsgID=%d MsgType=%d Length=%lu WireBodyLen=%u Total=%d SrcID=%d SrcFE=%d DstIDArg=%d WireDstID=%d WireMsgSeq=%d ProtoSeq=%d Encrypt=%d\n",

			WireClient->TransportConnID,

			Client->Uin,

			WireClient->TransportConnIDUin,

			(int)MsgID,

			(int)MsgType,

			(unsigned long)Length,

			(unsigned)wireBodyLen,

			TotalLength,

			(int)effectiveSrcID,

			(int)SrcFE,

			(int)DstIDArg,

			(int)effectiveWireDstID,

			effectiveWireMsgSeq,

			ProtocolSeq,

			Encrypt ? 1 : 0);

		fflush(stdout);

	}

	if (isDebug10001Send &&
		!ShouldSuppressDebugPacketMsgID(static_cast<USHORT>(MsgID)))
	{
		char firstHex[33] = {};
		char lastHex[33] = {};
		const size_t firstCount = (Length < 16) ? Length : 16;
		const size_t lastStart = (Length > 16) ? (Length - 16) : 0;
		size_t pos = 0;
		for (size_t i = 0; i < firstCount && pos + 2 < sizeof(firstHex); ++i)
			pos += sprintf_s(firstHex + pos, sizeof(firstHex) - pos, "%02X", Data ? Data[i] : 0);
		pos = 0;
		for (size_t i = lastStart; i < Length && pos + 2 < sizeof(lastHex); ++i)
			pos += sprintf_s(lastHex + pos, sizeof(lastHex) - pos, "%02X", Data ? Data[i] : 0);
		QQS_DebugPrintf10001("[SEND-FLOW] Uin=%u TransportConnID=%d MsgID=%d MsgType=%d PayloadLen=%lu WireBodyLen=%u Total=%d SrcID=%d SrcFE=%d DstIDArg=%d WireDstID=%d WireMsgSeq=%d Encrypt=%d First16=%s Last16=%s\n",
			Client->Uin,
			WireClient->TransportConnID,
			(int)MsgID,
			(int)MsgType,
			(unsigned long)Length,
			(unsigned)wireBodyLen,
			TotalLength,
			(int)effectiveSrcID,
			(int)SrcFE,
			(int)DstIDArg,
			(int)effectiveWireDstID,
			effectiveWireMsgSeq,
			Encrypt ? 1 : 0,
			firstHex,
			lastHex);
	}



	const BOOL sendResult = WireClient->Server->Send(
		WireClient->TransportConnID,
		(BYTE*)ProtocolHead,
		TotalLength);
	if (sendResult &&
		normalRaceStreamMessage &&
		effectiveWireMsgSeq > Client->NormalRaceWireLastMsgSeq)
	{
		Client->NormalRaceWireLastMsgSeq = effectiveWireMsgSeq;
	}





#ifdef DEBUG

	if (!ShouldSuppressDebugPacketMsgID(static_cast<USHORT>(MsgID)))

	{

		printf("[TransportConnID:%d]SendMsg:%d\n", WireClient->TransportConnID, MsgID);

	}

#endif

	free(ProtocolHead);





	return sendResult;

}



BOOL SendToClient(std::shared_ptr<ClientNode> Client, short MsgID, const BYTE* Data, DWORD Length, short SrcID, char SrcFE, short DstID, short MsgType, char Encrypt)

{

	// Official single-client traffic targets the live protocol connection, not

	// the legacy constant 1. Fall back only before a protocol ID is assigned.

	const short wireDstID = (Client && Client->ConnID > 0) ? Client->ConnID : DstID;

	return SendToClientInternal(Client, MsgID, Data, Length, SrcID, SrcFE, DstID, wireDstID, MsgType, Encrypt);

}



