static bool IsExpectedPVPLoginFirstPacket(
	const std::shared_ptr<ClientNode>& TransportClient,
	const CSHEAD* ProtocolHead,
	const MSGHEAD* MsgHead,
	const BYTE* Body,
	USHORT WireBodyLen)
{
	constexpr char kPVPFrontEnd = 101;
	constexpr USHORT kPVPLoginWireBodyLen = static_cast<USHORT>(sizeof(USHORT) + sizeof(UINT) * 3);
	if (!TransportClient || !ProtocolHead || !MsgHead || !Body ||
		WireBodyLen != kPVPLoginWireBodyLen || ProtocolHead->BodyFlag == 0 ||
		ntohs(MsgHead->MsgType) != Request || MsgHead->DstFE != kPVPFrontEnd)
	{
		return false;
	}

	BYTE* p = const_cast<BYTE*>(Body);
	const UINT requestUin = Read32(p);
	(void)Read32(p);
	const UINT requestPVPKey = Read32(p);
	const UINT protocolUin = ntohl(ProtocolHead->Uin);
	if (requestUin == 0 || requestUin != protocolUin ||
		TransportClient->TransportConnIDUin != requestUin)
	{
		return false;
	}

	const std::shared_ptr<ClientNode> sessionClient = GetClient(requestUin);
	if (!sessionClient)
		return false;
	const std::shared_ptr<RoomNode> room = GetActiveRaceRoom(sessionClient);
	if (!room || !sessionClient->IsLogin || sessionClient->deleteflag ||
		sessionClient->TaskID != 0xFFFC || room->matchQueueType != 0x0A ||
		room->RankedStartPhase != RankedMatchStartPhase::AwaitEnterRoom ||
		!room->RaceAuthorityValid || room->RaceSeed == 0 ||
		requestPVPKey != room->RaceSeed || room->ServerID < 110 || room->ServerID > 113 ||
		ntohs(MsgHead->DstID) != room->ServerID)
	{
		return false;
	}

	return true;
}

static bool IsExpectedRankedEnterRoomPacket(
	const std::shared_ptr<ClientNode>& SessionClient,
	const CSHEAD* ProtocolHead,
	const MSGHEAD* MsgHead,
	const BYTE* Body,
	USHORT WireBodyLen)
{
	constexpr USHORT kEnterRoomWireBodyLen = static_cast<USHORT>(sizeof(USHORT) + sizeof(UINT) * 3);
	if (!SessionClient || !ProtocolHead || !MsgHead || !Body ||
		WireBodyLen != kEnterRoomWireBodyLen || ProtocolHead->BodyFlag == 0 ||
		ntohs(MsgHead->MsgType) != Request || MsgHead->DstFE != FE_PLAYER)
	{
		return false;
	}

	BYTE* p = const_cast<BYTE*>(Body);
	const UINT requestUin = Read32(p);
	(void)Read32(p);
	const UINT requestRoomID = Read32(p);
	const UINT protocolUin = ntohl(ProtocolHead->Uin);
	if (requestUin == 0 || requestUin != protocolUin ||
		requestUin != SessionClient->Uin ||
		SessionClient->TransportConnIDUin != requestUin ||
		GetClient(requestUin) != SessionClient)
	{
		return false;
	}

	const std::shared_ptr<RoomNode> room = GetActiveRaceRoom(SessionClient);
	if (!room || !SessionClient->IsLogin || SessionClient->deleteflag ||
		SessionClient->TaskID != 0xFFFC || room->matchQueueType != 0x0A ||
		(room->RankedStartPhase != RankedMatchStartPhase::AwaitEnterRoom &&
		 room->RankedStartPhase != RankedMatchStartPhase::EnterRoomComplete) ||
		!room->RaceAuthorityValid || requestRoomID != room->ID ||
		GetBorderRoom(requestRoomID) != room ||
		!GetRankedPVPTransport(SessionClient, room))
	{
		return false;
	}

	return true;
}

static bool IsExpectedRankedBanMapPacket(
	const std::shared_ptr<ClientNode>& SessionClient,
	const CSHEAD* ProtocolHead,
	const MSGHEAD* MsgHead,
	const BYTE* Body,
	USHORT WireBodyLen)
{
	constexpr size_t kFixedPayloadLen = 15;
	if (!SessionClient || !ProtocolHead || !MsgHead || !Body ||
		WireBodyLen < sizeof(USHORT) + kFixedPayloadLen || ProtocolHead->BodyFlag == 0 ||
		ntohs(MsgHead->MsgType) != Request || MsgHead->DstFE != FE_PLAYER)
	{
		return false;
	}

	const size_t payloadLen = WireBodyLen - sizeof(USHORT);
	const UINT requestUin = QQS_ReadBE32(Body);
	const BYTE chooseMapNum = Body[14];
	if (payloadLen != kFixedPayloadLen + static_cast<size_t>(chooseMapNum) * sizeof(UINT) ||
		requestUin == 0 || requestUin != ntohl(ProtocolHead->Uin) ||
		requestUin != SessionClient->Uin ||
		SessionClient->TransportConnIDUin != requestUin ||
		GetClient(requestUin) != SessionClient)
	{
		return false;
	}

	const std::shared_ptr<RoomNode> room = GetActiveRaceRoom(SessionClient);
	return room && SessionClient->IsLogin && !SessionClient->deleteflag &&
		SessionClient->TaskID == 0xFFFC && room->matchQueueType == 0x0A &&
		room->RankedStartPhase == RankedMatchStartPhase::BanMapChoosing &&
		!room->MatchBanMaps.empty() && GetRankedPVPTransport(SessionClient, room) != nullptr;
}

static bool IsExpectedRankedPVPHelloPacket(
	const std::shared_ptr<ClientNode>& PacketClient,
	const CSHEAD* ProtocolHead,
	const MSGHEAD* MsgHead,
	USHORT WireBodyLen)
{
	if (!PacketClient || !ProtocolHead || !MsgHead ||
		WireBodyLen != sizeof(USHORT) || ProtocolHead->BodyFlag == 0 ||
		ntohs(MsgHead->MsgType) != Request || MsgHead->DstFE != FE_PLAYER)
	{
		return false;
	}

	const UINT protocolUin = ntohl(ProtocolHead->Uin);
	if (protocolUin == 0 || PacketClient->TransportConnIDUin != protocolUin)
		return false;
	const std::shared_ptr<ClientNode> sessionClient = GetClient(protocolUin);
	const std::shared_ptr<RoomNode> room = GetActiveRaceRoom(sessionClient);
	const std::shared_ptr<ClientNode> pvpClient = GetRankedPVPTransport(sessionClient, room);
	return sessionClient && room && pvpClient &&
		(PacketClient == sessionClient || PacketClient == pvpClient) &&
		sessionClient->TaskID == 0xFFFC && room->matchQueueType == 0x0A &&
		room->RankedStartPhase >= RankedMatchStartPhase::BanMapResult &&
		room->RankedStartPhase != RankedMatchStartPhase::Failed;
}

static bool IsExpectedCrossWorkerPVPGameplayPacket(
	const std::shared_ptr<ClientNode>& PacketClient,
	const CSHEAD* ProtocolHead,
	const MSGHEAD* MsgHead,
	USHORT WireBodyLen)
{
	if (!CrossServerTestIsWorker() || !PacketClient || !ProtocolHead || !MsgHead ||
		WireBodyLen <= sizeof(USHORT) || ProtocolHead->BodyFlag == 0 ||
		ntohs(MsgHead->MsgType) != Notify || MsgHead->DstFE != FE_GAMELOGIC ||
		!PacketClient->IsLogin || PacketClient->deleteflag ||
		PacketClient->TaskID != 0xFFFD || PacketClient->BorderRoomID == 0)
	{
		return false;
	}

	const UINT protocolUin = ntohl(ProtocolHead->Uin);
	return protocolUin != 0 && protocolUin == PacketClient->Uin &&
		PacketClient->TransportConnIDUin == protocolUin;
}

bool isSeqValid(std::shared_ptr<ClientNode> Client, CSHEAD* ProtocolHead, int MsgID, size_t Length)

{

	u_long currentSeq = htonl(ProtocolHead->Seq); // Convert from network to host byte order



	if (Msgs[MsgID]) {

		Client->HeadSeq = currentSeq; // Update lastSeq to the new valid sequence number

	}

	else {

		if (currentSeq != Client->HeadSeq + 1 || currentSeq == -1) {

			auto ServerLogger = spdlog::get("SpeedServer_logger");//获取日志库实例

			ServerLogger->info("[发包嫌疑:][UIN:{:d}][IP:{:s}][MsgID:{:d}]", Client->Uin, Client->Ip, MsgID);

			ServerLogger->flush();

			//std::cout << "发包嫌疑:"<< MsgID << std::endl;

			return false;

		}

		Client->HeadSeq = currentSeq; // Update lastSeq to the new valid sequence number

	}

	//std::cout <<"currentSeq:"<< currentSeq << "   Client->HeadSeq:" << Client->HeadSeq << std::endl;

	return true;

}

namespace
{
	thread_local const ClientNode* g_CurrentInboundWireMsgSeqClient = nullptr;
	thread_local int g_CurrentInboundWireMsgSeq = -1;
	thread_local int g_CurrentInboundProtocolSeq = -1;

	class ScopedInboundPacketContext
	{
	public:
		ScopedInboundPacketContext(
			const std::shared_ptr<ClientNode>& Client,
			int WireMsgSeq,
			int ProtocolSeq) noexcept
			: PreviousClient(g_CurrentInboundWireMsgSeqClient),
			PreviousMsgSeq(g_CurrentInboundWireMsgSeq),
			PreviousProtocolSeq(g_CurrentInboundProtocolSeq)
		{
			g_CurrentInboundWireMsgSeqClient = Client.get();
			g_CurrentInboundWireMsgSeq = WireMsgSeq;
			g_CurrentInboundProtocolSeq = ProtocolSeq;
		}

		~ScopedInboundPacketContext()
		{
			g_CurrentInboundWireMsgSeqClient = PreviousClient;
			g_CurrentInboundWireMsgSeq = PreviousMsgSeq;
			g_CurrentInboundProtocolSeq = PreviousProtocolSeq;
		}

		ScopedInboundPacketContext(const ScopedInboundPacketContext&) = delete;
		ScopedInboundPacketContext& operator=(const ScopedInboundPacketContext&) = delete;

	private:
		const ClientNode* PreviousClient;
		int PreviousMsgSeq;
		int PreviousProtocolSeq;
	};
}

bool TryGetCurrentInboundWireMsgSeq(const std::shared_ptr<ClientNode>& Client, int& WireMsgSeq)
{
	if (!Client || g_CurrentInboundWireMsgSeqClient != Client.get())
	{
		return false;
	}
	WireMsgSeq = g_CurrentInboundWireMsgSeq;
	return true;
}

bool TryGetCurrentInboundProtocolSeq(const std::shared_ptr<ClientNode>& Client, int& ProtocolSeq)
{
	if (!Client || g_CurrentInboundWireMsgSeqClient != Client.get())
	{
		return false;
	}
	ProtocolSeq = g_CurrentInboundProtocolSeq;
	return true;
}



void OnFullReceive(std::shared_ptr<ClientNode> Client, BYTE* Data, size_t Length)

{



	if (Length < sizeof(CSHEAD))

	{

		Client->IsLogin = FALSE;

		Client->Server->Disconnect(Client->TransportConnID);

		Client->deleteflag = 1;

		return;

	}

	CSHEAD* ProtocolHead = (CSHEAD*)Data;

	BYTE* Body = NULL;

	DWORD HeadLen = sizeof(CSHEAD) + ProtocolHead->OptLength;







	if (ProtocolHead->Ver == 23115)

	{







	}



	if (Length < HeadLen)

	{

		Client->IsLogin = FALSE;

		Client->Server->Disconnect(Client->TransportConnID);

		Client->deleteflag = 1;

		return;

	}

	UINT Uin = ntohl(ProtocolHead->Uin);

	if (Uin) {

		Client->TransportConnIDUin = Uin;

		if (!Client->IsLogin)

		{

			if (ProtocolHead->OptLength)

			{

				Body = (BYTE*)(ProtocolHead + 1);

				char Password[64] = { 0 };

				if (ProtocolHead->OptLength < 64)

				{

					memcpy(Password, Body, ProtocolHead->OptLength);

					if (UserDB_CmpPassword(Uin, Password))

					{

						Client->IsLogin = TRUE;

					}

				}

			}

			if (Clients.find(Uin) != Clients.end())

			{

				Client->IsLogin = TRUE;

			}

			if (Keymode == 1) {

				std::string Key = GetKey(Uin);

				if (Key.empty()) {

					Key = UserDB_GetLoginKey(Uin);

					Keys[Uin] = Key;

				}

				if (!Key.empty()) {

					memcpy(Client->Key, Key.c_str(), 16);

				}

			}

		}

	}



	DWORD BodyLen = Length - HeadLen;

	if (BodyLen >= sizeof(MSGHEAD))

	{

		MSGHEAD* MsgHead = (MSGHEAD*)((DWORD64)Data + HeadLen);

		/*std::cout<< "ProtocolHead:" << htonl(ProtocolHead->Seq) << std::endl;

		std::cout<< "MsgHead:" << htonl(MsgHead->MsgSeq) << std::endl;*/

		if (ProtocolHead->BodyFlag)

		{

			Body = (BYTE*)malloc(BodyLen);

			if (!Body)

			{

				return;

			}

			if (oi_symmetry_decrypt2((BYTE*)MsgHead, BodyLen, Client->Key, Body, (int*)&BodyLen) == false)

			{

				if (isLog == 1) {

					auto ServerLogger = spdlog::get("SpeedServer_logger");

					ServerLogger->info("[OnFullReceive][解密失败][Uin:{:d}][Content:{:d}][Ver:{:d}][BodyFlag:{:d}][IP:{:s}]",

						Uin, Client->TransportConnID, ProtocolHead->Ver, ProtocolHead->BodyFlag, Client->Ip);

					ServerLogger->flush();

				}

				free(Body);

				return;

			}

		}

		else

		{

			Body = (BYTE*)malloc(BodyLen);

			if (!Body)

			{

				return;

			}

			memcpy(Body, MsgHead, BodyLen);

		}



		BYTE* tmpBody = Body;

		MsgHead = (MSGHEAD*)tmpBody;

		tmpBody = (BYTE*)tmpBody + sizeof(MSGHEAD);

		BodyLen = BodyLen - sizeof(MSGHEAD);
		const DWORD AvailablePayloadBytes = BodyLen;



		//printMsgHead(MsgHead);



		if (ProtocolHead->OptLength)

		{

			Client->ServerID = ntohs(MsgHead->DstID);

		}

		else

		{

			int ServerID = ntohs(MsgHead->DstID);

			if (ServerID >= 110 && ServerID < 115)

			{

				Client->ServerID = ServerID;

			}

		}

		const unsigned short MsgID = ntohs(MsgHead->MsgID);

		const unsigned short BodyLen = ntohs(MsgHead->BodyLen);
		if ((MsgID == 1 || MsgID == 3 || MsgID == 131 || MsgID == 153 || MsgID == 165 ||
			MsgID == 697 || MsgID == 703 || MsgID == 2102 || MsgID == 2103 || MsgID == 20082 ||
			MsgID == 25010 || MsgID == 28346) &&
			(BodyLen < 2 || static_cast<DWORD>(BodyLen - 2) != AvailablePayloadBytes))
		{
			free(Body);
			return;
		}
		const USHORT inboundProtocolVersion = ntohs(static_cast<USHORT>(ProtocolHead->Ver));
		if (inboundProtocolVersion == 0 ||
			(Client->ProtocolVersion != 0 && Client->ProtocolVersion != inboundProtocolVersion))
		{
			free(Body);
			return;
		}
		Client->ProtocolVersion = inboundProtocolVersion;



		if (QQS_DebugUin10001Enabled() &&
			(Uin == 10001 || Client->Uin == 10001 || Client->TransportConnIDUin == 10001 || Client->TransportConnID == 10001)

			&& !ShouldSuppressDebugPacketMsgID(MsgID))

		{

			printf("[RECV-10001] TransportConnID=%d Uin=%u ClientUin=%u TransportConnIDUin=%u MsgID=%u MsgType=%d BodyLen=%u ProtoSeq=%d MsgSeq=%d SrcFE=%d SrcID=%d DstFE=%d DstID=%d BodyFlag=%d OptLength=%u\n",

				Client->TransportConnID,

				Uin,

				Client->Uin,

				Client->TransportConnIDUin,

				MsgID,

				(int)ntohs(MsgHead->MsgType),

				BodyLen,

				(int)ntohl(ProtocolHead->Seq),

				(int)ntohl(MsgHead->MsgSeq),

				(int)MsgHead->SrcFE,

				(int)ntohs(MsgHead->SrcID),

				(int)MsgHead->DstFE,

				(int)ntohs(MsgHead->DstID),

				(int)ProtocolHead->BodyFlag,

				(unsigned)ProtocolHead->OptLength);

			fflush(stdout);

		}



		if (isLog == 1 && MsgID != 153 && !ShouldSuppressDebugPacketMsgID(MsgID)) {

			auto ServerLogger = spdlog::get("SpeedServer_logger");

			ServerLogger->info("[OnRecvFromClient][TransportConnID:{:d}][Uin:{:d}][MsgID:{:d}][BodyLen:{:d}][Ver:{:d}][BodyFlag:{:d}][IP:{:s}]",

				Client->TransportConnID, Uin, MsgID, BodyLen, ProtocolHead->Ver, ProtocolHead->BodyFlag, Client->Ip);

		}





		const bool expectedPVPLogin = MsgID == 697 &&
			(IsExpectedPVPLoginFirstPacket(Client, ProtocolHead, MsgHead, tmpBody, BodyLen) ||
			 CrossServerTestIsExpectedWorkerPVPLoginPacket(Client, ProtocolHead, MsgHead, tmpBody, BodyLen));
		const bool expectedRankedEnterRoom = MsgID == 20082 &&
			(IsExpectedRankedEnterRoomPacket(Client, ProtocolHead, MsgHead, tmpBody, BodyLen) ||
			 CrossServerTestIsExpectedLobbyEnterRoomPacket(Client, ProtocolHead, MsgHead, tmpBody, BodyLen) ||
			 CrossServerTestIsExpectedWorkerEnterRoomPacket(Client, ProtocolHead, MsgHead, tmpBody, BodyLen));
		const bool expectedRankedBanMap = MsgID == 25010 &&
			IsExpectedRankedBanMapPacket(Client, ProtocolHead, MsgHead, tmpBody, BodyLen);
		const bool expectedRankedPVPHello = MsgID == 703 &&
			(IsExpectedRankedPVPHelloPacket(Client, ProtocolHead, MsgHead, BodyLen) ||
			 CrossServerTestIsExpectedWorkerPVPHelloPacket(Client, ProtocolHead, MsgHead, BodyLen));
		const bool expectedCrossWorkerPVPGameplay = MsgID == 28346 &&
			IsExpectedCrossWorkerPVPGameplayPacket(
				Client, ProtocolHead, MsgHead, BodyLen);
		if (PreventSDP[0] > 0) {

			if (expectedPVPLogin || expectedRankedEnterRoom ||
				expectedRankedBanMap || expectedRankedPVPHello ||
				expectedCrossWorkerPVPGameplay)
			{
				// Official PVP handoff/control packets use their own stream sequence;
				// only packets whose ranked room state and identity were verified above
				// bypass the ordinary player-stream increment check.
				Client->HeadSeq = htonl(ProtocolHead->Seq);
			}
			else if (!isSeqValid(Client, ProtocolHead, MsgID, Length)) {

				free(Body);

				return;

			}

		}



		const ScopedInboundPacketContext inboundPacketContext(
			Client,
			static_cast<int>(ntohl(MsgHead->MsgSeq)),
			static_cast<int>(ntohl(ProtocolHead->Seq)));
		OnRecvFromClient(Client, MsgID, tmpBody, BodyLen);



		free(Body);

	}

	else

	{

		//printf("[TransportConnID:%d]不支持请求检查更新\n", Client->TransportConnID);

		Client->IsLogin = FALSE;

		Client->Server->Disconnect(Client->TransportConnID);

		Client->deleteflag = 1;

	}



}



