void RequestSwitchInterface(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)

{

	BYTE* pReq = Body;

	USHORT WireLen = 0;

	if (BodyLen >= 2)

	{

		BYTE* pLen = pReq;

		WireLen = Read16(pLen);

		if (WireLen == BodyLen || WireLen == BodyLen - 2) pReq = pLen;

	}

	UINT Uin = Read32(pReq);

	UINT Time = Read32(pReq);

	BYTE InterfaceType = 0;

	if ((size_t)(pReq - Body) < BodyLen) InterfaceType = Read8(pReq);



	QQS_DebugPrintf10001("[151] RequestSwitchInterface Uin=%u ReqUin=%u BodyLen=%zu WireLen=%u InterfaceType=%u\n", Client ? Client->Uin : 0, Uin, BodyLen, WireLen, InterfaceType);

	if (InterfaceType == 2)

	{

		ResponseMapChallengeSwitchInterfaceNotice(Client);

		return;

	}



	ResponseSwitchInterface(Client);

}

void ResponseSwitchInterface(std::shared_ptr<ClientNode> Client)

{

	std::vector<BYTE> buf(819200); BYTE* p = buf.data(); size_t len;



	Write16(p, 0); //ResultID

	Write32(p, 0); //Uin



	len = p - buf.data();

	SendToClient(Client, 151, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);

}

