static size_t Shape317SeqSize(const YAML::Node& node)
{
	return (node && node.IsSequence()) ? node.size() : 0;
}

static int Shape317YamlInt(const YAML::Node& node, const char* key, int defaultValue = 0)
{
	if (!node || !node[key]) return defaultValue;
	return node[key].as<int>();
}

static std::string Shape317YamlString(const YAML::Node& node, const char* key, const std::string& defaultValue = std::string())
{
	if (!node || !node[key]) return defaultValue;
	return node[key].as<std::string>();
}

static void Shape317WriteString8(BYTE*& p, const std::string& value)
{
	Write8(p, static_cast<BYTE>(value.size()));
	if (!value.empty())
	{
		memcpy(p, value.data(), value.size());
		p += value.size();
	}
}

static std::string Shape317HexPrefix(const BYTE* data, size_t len, size_t maxLen = 16)
{
	static const char* hex = "0123456789ABCDEF";
	std::string out;
	if (!data || len == 0 || maxLen == 0) return out;
	const size_t n = (len < maxLen) ? len : maxLen;
	out.reserve(n * 3);
	for (size_t i = 0; i < n; ++i)
	{
		if (i) out.push_back(' ');
		const BYTE b = data[i];
		out.push_back(hex[(b >> 4) & 0x0F]);
		out.push_back(hex[b & 0x0F]);
	}
	return out;
}

static void Shape317WriteRefitEffect(BYTE*& p, const YAML::Node& effect)
{
	BYTE* pEffect = p;
	Write16(pEffect, 0); // len
	Write16(pEffect, static_cast<WORD>(Shape317YamlInt(effect, "EffectID", 0)));
	Write8(pEffect, static_cast<BYTE>(Shape317YamlInt(effect, "Level", 0)));
	Write32(pEffect, static_cast<DWORD>(Shape317YamlInt(effect, "Value1", 0)));
	Write32(pEffect, static_cast<DWORD>(Shape317YamlInt(effect, "Value2", 0)));
	Shape317WriteString8(pEffect, Shape317YamlString(effect, "Resource"));
	Shape317WriteString8(pEffect, Shape317YamlString(effect, "EffectRes"));
	Write8(pEffect, static_cast<BYTE>(Shape317YamlInt(effect, "Grade", 0)));
	Set16(p, static_cast<WORD>(pEffect - p));
	p = pEffect;
}

static void Shape317WriteRefitSuit(BYTE*& p, const YAML::Node& suit)
{
	BYTE* pSuit = p;
	Write16(pSuit, 0); // len
	Write32(pSuit, static_cast<DWORD>(Shape317YamlInt(suit, "KartID", 0)));
	Shape317WriteString8(pSuit, Shape317YamlString(suit, "KarNameLen"));

	const YAML::Node refitItems = suit["RefitItemList"];
	const size_t refitItemNum = Shape317SeqSize(refitItems);
	Write8(pSuit, static_cast<BYTE>(refitItemNum));
	for (size_t i = 0; i < refitItemNum; ++i)
	{
		Write32(pSuit, static_cast<DWORD>(refitItems[i].as<int>()));
	}

	const YAML::Node effects = suit["RefitEffects"];
	const size_t effectNum = Shape317SeqSize(effects);
	Write8(pSuit, static_cast<BYTE>(effectNum));
	for (size_t i = 0; i < effectNum; ++i)
	{
		Shape317WriteRefitEffect(pSuit, effects[i]);
	}

	Write16(pSuit, static_cast<WORD>(Shape317YamlInt(suit, "Grade", 0)));
	Write16(pSuit, static_cast<WORD>(Shape317YamlInt(suit, "DressPoint", 0)));
	Write16(pSuit, static_cast<WORD>(Shape317YamlInt(suit, "CarLibraryCollectValue", 0)));

	Write8(pSuit, 0); // RefitModifyNum
	Write8(pSuit, 0); // HasTurnModify
	Write32(pSuit, static_cast<DWORD>(Shape317YamlInt(suit, "ShapeSuitID", 0)));

	const YAML::Node additions = suit["RefitAdditionList"];
	if (Shape317SeqSize(additions) > 0)
	{
		const size_t additionNum = Shape317SeqSize(additions);
		Write8(pSuit, static_cast<BYTE>(additionNum));
		for (size_t i = 0; i < additionNum; ++i)
		{
			Write32(pSuit, static_cast<DWORD>(additions[i].as<int>()));
		}
	}
	else
	{
		// 官服普通皮肤这里固定 4 个 0。
		Write8(pSuit, 4);
		Write32(pSuit, 0);
		Write32(pSuit, 0);
		Write32(pSuit, 0);
		Write32(pSuit, 0);
	}

	Shape317WriteString8(pSuit, Shape317YamlString(suit, "GradeResourceLen"));
	Write8(pSuit, 0); // m_ucHasKartPhysParam
	Write8(pSuit, 0); // m_uchPhysInfoCount

	const YAML::Node similarList = suit["SimilarShapeList"];
	const size_t similarNum = Shape317SeqSize(similarList);
	Write8(pSuit, static_cast<BYTE>(similarNum));
	for (size_t i = 0; i < similarNum; ++i)
	{
		Write32(pSuit, static_cast<DWORD>(similarList[i].as<int>()));
	}

	Set16(p, static_cast<WORD>(pSuit - p));
	p = pSuit;
}

static void Shape317WriteLegendEffect(BYTE*& p, const KartShapeRefitLegendRefitEffectsCfg& effect)
{
	BYTE* pEffect = p;
	Write16(pEffect, 0); // len
	Write16(pEffect, effect.EffectID);
	Write8(pEffect, effect.Level);
	Write32(pEffect, effect.Value1);
	Write32(pEffect, effect.Value2);
	Shape317WriteString8(pEffect, effect.Resource);
	Shape317WriteString8(pEffect, effect.EffectRes);
	Write8(pEffect, effect.Grade);
	Set16(p, static_cast<WORD>(pEffect - p));
	p = pEffect;
}

static void Shape317WriteConsumInfo(BYTE*& p, const KartShapeRefitLegendMaxConsumCfg& consum)
{
	BYTE* pConsum = p;
	Write16(pConsum, 0); // len
	Write32(pConsum, consum.ItemID);
	Write32(pConsum, consum.ItemNum);
	Write32(pConsum, static_cast<DWORD>(consum.ItemPeriod));
	Set16(p, static_cast<WORD>(pConsum - p));
	p = pConsum;
}

static void Shape317WriteLegend(BYTE*& p, const KartShapeRefitLegendInfo& legend)
{
	BYTE* pLegend = p;
	Write16(pLegend, 0); // len
	Write32(pLegend, legend.KartID);
	Shape317WriteString8(pLegend, legend.KarName);
	Write16(pLegend, legend.Grade);
	Shape317WriteString8(pLegend, legend.GradeResource);

	Write8(pLegend, static_cast<BYTE>(legend.LevelInfo.size()));
	for (const auto& level : legend.LevelInfo)
	{
		BYTE* pLevel = pLegend;
		Write16(pLevel, 0); // len
		Write8(pLevel, level.Level);
		Write8(pLevel, 0); // RefitItemNum
		Write8(pLevel, static_cast<BYTE>(level.RefitEffectsInfo.size()));
		for (const auto& effect : level.RefitEffectsInfo)
		{
			Shape317WriteLegendEffect(pLevel, effect);
		}
		Write16(pLevel, level.DressPoint);
		Write16(pLevel, level.CarLibraryCollectValue);
		Write8(pLevel, 0); // RefitModifyNum
		Write8(pLevel, 0); // HasTurnModify
		Write32(pLevel, level.ShapeSuitID);
		Write8(pLevel, static_cast<BYTE>(level.ConsumInfo.size()));
		for (const auto& consum : level.ConsumInfo)
		{
			Shape317WriteConsumInfo(pLevel, consum);
		}
		Write8(pLevel, 0); // m_ucHasKartPhysPara
		Write8(pLevel, 0); // m_uchPhysInfoCount
		Set16(pLegend, static_cast<WORD>(pLevel - pLegend));
		pLegend = pLevel;
	}

	Write32(pLegend, legend.ShapeSuitID);
	Shape317WriteConsumInfo(pLegend, legend.MaxConsumInfo);
	Write8(pLegend, legend.LegendSkinType);
	Set16(p, static_cast<WORD>(pLegend - p));
	p = pLegend;
}

static void Shape317WriteColorCfg(BYTE*& p, const KartShapeColorInfo& color)
{
	BYTE* pColorCfg = p;
	Write16(pColorCfg, 0); // len
	Write32(pColorCfg, color.MainShapeSuitID);
	Write16(pColorCfg, color.ColorShapeNum);

	for (const auto& shape : color.ShapeList)
	{
		BYTE* pColorShape = pColorCfg;
		Write16(pColorShape, 0); // len
		Write32(pColorShape, shape.ShapeSuitID);
		Shape317WriteString8(pColorShape, shape.KarName);
		Write16(pColorShape, shape.Grade);
		Shape317WriteString8(pColorShape, shape.GradeResource);
		Write16(pColorShape, shape.CarLibraryCollectValue);
		Set16(pColorCfg, static_cast<WORD>(pColorShape - pColorCfg));
		pColorCfg = pColorShape;
	}

	Set16(p, static_cast<WORD>(pColorCfg - p));
	p = pColorCfg;
}

void ResponseGetShapeRefitCfgTest(std::shared_ptr<ClientNode> Client)
{
	YAML::Node ShapeRefitCfg = YAML::LoadFile(".\\Config\\ShapeRefitCfg.yml");
	const YAML::Node suits = ShapeRefitCfg["ShapeRefitLefend"];
	const size_t suitTotal = Shape317SeqSize(suits);

	std::vector<KartShapeRefitLegendInfo> legendCfg = getLegendarySkin();
	std::vector<KartShapeColorInfo> colorCfg = getShapeColorCfg();

	constexpr size_t kOfficialSuitChunk = 50;
	constexpr size_t kOfficialLegendChunk = 5;
	const size_t chunkCount = std::max<size_t>(1, (suitTotal + kOfficialSuitChunk - 1) / kOfficialSuitChunk);

	for (size_t chunk = 0; chunk < chunkCount; ++chunk)
	{
		std::vector<BYTE> buf(819200);
		BYTE* p = buf.data();
		// SendToClient 会把 MSGHEAD.BodyLen 写成 payload_len + 2。
		// 官服抓包 body_hex 前 2 字节是 MSGHEAD.BodyLen，不是 payload 字段；这里不能重复写。
		Write16(p, 0); // ResultID

		const size_t startIndex = chunk * kOfficialSuitChunk;
		const size_t suitRemain = (startIndex < suitTotal) ? (suitTotal - startIndex) : 0;
		const size_t suitCount = (suitRemain < kOfficialSuitChunk) ? suitRemain : kOfficialSuitChunk;
		Write16(p, static_cast<WORD>(suitCount)); // KartShapeRefitSuitNum
		for (size_t i = 0; i < suitCount; ++i)
		{
			Shape317WriteRefitSuit(p, suits[startIndex + i]);
		}

		const size_t legendStart = chunk * kOfficialLegendChunk;
		const size_t legendRemain = (legendStart < legendCfg.size()) ? (legendCfg.size() - legendStart) : 0;
		const size_t legendCount = (legendRemain < kOfficialLegendChunk) ? legendRemain : kOfficialLegendChunk;
		Write16(p, static_cast<WORD>(legendCount)); // KartShapeRefitLegendNum
		for (size_t i = 0; i < legendCount; ++i)
		{
			Shape317WriteLegend(p, legendCfg[legendStart + i]);
		}

		const BYTE hasMoreInfo = (chunk + 1 < chunkCount) ? 1 : 0;
		Write8(p, hasMoreInfo); // HasMoreInfo: 官服续包标记，不等待不延迟
		if (chunk == 0)
		{
			Write16(p, 0); // KartOriginNum

			Write16(p, static_cast<WORD>(colorCfg.size())); // KartShapeColorCfgNum
			for (const auto& color : colorCfg)
			{
				Shape317WriteColorCfg(p, color);
			}

			Write16(p, 0); // BufferCarNum
		}
		else
		{
			Write16(p, 0); // KartOriginNum
			Write16(p, 0); // BufferCarNum，714 官服尾部只有 HasMore + OriginNum + BufferCarNum
		}

		const size_t len = p - buf.data();
		const int msgId = (chunk == 0) ? 317 : 714;
		const WORD wireBodyLen = static_cast<WORD>(len + sizeof(USHORT));
		const std::string prefix = Shape317HexPrefix(buf.data(), len);
		if (auto ServerLogger = spdlog::get("SpeedServer_logger"))
		{
			ServerLogger->info("[FLOW][SHAPE-317714-SEND][Uin:{:d}][TransportConnID:{:d}][MsgID:{:d}][Chunk:{:d}/{:d}][PayloadLen:{:d}][WireBodyLen:{:d}][SuitCount:{:d}][LegendCount:{:d}][HasMore:{:d}][Prefix:{:s}]",
				Client ? Client->Uin : 0,
				Client ? Client->TransportConnID : 0,
				msgId,
				static_cast<int>(chunk + 1),
				static_cast<int>(chunkCount),
				static_cast<int>(len),
				static_cast<int>(wireBodyLen),
				static_cast<int>(suitCount),
				static_cast<int>(legendCount),
				static_cast<int>(hasMoreInfo),
				prefix.c_str());
			ServerLogger->flush();
		}
		QQS_DebugPrintf10001("[FLOW][SHAPE-317714-SEND] Uin=%u TransportConnID=%d MsgID=%d Chunk=%zu/%zu PayloadLen=%zu WireBodyLen=%u SuitCount=%zu LegendCount=%zu HasMore=%u Prefix=%s\n",
			Client ? Client->Uin : 0,
			Client ? Client->TransportConnID : 0,
			msgId,
			chunk + 1,
			chunkCount,
			len,
			static_cast<unsigned>(wireBodyLen),
			suitCount,
			legendCount,
			static_cast<unsigned>(hasMoreInfo),
			prefix.c_str());
		SendToClient(Client, msgId, buf.data(), static_cast<DWORD>(len), Client->ConnID, FE_PLAYER, 1, Response);
	}
}



void RequestWeRelayCommonCfg(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)

{

	UINT Uin = Read32(Body);

	UINT Time = Read32(Body);



	ResponseWeRelayCommonCfg(Client);

}

