void RequestClientVerify(std::shared_ptr<ClientNode> Client)

{

	std::vector<BYTE> buf(819200); BYTE* p = buf.data();  size_t len;

	{ //Head

		BYTE* pHead = p;

		Write16(pHead, 0); //len



		Write32(pHead, Client->Uin); //Uin

		Write32(pHead, (DWORD)time(nullptr)); //Time

		Write8(pHead, 0); //Version

		Write8(pHead, 0); //Compress

		Write8(pHead, 0); //OptLength



		len = pHead - p;

		Set16(p, (WORD)len);

		p += len;

	}

	{ //Body

		BYTE* pBody = p;

		Write16(pBody, 0); //len

		Write16(pBody, 31); //MsgLen

		memcpy(pBody, "OnNotifyServerVerify", 21);

		pBody += 22;



		Write8(pBody, 246);



		double intValue = Client->ServeryVerifyKey;

		std::memcpy(pBody, &intValue, sizeof(double));

		pBody += sizeof(double);



		Write16(pBody, 0);





		len = pBody - p;

		Set16(p, (WORD)len);

		p += len;

	}

	len = p - buf.data();

	SendToClient(Client, 24251, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);

}





static void WriteQuickRPCShortText(BYTE*& p, const std::string& text)

{

	std::string out = text;

	if (out.size() > 255) {

		out.resize(255);

	}

	WriteText(p, out.c_str(), (DWORD)out.size());

}



static void WriteQuickRPCFuncName(BYTE*& p, const char* funcName)

{

	DWORD len = (DWORD)strlen(funcName);

	memcpy(p, funcName, len);

	p += len;

	Write16(p, 0);

}



static BYTE QuickRPCHexByteLen(const char* hex)

{

	if (!hex) {

		return 0;

	}

	size_t n = strlen(hex) / 2;

	return (n > 255) ? 255 : (BYTE)n;

}



static void WriteQuickRPCTextHex(BYTE*& p, const char* gbkHex)

{

	Write8(p, 250);

	Write8(p, QuickRPCHexByteLen(gbkHex));

	if (gbkHex && gbkHex[0] != 0) {

		WriteHex(p, gbkHex);

	}

}



static void WriteQuickRPCTextValueString(BYTE*& p, const char* key, const char* value)

{

	WriteText(p, key);

	WriteText(p, value ? value : "");

}



static void WriteQuickRPCTextValueHex(BYTE*& p, const char* key, const char* gbkHex)

{

	WriteText(p, key);

	WriteQuickRPCTextHex(p, gbkHex);

}



static double ReadQuickRPCDoubleParam(const BYTE* msg, USHORT msgLen, int paramIndex, double defaultValue)

{

	if (!msg || msgLen == 0 || paramIndex < 0) {

		return defaultValue;

	}



	int seen = 0;

	for (USHORT i = 0; i + 9 <= msgLen; ++i) {

		if (msg[i] != 0xF6) {

			continue;

		}



		double value = defaultValue;

		memcpy(&value, msg + i + 1, sizeof(double));

		if (seen == paramIndex) {

			return value;

		}

		++seen;

		i += 8;

	}



	return defaultValue;

}



static std::string QuickRPCBytesToHex(const std::vector<BYTE>& data)

{

	static const char kHex[] = "0123456789ABCDEF";

	std::string out;

	out.reserve(data.size() * 2);

	for (BYTE b : data) {

		out.push_back(kHex[(b >> 4) & 0x0F]);

		out.push_back(kHex[b & 0x0F]);

	}

	return out;

}



static std::vector<BYTE> BuildQuickRPCCapturedTemplateResponse(const char* capturedHex, double contextID)

{

	auto hexNibble = [](char c) -> BYTE {

		if (c >= '0' && c <= '9') return (BYTE)(c - '0');

		if (c >= 'A' && c <= 'F') return (BYTE)(c - 'A' + 10);

		if (c >= 'a' && c <= 'f') return (BYTE)(c - 'a' + 10);

		return 0;

	};



	size_t hexLen = strlen(capturedHex);

	std::vector<BYTE> msg;

	msg.reserve(hexLen / 2);

	for (size_t i = 0; i + 1 < hexLen; i += 2) {

		msg.push_back((BYTE)((hexNibble(capturedHex[i]) << 4) | hexNibble(capturedHex[i + 1])));

	}



	for (size_t i = 0; i + 10 <= msg.size(); ++i) {

		if (msg[i] == 0 && msg[i + 1] == 0 && msg[i + 2] == 0xF6) {

			memcpy(msg.data() + i + 3, &contextID, sizeof(double));

			break;

		}

	}

	return msg;

}



static bool PatchQuickRPCNamedDouble(std::vector<BYTE>& msg, const char* key, double value)

{

	if (!key || !*key || msg.empty()) return false;

	const size_t keyLen = strlen(key);

	for (size_t i = 0; i + keyLen + 1 + sizeof(double) <= msg.size(); ++i) {

		if (memcmp(msg.data() + i, key, keyLen) != 0) continue;

		const size_t searchLimit = i + keyLen + 24;

		const size_t searchEnd = (msg.size() < searchLimit) ? msg.size() : searchLimit;

		for (size_t j = i + keyLen; j + 1 + sizeof(double) <= searchEnd; ++j) {

			if (msg[j] != 0xF6) continue;

			memcpy(msg.data() + j + 1, &value, sizeof(double));

			return true;

		}

	}

	return false;

}



static std::vector<BYTE> BuildQuickRPCSimpleDoubleResponse(double contextID, double value)

{

	std::vector<BYTE> msg(128);

	BYTE* p = msg.data();

	WriteQuickRPCFuncName(p, "DispatchCoResponse");

	WriteValue(p, contextID);

	WriteValue(p, value);

	msg.resize((size_t)(p - msg.data()));

	return msg;

}


// AMF3 字符串字典计数器。官服每写入一个 FA 文本都会占用新索引，
// 即使字段名重复也不能自行复用，否则后续 FB 引用会整体错位。
struct Beta87LoginCfgStringTable
{
	size_t NextIndex = 0;

	BYTE WriteNew(BYTE*& p, const char* text)
	{
		const BYTE index = static_cast<BYTE>(NextIndex++);
		WriteText(p, text);
		return index;
	}
};

static void WriteBeta87LoginCfgNumber(
	BYTE*& p,
	Beta87LoginCfgStringTable& strings,
	const char* key,
	int value)
{
	// 写入一个“配置名 -> 数值”字段；重复名称仍按官服重新登记字符串。
	strings.WriteNew(p, key);
	WriteValue(p, value);
}

// 写入 OriginCarSysThemeCfg 的单个主题项。
// ID/Open 使用前面已经登记的字符串索引，不能照抄某个 Dump 中的 FB 字节。
static void WriteBeta87LoginCfgThemeEntry(
	BYTE*& p,
	BYTE idKeyIndex,
	BYTE openKeyIndex,
	int id,
	bool open)
{
	WriteValue(p, id);
	BYTE* entryLen = WriteLenValueStart(p);
	BYTE* entry = p;
	WriteKeyIndex(entry, idKeyIndex);
	WriteValue(entry, id);
	WriteKeyIndex(entry, openKeyIndex);
	if (open) WriteF8(entry); else WriteF9(entry);
	WriteLenValueEnd(p, entry, entryLen);
}

// 构造 Co.Beta87_GetLoginCfg 对应的 DispatchCoResponse 业务体。
// contextID 必须回显当前请求；配置字段和值来自新版官服 Dump 的共同结构。
static std::vector<BYTE> BuildBeta87GetLoginCfgResponse(double contextID)
{
	// AuroraDistanceCullOverride 中官服固定下发的四个数值键。
	// Dump 只能证明这些完整键值，尚不能证明它们是普通车辆 ID，不能擅自去掉 0x40000000 标记位。
	static const int kAuroraOverrideKeys[] =
	{
		1074003220,
		1073839366,
		1073840390,
		1073955092,
	};
	// ForbidRoleCardKartLst 的官服固定列表；顺序和重复项都必须原样保留。
	static const int kForbidRoleCardKartIds[] =
	{
		15225, 122201, 136712, 146566, 123509, 71459, 121864, 14735,
		144546, 96787, 139751, 146565, 157743, 116741, 17923, 18932,
		18933, 19294, 19624, 19625, 19963, 20454, 22098, 24411,
		24930, 25400, 26585, 157743, 157744, 157741, 157742, 158389,
		158390, 158391, 158392, 158393, 158394, 158395, 113681, 80172,
		146563, 15224, 122207, 162506, 162507, 167869, 168664, 171051,
		171052, 171054, 171047,
	};

	std::vector<BYTE> msg(4096);
	BYTE* p = msg.data();

	// QuickRPC 返回头：函数名、当前请求的 ContextID、Result=0。
	WriteQuickRPCFuncName(p, "DispatchCoResponse");
	WriteValue(p, contextID);
	WriteValue(p, 0);

	// 根配置表长度先占位，全部字段写完后再按实际长度回填。
	BYTE* rootLen = WriteLenValueStart(p);
	BYTE* root = p;
	Beta87LoginCfgStringTable strings;

	// 字段顺序和编码类型属于官服协议结构，不能排序、去重或添加保底字段。
	WriteBeta87LoginCfgNumber(root, strings, "OtherPlayerResetTime_PlayerReset", 2000);
	WriteBeta87LoginCfgNumber(root, strings, "EnableForceTransDataViaSvrByTCP", 1);
	WriteBeta87LoginCfgNumber(root, strings, "XiaoPenCoolDownTime", 500);
	WriteBeta87LoginCfgNumber(root, strings, "ShowSignin", 1);
	WriteBeta87LoginCfgNumber(root, strings, "QuickRaceEnableCancelMatch", 0);
	WriteBeta87LoginCfgNumber(root, strings, "RoomStayMarkClearOnRelogin", 1);
	// 官服字段名原本就是 Persent，不能擅自改成 Percent。
	WriteBeta87LoginCfgNumber(root, strings, "NetPersentPerFrame", 1000);
	WriteBeta87LoginCfgNumber(root, strings, "RoomStayMarkTimeoutSeconds", 300);
	WriteBeta87LoginCfgNumber(root, strings, "DisableClientReplaceTeamPower", 0);
	WriteBeta87LoginCfgNumber(root, strings, "Disable_PlayerSkipUpdateByLod", 1);
	WriteBeta87LoginCfgNumber(root, strings, "TopListOptimize", 1);
	WriteBeta87LoginCfgNumber(root, strings, "RoomStayMarkClearAfterNGames", 1);
	WriteBeta87LoginCfgNumber(root, strings, "OpenSingleRaceMultiplayerMatch", 1);
	WriteBeta87LoginCfgNumber(root, strings, "RoomStayMarkEnabled", 1);
	WriteBeta87LoginCfgNumber(root, strings, "EnableAirFrictionRatio", 0);

	// 每辆车对应 4 组距离裁剪参数：1=60、2=65、3=100、4=500。
	strings.WriteNew(root, "AuroraDistanceCullOverride");
	BYTE* auroraLen = WriteLenValueStart(root);
	BYTE* aurora = root;
	for (size_t i = 0; i < sizeof(kAuroraOverrideKeys) / sizeof(kAuroraOverrideKeys[0]); ++i)
	{
		WriteValue(aurora, kAuroraOverrideKeys[i]);
		BYTE* distanceLen = WriteLenValueStart(aurora);
		BYTE* distance = aurora;
		WriteValue(distance, 1);
		WriteValue(distance, 60);
		WriteValue(distance, 2);
		WriteValue(distance, 65);
		WriteValue(distance, 3);
		WriteValue(distance, 100);
		WriteValue(distance, 4);
		WriteValue(distance, 500);
		WriteLenValueEnd(aurora, distance, distanceLen);
	}
	WriteLenValueEnd(root, aurora, auroraLen);

	WriteBeta87LoginCfgNumber(root, strings, "EnableInGameStoneTips", 1);
	WriteBeta87LoginCfgNumber(root, strings, "IsNewRecordSnapshot", 0);
	WriteBeta87LoginCfgNumber(root, strings, "DisableAsyncLoad", 0);
	WriteBeta87LoginCfgNumber(root, strings, "TransAllTCP", 1);

	// 列表键从 1 开始；其中官服重复出现的 157743 也必须保留。
	strings.WriteNew(root, "ForbidRoleCardKartLst");
	BYTE* forbidLen = WriteLenValueStart(root);
	BYTE* forbid = root;
	for (size_t i = 0; i < sizeof(kForbidRoleCardKartIds) / sizeof(kForbidRoleCardKartIds[0]); ++i)
	{
		WriteValue(forbid, static_cast<int>(i + 1));
		WriteValue(forbid, kForbidRoleCardKartIds[i]);
	}
	WriteLenValueEnd(root, forbid, forbidLen);

	// 官服当前下发的是空表，不额外补入地图。
	strings.WriteNew(root, "UnsupportedMap");
	BYTE* unsupportedLen = WriteLenValueStart(root);
	BYTE* unsupported = root;
	WriteLenValueEnd(root, unsupported, unsupportedLen);

	// 此字段使用 AMF3 true（F8），不是数值 1。
	strings.WriteNew(root, "Enable_VelvetSimulatorParallelUpdate");
	WriteF8(root);
	WriteBeta87LoginCfgNumber(root, strings, "RoomCustomOBDisabled", 0);
	// 官服根表中第二次出现 EnableAsyncLoad，必须保留该重复字段。
	WriteBeta87LoginCfgNumber(root, strings, "EnableAsyncLoad", 0);
	WriteBeta87LoginCfgNumber(root, strings, "RoomStayMarkClearOnTimeout", 1);
	WriteBeta87LoginCfgNumber(root, strings, "UseOriTransLogic", 1);
	WriteBeta87LoginCfgNumber(root, strings, "RoomStayMarkNGamesThreshold", 1);
	WriteBeta87LoginCfgNumber(root, strings, "DefaultDeadResetTime", 1000);
	WriteBeta87LoginCfgNumber(root, strings, "IsUrlWithSign", 0);
	WriteBeta87LoginCfgNumber(root, strings, "MiscellaneousDlg", 0);
	WriteBeta87LoginCfgNumber(root, strings, "LearnSkillConfigKartID", 1);
	WriteBeta87LoginCfgNumber(root, strings, "EnableClientSuperN2OFix", 1);
	WriteBeta87LoginCfgNumber(root, strings, "DiamondTipBubble", 0);

	// 原点赛车主题配置：首项登记 ID/Open，后续项使用动态取得的字典索引引用。
	strings.WriteNew(root, "OriginCarSysThemeCfg");
	BYTE* originLen = WriteLenValueStart(root);
	BYTE* origin = root;

	WriteValue(origin, 171054);
	BYTE* kart171054Len = WriteLenValueStart(origin);
	BYTE* kart171054 = origin;

	WriteValue(kart171054, 1);
	BYTE* firstThemeLen = WriteLenValueStart(kart171054);
	BYTE* firstTheme = kart171054;
	const BYTE idKeyIndex = strings.WriteNew(firstTheme, "ID");
	WriteValue(firstTheme, 1);
	const BYTE openKeyIndex = strings.WriteNew(firstTheme, "Open");
	WriteF8(firstTheme);
	WriteLenValueEnd(kart171054, firstTheme, firstThemeLen);
	WriteBeta87LoginCfgThemeEntry(kart171054, idKeyIndex, openKeyIndex, 2, true);
	WriteLenValueEnd(origin, kart171054, kart171054Len);

	WriteValue(origin, 150543);
	BYTE* kart150543Len = WriteLenValueStart(origin);
	BYTE* kart150543 = origin;
	WriteBeta87LoginCfgThemeEntry(kart150543, idKeyIndex, openKeyIndex, 1, true);
	WriteBeta87LoginCfgThemeEntry(kart150543, idKeyIndex, openKeyIndex, 2, true);
	WriteBeta87LoginCfgThemeEntry(kart150543, idKeyIndex, openKeyIndex, 3, false);
	WriteBeta87LoginCfgThemeEntry(kart150543, idKeyIndex, openKeyIndex, 4, false);
	WriteLenValueEnd(origin, kart150543, kart150543Len);
	WriteLenValueEnd(root, origin, originLen);

	WriteBeta87LoginCfgNumber(root, strings, "LockFrameAtEnd", 1);
	WriteBeta87LoginCfgNumber(root, strings, "WMQueueInUpdate", 0);
	WriteBeta87LoginCfgNumber(root, strings, "Win7Enable64", 1);
	// 按本次实际编码结果回填根表长度，禁止写死 Dump 中的长度偏移。
	WriteLenValueEnd(p, root, rootLen);

	msg.resize(static_cast<size_t>(p - msg.data()));
	return msg;
}




