static int FMH_RoundToInt(double value)
{
	return value >= 0 ? static_cast<int>(value + 0.5) : static_cast<int>(value - 0.5);
}

static double FMH_ReadDoubleValue(const BYTE* p)
{
	double value = 0;
	memcpy(&value, p, sizeof(double));
	return value;
}

static std::vector<int> FMH_ParseNumbers(BYTE* msg, size_t msgLen)
{
	std::vector<int> values;
	size_t start = 0;
	for (size_t i = 0; i + 1 < msgLen; ++i)
	{
		if (msg[i] == 0 && msg[i + 1] == 0)
		{
			start = i + 2;
			break;
		}
	}
	for (size_t i = start; i + 9 <= msgLen;)
	{
		if (msg[i] == 246)
		{
			values.push_back(FMH_RoundToInt(FMH_ReadDoubleValue(msg + i + 1)));
			i += 9;
			continue;
		}
		++i;
	}
	return values;
}

static std::vector<int> FMH_NormalizePairs(const std::vector<int>& pairs, int requiredPairs)
{
	std::vector<int> out;
	int maxPairs = requiredPairs > 0 ? requiredPairs : 10;
	for (size_t i = 0; i + 1 < pairs.size() && static_cast<int>(out.size() / 2) < maxPairs; i += 2)
	{
		int slot = pairs[i] > 0 ? pairs[i] : static_cast<int>(out.size() / 2) + 1;
		int group = pairs[i + 1];
		if (group < 0) continue;
		out.push_back(slot);
		out.push_back(group);
	}
	return out;
}

static std::vector<int> FMH_ParseSelectPairs(BYTE* msg, size_t msgLen, int requiredPairs)
{
	std::vector<int> nums = FMH_ParseNumbers(msg, msgLen);
	std::vector<int> pairs;
	if (nums.size() > 1) pairs.assign(nums.begin() + 1, nums.end());
	return FMH_NormalizePairs(pairs, requiredPairs);
}

static std::vector<int> FMH_CompletePairs(const std::vector<int>& pairs, const std::vector<int>& fallbackPairs, int requiredPairs)
{
	int maxPairs = requiredPairs > 0 ? requiredPairs : 10;
	std::vector<int> groups(static_cast<size_t>(maxPairs) + 1, -1);
	std::vector<int> fallback = FMH_NormalizePairs(fallbackPairs, requiredPairs);
	for (size_t i = 0; i + 1 < fallback.size(); i += 2)
	{
		int slot = fallback[i];
		if (slot > 0 && slot <= maxPairs && fallback[i + 1] >= 0) groups[slot] = fallback[i + 1];
	}
	std::vector<int> normalized = FMH_NormalizePairs(pairs, requiredPairs);
	for (size_t i = 0; i + 1 < normalized.size(); i += 2)
	{
		int slot = normalized[i];
		if (slot > 0 && slot <= maxPairs && normalized[i + 1] >= 0) groups[slot] = normalized[i + 1];
	}
	std::vector<int> out;
	for (int slot = 1; slot <= maxPairs; ++slot)
	{
		if (groups[slot] < 0) continue;
		out.push_back(slot);
		out.push_back(groups[slot]);
	}
	return out;
}

static std::string FMH_FormatPairs(const std::vector<int>& pairs)
{
	std::string out;
	for (size_t i = 0; i + 1 < pairs.size(); i += 2)
	{
		if (!out.empty()) out += ",";
		out += std::to_string(pairs[i]);
		out += ":";
		out += std::to_string(pairs[i + 1]);
	}
	return out;
}

static int FMH_YIntAny(const YAML::Node& node, std::initializer_list<const char*> keys, int def)
{
	for (const char* key : keys)
	{
		if (node && node[key])
		{
			try { return node[key].as<int>(); } catch (...) { return def; }
		}
	}
	return def;
}

static bool FMH_YBoolAny(const YAML::Node& node, std::initializer_list<const char*> keys, bool def)
{
	for (const char* key : keys)
	{
		if (node && node[key])
		{
			try { return node[key].as<bool>(); } catch (...) { return def; }
		}
	}
	return def;
}

static void FMH_AddUniquePath(std::vector<std::string>& paths, const std::string& path)
{
	if (path.empty()) return;
	for (const auto& oldPath : paths)
	{
		if (_stricmp(oldPath.c_str(), path.c_str()) == 0) return;
	}
	paths.push_back(path);
}

static std::string FMH_DirName(const std::string& path)
{
	size_t pos = path.find_last_of("\\/");
	return pos == std::string::npos ? std::string() : path.substr(0, pos);
}

static YAML::Node FMH_LoadRootNode(std::string* loadedPath = nullptr)
{
	std::vector<std::string> paths;
	FMH_AddUniquePath(paths, "./24251/FinalMagicHouse.yml");
	FMH_AddUniquePath(paths, "./Config/FinalMagicHouse.yml");
	FMH_AddUniquePath(paths, "./x64/Release/24251/FinalMagicHouse.yml");
	FMH_AddUniquePath(paths, "24251/FinalMagicHouse.yml");
	FMH_AddUniquePath(paths, "Config/FinalMagicHouse.yml");
	char modulePath[MAX_PATH] = { 0 };
	DWORD moduleLen = GetModuleFileNameA(NULL, modulePath, MAX_PATH);
	if (moduleLen > 0 && moduleLen < MAX_PATH)
	{
		std::string exeDir = FMH_DirName(modulePath);
		FMH_AddUniquePath(paths, exeDir + "/24251/FinalMagicHouse.yml");
		FMH_AddUniquePath(paths, exeDir + "/Config/FinalMagicHouse.yml");
		FMH_AddUniquePath(paths, exeDir + "/../../24251/FinalMagicHouse.yml");
		FMH_AddUniquePath(paths, exeDir + "/../../Config/FinalMagicHouse.yml");
	}
	for (const std::string& path : paths)
	{
		try
		{
			YAML::Node file = YAML::LoadFile(path);
			YAML::Node root = file["final_magic_house"] ? file["final_magic_house"] : file;
			if (root)
			{
				if (loadedPath) *loadedPath = path;
				return root;
			}
		}
		catch (const std::exception&) {}
	}
	if (loadedPath) loadedPath->clear();
	return YAML::Node();
}

static std::vector<int> FMH_ParsePairsNode(const YAML::Node& node, int requiredPairs)
{
	std::vector<int> pairs;
	std::vector<int> flat;
	if (!node || !node.IsSequence()) return pairs;
	for (size_t i = 0; i < node.size(); ++i)
	{
		YAML::Node row = node[i];
		if (row.IsMap())
		{
			int slot = FMH_YIntAny(row, { "slot", "Slot", "index" }, static_cast<int>(i) + 1);
			int group = FMH_YIntAny(row, { "group_index", "groupIndex", "GroupIndex", "group" }, 0);
			if (group > 0) { pairs.push_back(slot); pairs.push_back(group); }
		}
		else if (row.IsSequence() && row.size() >= 2)
		{
			try { pairs.push_back(row[0].as<int>()); pairs.push_back(row[1].as<int>()); } catch (...) {}
		}
		else if (row.IsScalar())
		{
			try { flat.push_back(row.as<int>()); } catch (...) {}
		}
	}
	if (pairs.empty() && !flat.empty()) pairs = flat;
	return FMH_NormalizePairs(pairs, requiredPairs);
}

static int FMH_SelectItemIdToItemIndex(int itemId)
{
	switch (itemId)
	{
	case 169630: case 169617: return 39;
	case 169638: case 169625: return 38;
	case 116398: case 116388: return 37;
	case 116406: case 116396: return 36;
	case 159208: case 159198: return 35;
	case 159216: case 159206: return 34;
	case 151460: case 151450: return 33;
	case 151468: case 151458: return 32;
	case 166944: case 166934: return 31;
	case 166952: case 166942: return 30;
	case 119660: case 119650: return 29;
	case 119668: case 119658: return 28;
	case 147060: case 147050: return 27;
	case 147068: case 147058: return 26;
	case 137787: case 137777: return 25;
	case 137795: case 137785: return 24;
	case 167127: case 167117: return 23;
	case 167135: case 167125: return 22;
	case 121383: case 121373: return 21;
	case 121391: case 121381: return 20;
	case 117394: case 117384: return 19;
	case 117402: case 117392: return 18;
	case 154814: case 154804: return 17;
	case 154822: case 154812: return 16;
	case 164137: case 164127: return 15;
	case 164145: case 164135: return 14;
	case 121307: case 121297: return 13;
	case 121315: case 121305: return 12;
	case 114408: case 114398: return 11;
	case 114416: case 114406: return 10;
	case 155174: case 155164: return 9;
	case 155182: case 155172: return 8;
	case 164177: case 164167: return 7;
	case 164185: case 164175: return 6;
	case 132324: case 132314: return 5;
	case 132332: case 132322: return 4;
	case 130461: case 130451: return 3;
	case 130469: case 130459: return 2;
	case 154734: case 154724: return 1;
	case 154742: case 154732: return 0;
	default: break;
	}
	return -1;
}

static bool FMH_IsKnownSelectItemIndex(int itemIndex)
{
	return itemIndex >= 0 && itemIndex <= 39;
}

static int FMH_YSelectItemIndexAny(const YAML::Node& node, std::initializer_list<const char*> keys)
{
	int itemId = FMH_YIntAny(node, keys, 0);
	if (itemId <= 0) return -1;
	int itemIndex = FMH_SelectItemIdToItemIndex(itemId);
	if (itemIndex >= 0) return itemIndex;
	return FMH_IsKnownSelectItemIndex(itemId) ? itemId : -1;
}

static std::vector<int> FMH_ParseItemIdsNode(const YAML::Node& node, int requiredPairs)
{
	std::vector<int> pairs;
	if (!node || !node.IsSequence()) return pairs;
	int maxPairs = requiredPairs > 0 ? requiredPairs : 10;
	for (size_t i = 0; i < node.size() && static_cast<int>(pairs.size() / 2) < maxPairs; ++i)
	{
		YAML::Node row = node[i];
		int slot = static_cast<int>(pairs.size() / 2) + 1;
		int itemIndex = 0;
		if (row.IsMap())
		{
			slot = FMH_YIntAny(row, { "slot", "Slot", "index" }, slot);
			itemIndex = FMH_YSelectItemIndexAny(row, { "item_id", "itemId", "ItemID", "id", "male_item_id", "female_item_id" });
		}
		else if (row.IsScalar())
		{
			try
			{
				int itemId = row.as<int>();
				itemIndex = FMH_SelectItemIdToItemIndex(itemId);
				if (itemIndex < 0 && FMH_IsKnownSelectItemIndex(itemId)) itemIndex = itemId;
			}
			catch (...) {}
		}
		if (itemIndex < 0) continue;
		pairs.push_back(slot > 0 ? slot : static_cast<int>(pairs.size() / 2) + 1);
		pairs.push_back(itemIndex);
	}
	return FMH_NormalizePairs(pairs, requiredPairs);
}

static std::vector<int> FMH_ParseTabsNode(const YAML::Node& node, int requiredPairs)
{
	std::vector<int> pairs;
	if (!node || !node.IsSequence()) return pairs;
	int maxPairs = requiredPairs > 0 ? requiredPairs : 10;
	for (size_t i = 0; i < node.size() && static_cast<int>(pairs.size() / 2) < maxPairs; ++i)
	{
		YAML::Node row = node[i];
		int tab = static_cast<int>(i) + 1;
		YAML::Node items;
		if (row.IsMap())
		{
			tab = FMH_YIntAny(row, { "tab", "tab_index", "tabIndex", "Tab" }, tab);
			items = row["items"] ? row["items"] : (row["item_ids"] ? row["item_ids"] : row["default_item_ids"]);
		}
		else if (row.IsSequence())
		{
			items = row;
		}
		if (!items || !items.IsSequence()) continue;
		for (size_t j = 0; j < items.size() && j < 2 && static_cast<int>(pairs.size() / 2) < maxPairs; ++j)
		{
			int itemIndex = 0;
			YAML::Node itemNode = items[j];
			if (itemNode.IsMap()) itemIndex = FMH_YSelectItemIndexAny(itemNode, { "item_id", "itemId", "ItemID", "id", "male_item_id", "female_item_id" });
			else if (itemNode.IsScalar())
			{
				try
				{
					int itemId = itemNode.as<int>();
					itemIndex = FMH_SelectItemIdToItemIndex(itemId);
					if (itemIndex < 0 && FMH_IsKnownSelectItemIndex(itemId)) itemIndex = itemId;
				}
				catch (...) {}
			}
			if (itemIndex < 0) continue;
			int groupSlot = (tab - 1) * 2 + static_cast<int>(j) + 1;
			if (groupSlot <= 0 || groupSlot > maxPairs) continue;
			pairs.push_back(groupSlot);
			pairs.push_back(itemIndex);
		}
	}
	return FMH_NormalizePairs(pairs, requiredPairs);
}

static int FMH_DefaultNeedByGroup(int groupIndex)
{
	switch (groupIndex)
	{
	case 1: return 40;
	case 2: return 50;
	case 3: return 60;
	case 4: return 70;
	case 5: return 80;
	case 6: return 100;
	case 7: return 100;
	case 8: return 120;
	case 9: return 150;
	case 10: return 160;
	default: return 0;
	}
}

static int FMH_FindItemIndexInCfgItems(const std::vector<FinalMagicHouseCfgEntry>& items, int itemId, int groupIndex = 0)
{
	for (const auto& item : items)
	{
		if (groupIndex > 0 && item.GroupIndex != groupIndex) continue;
		if (item.MaleItemID == itemId || item.FemaleItemID == itemId) return item.ItemIndex;
	}
	return -1;
}

static int FMH_NormalizeCurrentRound(const FinalMagicHouseStateRow& state)
{
	int round = state.CurrentRound > 0 ? state.CurrentRound : (state.DrawCount + 1);
	if (round <= state.DrawCount) round = state.DrawCount + 1;
	return round > 0 ? round : 1;
}

static int FMH_CostForRound(const FinalMagicHouseRuntimeCfg& cfg, int round)
{
	static const int kDefaultRoundCosts[] = { 1, 2, 3, 5, 10, 12, 18, 20, 25, 30 };
	if (round <= 0) round = 1;
	if (round <= static_cast<int>(sizeof(kDefaultRoundCosts) / sizeof(kDefaultRoundCosts[0])))
	{
		return kDefaultRoundCosts[round - 1];
	}
	return cfg.CostNumOnce >= 0 ? kDefaultRoundCosts[sizeof(kDefaultRoundCosts) / sizeof(kDefaultRoundCosts[0]) - 1] : 1;
}

static int FMH_AwardItemIndex(const FinalMagicHouseRuntimeCfg& cfg, const FinalMagicHouseAwardCfg& award)
{
	if (award.ItemIndex >= 0) return award.ItemIndex;
	int itemIndex = FMH_FindItemIndexInCfgItems(cfg.CfgItems, award.ItemID);
	if (itemIndex >= 0) return itemIndex;
	for (const auto& row : cfg.Awards)
	{
		if (row.ItemID == award.ItemID && row.ItemIndex >= 0) return row.ItemIndex;
	}
	return -1;
}

static int FMH_NormalizeGotItemIndex(const FinalMagicHouseRuntimeCfg& cfg, int rawValue)
{
	if (rawValue >= 0 && rawValue <= 999) return rawValue;
	int itemIndex = FMH_FindItemIndexInCfgItems(cfg.CfgItems, rawValue);
	if (itemIndex >= 0) return itemIndex;
	for (const auto& award : cfg.Awards)
	{
		if (award.ItemID == rawValue && award.ItemIndex >= 0) return award.ItemIndex;
	}
	return -1;
}

static std::vector<int> FMH_ParseGotItemData(const FinalMagicHouseRuntimeCfg& cfg, const std::string& gotItemData)
{
	std::vector<int> got;
	size_t start = 0;
	while (start < gotItemData.size())
	{
		size_t end = gotItemData.find(';', start);
		std::string token = gotItemData.substr(start, end == std::string::npos ? std::string::npos : end - start);
		size_t sep = token.find(':');
		if (sep != std::string::npos)
		{
			int drawNo = atoi(token.substr(0, sep).c_str());
			int rawItemIndex = atoi(token.substr(sep + 1).c_str());
			int itemIndex = FMH_NormalizeGotItemIndex(cfg, rawItemIndex);
			if (drawNo > 0 && itemIndex >= 0)
			{
				got.push_back(drawNo);
				got.push_back(itemIndex);
			}
		}
		if (end == std::string::npos) break;
		start = end + 1;
	}
	return got;
}

static FinalMagicHouseCfgEntry FMH_ParseCfgItemNode(const YAML::Node& node, int tabIndex, int groupIndex, int fallbackItemIndex, int fallbackNeed)
{
	FinalMagicHouseCfgEntry item;
	item.TabIndex = tabIndex;
	item.GroupIndex = groupIndex;
	item.ItemIndex = fallbackItemIndex;
	item.NeedCallonItemNums = fallbackNeed;
	if (node.IsMap())
	{
		item.MaleItemID = FMH_YIntAny(node, { "item_id", "itemId", "ItemID", "id", "male_item_id" }, 0);
		item.FemaleItemID = FMH_YIntAny(node, { "female_item_id", "femaleItemId", "FemaleItemID" }, 0);
		item.ItemIndex = FMH_YIntAny(node, { "item_index", "itemIndex", "ItemIndex" }, item.ItemIndex);
		item.ItemNum = FMH_YIntAny(node, { "item_num", "itemNum", "ItemNum", "num" }, item.ItemNum);
		item.ItemType = FMH_YIntAny(node, { "item_type", "itemType", "ItemType", "type" }, item.ItemType);
		item.AvailPeriod = FMH_YIntAny(node, { "avail_period", "availPeriod", "AvailPeriod", "period" }, item.AvailPeriod);
		item.NeedCallonItemNums = FMH_YIntAny(node, { "need_callon_item_nums", "need", "needCallon" }, item.NeedCallonItemNums);
	}
	else if (node.IsScalar())
	{
		try { item.MaleItemID = node.as<int>(); } catch (...) { item.MaleItemID = 0; }
	}
	int mapped = FMH_SelectItemIdToItemIndex(item.MaleItemID);
	if (mapped >= 0) item.ItemIndex = mapped;
	return item;
}

static void FMH_ParseTabsCfgNode(const YAML::Node& tabs, int requiredPairs, std::vector<FinalMagicHouseCfgEntry>& cfgItems, std::vector<int>& defaultPairs)
{
	if (!tabs || !tabs.IsSequence()) return;
	std::vector<FinalMagicHouseCfgEntry> baseItems;
	for (const auto& item : cfgItems)
	{
		if (item.TabIndex <= 0) baseItems.push_back(item);
	}
	std::vector<FinalMagicHouseCfgEntry> customItems;
	std::vector<int> selectedPairs;
	int customItemIndex = 1000;
	for (size_t ti = 0; ti < tabs.size(); ++ti)
	{
		YAML::Node tabNode = tabs[ti];
		int tabIndex = static_cast<int>(ti) + 1;
		if (tabNode.IsMap()) tabIndex = FMH_YIntAny(tabNode, { "tab", "tab_index", "tabIndex", "Tab" }, tabIndex);
		YAML::Node groups = tabNode.IsMap() ? (tabNode["groups"] ? tabNode["groups"] : tabNode["items"]) : YAML::Node();
		if (!groups || !groups.IsSequence()) continue;
		for (size_t gi = 0; gi < groups.size(); ++gi)
		{
			YAML::Node groupNode = groups[gi];
			int groupIndex = (tabIndex - 1) * 2 + static_cast<int>(gi) + 1;
			if (groupNode.IsMap()) groupIndex = FMH_YIntAny(groupNode, { "group", "group_index", "groupIndex", "GroupIndex" }, groupIndex);
			YAML::Node itemList = groupNode.IsMap() ? (groupNode["items"] ? groupNode["items"] : groupNode["candidates"]) : groupNode;
			if (!itemList || !itemList.IsSequence()) continue;
			int need = FMH_YIntAny(groupNode, { "need", "need_callon_item_nums" }, FMH_DefaultNeedByGroup(groupIndex));
			for (size_t ii = 0; ii < itemList.size(); ++ii)
			{
				FinalMagicHouseCfgEntry item = FMH_ParseCfgItemNode(itemList[ii], tabIndex, groupIndex, customItemIndex++, need);
				if (item.MaleItemID <= 0 || item.ItemIndex < 0) continue;
				customItems.push_back(item);
			}
			int defItemId = groupNode.IsMap() ? FMH_YIntAny(groupNode, { "default", "default_item_id", "selected", "selected_item_id" }, 0) : 0;
			if (defItemId > 0)
			{
				int itemIndex = FMH_FindItemIndexInCfgItems(customItems, defItemId, groupIndex);
				if (itemIndex >= 0)
				{
					selectedPairs.push_back(groupIndex);
					selectedPairs.push_back(itemIndex);
				}
			}
		}
	}
	if (!customItems.empty())
	{
		cfgItems = baseItems;
		cfgItems.insert(cfgItems.end(), customItems.begin(), customItems.end());
	}
	if (!selectedPairs.empty()) defaultPairs = FMH_CompletePairs(selectedPairs, defaultPairs, requiredPairs);
}

static FinalMagicHouseRuntimeCfg FMH_LoadRuntimeCfg()
{
	FinalMagicHouseRuntimeCfg cfg;
	cfg.DefaultPairs = FMH_DefaultSelectedPairs();
	cfg.CfgItems = FMH_DefaultCfgItems();
	cfg.Awards.push_back(FinalMagicHouseAwardCfg());
	try
	{
		std::string loadedPath;
		YAML::Node root = FMH_LoadRootNode(&loadedPath);
		cfg.ConfigPath = loadedPath;
		cfg.ConfigLoaded = root ? true : false;
		if (!root) return cfg;
		cfg.Enabled = FMH_YBoolAny(root, { "enabled" }, cfg.Enabled);
		cfg.ActivityId = static_cast<UINT>(FMH_YIntAny(root, { "activity_id", "activityId" }, static_cast<int>(cfg.ActivityId)));
		cfg.DisabledResultCode = FMH_YIntAny(root, { "disabled_result_code", "disabledResultCode" }, cfg.DisabledResultCode);
		YAML::Node cost = root["cost"];
		cfg.CostItemID = FMH_YIntAny(cost, { "item_id", "itemId", "CostItemID" }, cfg.CostItemID);
		cfg.CostNumOnce = FMH_YIntAny(cost, { "once", "num", "CostNumOnce" }, cfg.CostNumOnce);
		cfg.StrictCost = FMH_YBoolAny(cost, { "strict_cost", "strictCost" }, cfg.StrictCost);
		cfg.NoTicketResultCode = FMH_YIntAny(cost, { "no_ticket_result_code", "noTicketResultCode" }, cfg.NoTicketResultCode);
		YAML::Node draw = root["draw"];
		cfg.StrictCost = FMH_YBoolAny(draw, { "strict_cost", "strictCost" }, cfg.StrictCost);
		YAML::Node select = root["select"];
		cfg.RequiredPairs = FMH_YIntAny(select, { "required_pairs", "requiredPairs" }, cfg.RequiredPairs);
		FMH_ParseTabsCfgNode(select["tabs"] ? select["tabs"] : root["tabs"], cfg.RequiredPairs, cfg.CfgItems, cfg.DefaultPairs);
		std::vector<int> yamlPairs = FMH_ParseTabsNode(select["default_tabs"] ? select["default_tabs"] : root["default_tabs"], cfg.RequiredPairs);
		if (yamlPairs.empty()) yamlPairs = FMH_ParseItemIdsNode(select["default_item_ids"] ? select["default_item_ids"] : root["default_item_ids"], cfg.RequiredPairs);
		if (yamlPairs.empty()) yamlPairs = FMH_ParsePairsNode(select["default_pairs"] ? select["default_pairs"] : root["default_pairs"], cfg.RequiredPairs);
		if (!yamlPairs.empty()) cfg.DefaultPairs = FMH_CompletePairs(yamlPairs, cfg.DefaultPairs, cfg.RequiredPairs);
		YAML::Node awards = root["award_pool"] ? root["award_pool"]["items"] : root["awards"];
		if (awards && awards.IsSequence())
		{
			std::vector<FinalMagicHouseAwardCfg> parsed;
			for (size_t i = 0; i < awards.size(); ++i)
			{
				YAML::Node row = awards[i];
				FinalMagicHouseAwardCfg award;
				award.ItemID = FMH_YIntAny(row, { "item_id", "itemId", "ItemID" }, 0);
				award.ItemNum = FMH_YIntAny(row, { "item_num", "itemNum", "ItemNum", "num" }, 1);
				award.ItemType = FMH_YIntAny(row, { "item_type", "itemType", "ItemType", "type" }, 2);
				award.AvailPeriod = FMH_YIntAny(row, { "avail_period", "availPeriod", "AvailPeriod", "period" }, 0);
				award.Weight = FMH_YIntAny(row, { "weight", "Weight", "probability" }, 1);
				award.SpecialFlag = FMH_YIntAny(row, { "special_flag", "specialFlag" }, static_cast<int>(i) + 1);
				award.ItemIndex = FMH_YIntAny(row, { "item_index", "itemIndex", "ItemIndex", "award_index", "awardIndex" }, FMH_FindItemIndexInCfgItems(cfg.CfgItems, award.ItemID));
				award.Round = FMH_YIntAny(row, { "round", "Round", "draw_round", "drawRound" }, static_cast<int>(i) + 1);
				if (award.ItemID > 0) parsed.push_back(award);
			}
			if (!parsed.empty()) cfg.Awards = parsed;
		}
	}
	catch (const std::exception& e)
	{
		QQS_DebugPrintf10001("[FinalMagicHouse] Load FinalMagicHouse.yml failed, use defaults: %s\n", e.what());
	}
	return cfg;
}

static std::vector<int> FMH_LoadSelectedPairsForClient(std::shared_ptr<ClientNode> Client, const FinalMagicHouseRuntimeCfg& cfg)
{
	std::vector<int> pairs;
	if (Client) PlayerDB_FMH_LoadSelectedGroups(Client->Uin, cfg.ActivityId, pairs);
	pairs = FMH_NormalizePairs(pairs, cfg.RequiredPairs);
	if (pairs.empty()) pairs = FMH_NormalizePairs(cfg.DefaultPairs, cfg.RequiredPairs);
	else pairs = FMH_CompletePairs(pairs, cfg.DefaultPairs, cfg.RequiredPairs);
	return pairs;
}

static FinalMagicHouseAwardCfg FMH_PickAward(const FinalMagicHouseRuntimeCfg& cfg, UINT uin, int drawNo)
{
	FinalMagicHouseAwardCfg fallback;
	if (cfg.Awards.empty()) return fallback;
	for (const auto& award : cfg.Awards)
	{
		if (award.Round == drawNo) return award;
	}
	int total = 0;
	for (const auto& award : cfg.Awards) total += award.Weight > 0 ? award.Weight : 1;
	if (total <= 0) return cfg.Awards.front();
	UINT seed = (uin * 1103515245u) + static_cast<UINT>(drawNo * 12345 + 97);
	int pick = static_cast<int>(seed % static_cast<UINT>(total));
	for (const auto& award : cfg.Awards)
	{
		int w = award.Weight > 0 ? award.Weight : 1;
		if (pick < w) return award;
		pick -= w;
	}
	return cfg.Awards.back();
}

static void FMH_AppendGotItemData(FinalMagicHouseStateRow& state, const FinalMagicHouseRuntimeCfg& cfg, const FinalMagicHouseAwardCfg& award)
{
	int itemIndex = FMH_AwardItemIndex(cfg, award);
	if (itemIndex < 0) return;
	if (!state.GotItemData.empty()) state.GotItemData += ";";
	state.GotItemData += std::to_string(state.DrawCount);
	state.GotItemData += ":";
	state.GotItemData += std::to_string(itemIndex);
	if (state.GotItemData.size() > 2000) state.GotItemData = state.GotItemData.substr(state.GotItemData.size() - 2000);
}

static size_t FMH_FindAscii(const std::vector<BYTE>& data, const char* key)
{
	size_t keyLen = strlen(key);
	if (keyLen == 0 || data.size() < keyLen) return std::string::npos;
	for (size_t i = 0; i + keyLen <= data.size(); ++i)
	{
		bool ok = true;
		for (size_t j = 0; j < keyLen; ++j)
		{
			if (data[i + j] != static_cast<BYTE>(key[j])) { ok = false; break; }
		}
		if (ok) return i;
	}
	return std::string::npos;
}

static bool FMH_OverwriteSelectedPairs(std::vector<BYTE>& msg, const std::vector<int>& selectedPairs)
{
	std::vector<int> pairs = FMH_NormalizePairs(selectedPairs, 10);
	if (pairs.size() != 20) return false;
	size_t keyPos = FMH_FindAscii(msg, "iAlreadySelectItemIndex");
	if (keyPos == std::string::npos) return false;
	size_t blockPos = keyPos + strlen("iAlreadySelectItemIndex");
	if (blockPos + 5 > msg.size() || msg[blockPos] != 253) return false;
	DWORD len = (static_cast<DWORD>(msg[blockPos + 1]) << 24) | (static_cast<DWORD>(msg[blockPos + 2]) << 16) | (static_cast<DWORD>(msg[blockPos + 3]) << 8) | static_cast<DWORD>(msg[blockPos + 4]);
	if (len != pairs.size() * 9 || blockPos + 5 + len > msg.size()) return false;
	BYTE* p = msg.data() + blockPos + 5;
	for (int value : pairs) WriteValue(p, value);
	return true;
}

static void FMH_WriteAwardResult(BYTE*& p, const FinalMagicHouseAwardCfg& award)
{
	WriteTextValue(p, "m_sItemNum", 1);
	WriteText(p, "m_astItemInfo");
	BYTE* itemsLen = WriteLenValueStart(p);
	BYTE* items = p;
	WriteValue(items, 1);
	BYTE* itemLen = WriteLenValueStart(items);
	BYTE* item = items;
	WriteTextValue(item, "m_iAvailPeriod", award.AvailPeriod);
	WriteTextValue(item, "m_ushItemType", award.ItemType);
	WriteTextValue(item, "m_iItemID", award.ItemID);
	WriteTextValue(item, "m_iItemNum", award.ItemNum);
	WriteLenValueEnd(items, item, itemLen);
	WriteLenValueEnd(p, items, itemsLen);
}

static std::vector<BYTE> BuildFinalMagicHouseAwardResponse(double contextID, const FinalMagicHouseAwardCfg& award)
{
	std::vector<BYTE> msg(1024);
	BYTE* p = msg.data();
	WriteQuickRPCFuncName(p, "DispatchCoResponse");
	WriteValue(p, contextID);
	WriteValue(p, 0);
	BYTE* rootLen = WriteLenValueStart(p);
	BYTE* root = p;
	FMH_WriteAwardResult(root, award);
	WriteLenValueEnd(p, root, rootLen);
	msg.resize(static_cast<size_t>(p - msg.data()));
	return msg;
}

static void FMH_WriteTextInt(BYTE*& p, const char* key, int value)
{
	WriteText(p, key);
	WriteValue(p, value);
}

static void FMH_WriteSelectedPairsBlock(BYTE*& root, const std::vector<int>& selectedPairs, int requiredPairs)
{
	std::vector<int> pairs = FMH_NormalizePairs(selectedPairs, requiredPairs);
	WriteText(root, "iAlreadySelectItemIndex");
	BYTE* selectedLen = WriteLenValueStart(root);
	BYTE* selected = root;
	for (int value : pairs) WriteValue(selected, value);
	WriteLenValueEnd(root, selected, selectedLen);
}

static void FMH_WriteCfgEntry(BYTE*& pool, const FinalMagicHouseCfgEntry& cfgItem, int marker)
{
	WriteValue(pool, marker);
	BYTE* itemLen = WriteLenValueStart(pool);
	BYTE* item = pool;
	FMH_WriteTextInt(item, "availperiod", cfgItem.AvailPeriod);
	if (cfgItem.TabIndex > 0) FMH_WriteTextInt(item, "tab_index", cfgItem.TabIndex);
	if (cfgItem.GroupIndex > 0) FMH_WriteTextInt(item, "group_index", cfgItem.GroupIndex);
	FMH_WriteTextInt(item, "itemnum", cfgItem.ItemNum);
	FMH_WriteTextInt(item, "item_type", cfgItem.ItemType);
	WriteText(item, "genderitem");
	BYTE* genderLen = WriteLenValueStart(item);
	BYTE* gender = item;
	WriteValue(gender, 1);
	WriteValue(gender, cfgItem.MaleItemID);
	if (cfgItem.FemaleItemID > 0)
	{
		WriteValue(gender, 2);
		WriteValue(gender, cfgItem.FemaleItemID);
	}
	WriteLenValueEnd(item, gender, genderLen);
	FMH_WriteTextInt(item, "item_index", cfgItem.ItemIndex);
	FMH_WriteTextInt(item, "need_callon_item_nums", cfgItem.NeedCallonItemNums);
	WriteLenValueEnd(pool, item, itemLen);
}

static std::vector<BYTE> FMH_BuildDynamicCfgResponse(double contextID, const FinalMagicHouseRuntimeCfg& cfg, const std::vector<int>& selectedPairs, const FinalMagicHouseStateRow& state)
{
	std::vector<BYTE> msg(32768);
	BYTE* p = msg.data();
	WriteQuickRPCFuncName(p, "DispatchCoResponse");
	WriteValue(p, contextID);
	WriteValue(p, 0);
	BYTE* rootLen = WriteLenValueStart(p);
	BYTE* root = p;
	int currentRound = FMH_NormalizeCurrentRound(state);
	int costNum = FMH_CostForRound(cfg, currentRound);
	std::vector<int> gotItems = FMH_ParseGotItemData(cfg, state.GotItemData);
	FMH_WriteTextInt(root, "iCostItemID", cfg.CostItemID);
	WriteText(root, "iAlreadyGotItemIndex");
	BYTE* gotLen = WriteLenValueStart(root);
	BYTE* got = root;
	for (int value : gotItems) WriteValue(got, value);
	WriteLenValueEnd(root, got, gotLen);
	FMH_WriteTextInt(root, "iCloseDate", 20260530);
	FMH_WriteSelectedPairsBlock(root, selectedPairs, cfg.RequiredPairs);
	FMH_WriteTextInt(root, "iOpenTime", 0);
	FMH_WriteTextInt(root, "iCloseTime", 235959);
	WriteText(root, "award_poll_cfg");
	BYTE* poolLen = WriteLenValueStart(root);
	BYTE* pool = root;
	int marker = 1;
	for (const auto& cfgItem : cfg.CfgItems)
	{
		if (cfgItem.MaleItemID <= 0 || cfgItem.ItemIndex < 0) continue;
		FMH_WriteCfgEntry(pool, cfgItem, marker++);
	}
	WriteLenValueEnd(root, pool, poolLen);
	FMH_WriteTextInt(root, "iCostItenNum", costNum);
	FMH_WriteTextInt(root, "iCurrentRound", currentRound);
	FMH_WriteTextInt(root, "iOpenDate", 20260501);
	WriteLenValueEnd(p, root, rootLen);
	msg.resize(static_cast<size_t>(p - msg.data()));
	return msg;
}

