static bool IsSameMatchQueueClient(const std::shared_ptr<ClientNode>& QueueClient, const std::shared_ptr<ClientNode>& Client)

{

	if (!QueueClient || !Client)

	{

		return false;

	}

	if (QueueClient == Client)

	{

		return true;

	}

	if (Client->Uin != 0 && QueueClient->Uin == Client->Uin)

	{

		return true;

	}

	if (Client->TransportConnID != 0 && QueueClient->TransportConnID == Client->TransportConnID)

	{

		return true;

	}

	if (Client->TransportConnIDUin != 0 && QueueClient->TransportConnIDUin == Client->TransportConnIDUin)

	{

		return true;

	}

	return false;

}


static bool IsExactMatchQueueClient(const std::shared_ptr<ClientNode>& QueueClient, const std::shared_ptr<ClientNode>& Client)

{

	if (!QueueClient || !Client)

	{

		return false;

	}

	if (QueueClient == Client)

	{

		return true;

	}

	if (Client->TransportConnID != 0 &&
		Client->TransportConnID != 0 && Client->TransportConnID != 0xFFFF &&
		QueueClient->TransportConnID == Client->TransportConnID &&
		QueueClient->TransportConnID == Client->TransportConnID)

	{

		return true;

	}

	return false;

}



int CancelRankedMatch(std::shared_ptr<ClientNode> Client)

{

	if (!Client)

	{

		return 0;

	}

	std::lock_guard<std::recursive_mutex> lg(RankedQueueMutex);



	int removed = 0;

	for (auto it = RankedMatchQueue.begin(); it != RankedMatchQueue.end(); /* no increment here */)

	{

		if (IsSameMatchQueueClient(it->first, Client))

		{

			it = RankedMatchQueue.erase(it); // 删除元素并更新迭代器

			removed++;

		}

		else

		{

			++it; // 只有在没有删除元素时才移动迭代器

		}

	}

	return removed;

}



int CancelBorderMatch(std::shared_ptr<ClientNode> Client)

{

	if (!Client)

	{

		return 0;

	}

	std::lock_guard<std::recursive_mutex> lg(BorderQueueMutex);



	int removed = 0;

	for (auto it = BorderMatchQueue.begin(); it != BorderMatchQueue.end(); /* no increment here */)

	{

		if (IsSameMatchQueueClient(it->first, Client))

		{

			it = BorderMatchQueue.erase(it); // 删除元素并更新迭代器

			removed++;

		}

		else

		{

			++it; // 只有在没有删除元素时才移动迭代器

		}

	}

	return removed;

}

void RequestCancelMatch(std::shared_ptr<ClientNode> Client)

{

	if (!Client)

	{

		return;

	}



	const UINT oldTaskID = Client->TaskID;
	if (oldTaskID == 0xFFFD)
		CrossServerTestCancelBorderPlayer(Client);

	int removed = 0;

	removed += CancelRankedMatch(Client);

	removed += CancelBorderMatch(Client);



	// 只清理等待匹配态。已经进入 BorderRoomID 的比赛房时，不让取消包误清比赛任务。

	if (removed > 0 || Client->BorderRoomID == 0)

	{

		if (oldTaskID == 0xFFFC || oldTaskID == 0xFFFD)

		{

			Client->TaskID = 0;

			Client->IsReady = FALSE;

			Client->ReadyState = QQS_ROOM_READY_STATE_NOT_READY;

		}

	}

}


void RequestCancelMatchExactSession(std::shared_ptr<ClientNode> Client)

{

	if (!Client)

	{

		return;

	}

	const UINT oldTaskID = Client->TaskID;

	int removed = 0;

	{

		std::lock_guard<std::recursive_mutex> lg(RankedQueueMutex);

		for (auto it = RankedMatchQueue.begin(); it != RankedMatchQueue.end(); /* no increment here */)

		{

			if (IsExactMatchQueueClient(it->first, Client))

			{

				it = RankedMatchQueue.erase(it);

				removed++;

			}

			else

			{

				++it;

			}

		}

	}

	{

		std::lock_guard<std::recursive_mutex> lg(BorderQueueMutex);

		for (auto it = BorderMatchQueue.begin(); it != BorderMatchQueue.end(); /* no increment here */)

		{

			if (IsExactMatchQueueClient(it->first, Client))

			{

				it = BorderMatchQueue.erase(it);

				removed++;

			}

			else

			{

				++it;

			}

		}

	}

	if (removed > 0 || Client->BorderRoomID == 0)

	{

		if (oldTaskID == 0xFFFC || oldTaskID == 0xFFFD)

		{

			Client->TaskID = 0;

			Client->IsReady = FALSE;

			Client->ReadyState = QQS_ROOM_READY_STATE_NOT_READY;

		}

	}

}



