namespace
{
struct PwdRedEnvelopeNumberRange
{
	int Minimum = 0;
	int Maximum = 0;
};

struct PwdRedEnvelopeItemConfig
{
	ItemInfo Item;
	PwdRedEnvelopeNumberRange ItemNum;
	std::string DatabaseName;
};

struct PwdRedEnvelopeGrantedItem
{
	ItemInfo Item;
	int GrantedItemNum = 0;
	bool Granted = true;
	std::string DatabaseName;
};

struct PwdRedEnvelopeRewardResult
{
	int Experience = 0;
	int SuperMoney = 0;
	int Charm = 0;
	int TotalHonor = 0;
	bool NotifyReward = true;
	std::vector<PwdRedEnvelopeGrantedItem> Items;
};

static constexpr size_t PwdRedEnvelopeMaxReasonBytes = 240;

static std::mt19937& GetPwdRedEnvelopeRandomEngine()
{
	static thread_local std::mt19937 Engine(std::random_device{}());
	return Engine;
}

static PwdRedEnvelopeNumberRange ParsePwdRedEnvelopeNumberRange(
	const YAML::Node& Node,
	const std::string& FieldName,
	int MinimumAllowed)
{
	if (!Node)
	{
		throw std::runtime_error(FieldName + " 缺失");
	}

	PwdRedEnvelopeNumberRange Result;
	if (Node.IsScalar())
	{
		Result.Minimum = Node.as<int>();
		Result.Maximum = Result.Minimum;
	}
	else if (Node.IsMap() && Node["Min"] && Node["Max"])
	{
		Result.Minimum = Node["Min"].as<int>();
		Result.Maximum = Node["Max"].as<int>();
	}
	else
	{
		throw std::runtime_error(FieldName + " 必须是固定整数或包含 Min/Max 的范围");
	}

	if (Result.Minimum < MinimumAllowed || Result.Maximum < Result.Minimum)
	{
		throw std::runtime_error(FieldName + " 范围无效");
	}
	return Result;
}

static int ResolvePwdRedEnvelopeNumber(const PwdRedEnvelopeNumberRange& Range)
{
	if (Range.Minimum == Range.Maximum)
	{
		return Range.Minimum;
	}
	std::uniform_int_distribution<int> Distribution(Range.Minimum, Range.Maximum);
	return Distribution(GetPwdRedEnvelopeRandomEngine());
}

static int ResolvePwdRedEnvelopeSuperMoney(const PwdRedEnvelopeNumberRange& Range)
{
	constexpr int DrawCount = 3;

	int Result = ResolvePwdRedEnvelopeNumber(Range);
	for (int Index = 1; Index < DrawCount; ++Index)
	{
		const int Candidate = ResolvePwdRedEnvelopeNumber(Range);
		if (Candidate < Result)
		{
			Result = Candidate;
		}
	}

	return Result;
}

static PwdRedEnvelopeItemConfig ParsePwdRedEnvelopeItem(
	const YAML::Node& ItemNode,
	const std::string& FieldName)
{
	if (!ItemNode || !ItemNode.IsMap() || !ItemNode["ItemId"] ||
		!ItemNode["ItemNum"] || !ItemNode["ObtainTime"] || !ItemNode["AvailPeriod"])
	{
		throw std::runtime_error(FieldName + " 缺少 ItemId/ItemNum/ObtainTime/AvailPeriod");
	}

	const int ItemId = ItemNode["ItemId"].as<int>();
	if (ItemId <= 0)
	{
		throw std::runtime_error(FieldName + ".ItemId 无效");
	}

	PwdRedEnvelopeItemConfig Result;
	Result.Item.ItemID = static_cast<UINT>(ItemId);
	Result.ItemNum = ParsePwdRedEnvelopeNumberRange(ItemNode["ItemNum"], FieldName + ".ItemNum", 1);
	Result.Item.ObtainTime = ItemNode["ObtainTime"].as<int>();
	Result.Item.AvailPeriod = ItemNode["AvailPeriod"].as<int>();
	Result.DatabaseName = GetItemName(Result.Item.ItemID);
	if (Result.DatabaseName.empty() || Result.DatabaseName == "Empty")
	{
		throw std::runtime_error(FieldName + ".ItemId 在 ItemAllNew 中不存在");
	}
	return Result;
}

static PwdRedEnvelopeGrantedItem ResolvePwdRedEnvelopeItem(const PwdRedEnvelopeItemConfig& Config)
{
	PwdRedEnvelopeGrantedItem Result;
	Result.Item = Config.Item;
	Result.GrantedItemNum = ResolvePwdRedEnvelopeNumber(Config.ItemNum);
	Result.Item.ItemNum = Result.GrantedItemNum;
	Result.DatabaseName = Config.DatabaseName;
	return Result;
}

static void ValidatePwdRedEnvelopeRewardNotice(const PwdRedEnvelopeRewardResult& Reward)
{
	if (!Reward.NotifyReward)
	{
		return;
	}

	const std::string ContinuePrefix = "继续获得：";
	for (const PwdRedEnvelopeGrantedItem& Item : Reward.Items)
	{
		const std::string RewardText = Item.DatabaseName + "×" + std::to_string(Item.GrantedItemNum);
		if (ContinuePrefix.size() + RewardText.size() > PwdRedEnvelopeMaxReasonBytes)
		{
			throw std::runtime_error(
				"ItemId " + std::to_string(Item.Item.ItemID) + " 的数据库名称过长，无法发送奖励提醒");
		}
	}
}

static std::vector<PwdRedEnvelopeGrantedItem> ResolvePwdRedEnvelopeItems(const YAML::Node& Config)
{
	std::vector<PwdRedEnvelopeGrantedItem> Result;
	YAML::Node FixedItems = Config["Items"];
	if (FixedItems)
	{
		if (!FixedItems.IsSequence())
		{
			throw std::runtime_error("Items 必须是数组");
		}
		Result.reserve(FixedItems.size());
		for (size_t Index = 0; Index < FixedItems.size(); ++Index)
		{
			PwdRedEnvelopeItemConfig ItemConfig = ParsePwdRedEnvelopeItem(
				FixedItems[Index], "Items[" + std::to_string(Index) + "]");
			Result.push_back(ResolvePwdRedEnvelopeItem(ItemConfig));
		}
	}

	YAML::Node RandomItems = Config["RandomItems"];
	if (!RandomItems)
	{
		return Result;
	}
	if (!RandomItems.IsMap() || !RandomItems["Pick"] || !RandomItems["Pool"] ||
		!RandomItems["Pool"].IsSequence())
	{
		throw std::runtime_error("RandomItems 必须包含 Pick 和 Pool 数组");
	}

	const int Pick = RandomItems["Pick"].as<int>();
	YAML::Node PoolNode = RandomItems["Pool"];
	if (Pick <= 0 || static_cast<size_t>(Pick) > PoolNode.size())
	{
		throw std::runtime_error("RandomItems.Pick 必须大于 0 且不能超过 Pool 数量");
	}

	std::vector<PwdRedEnvelopeItemConfig> Pool;
	Pool.reserve(PoolNode.size());
	for (size_t Index = 0; Index < PoolNode.size(); ++Index)
	{
		Pool.push_back(ParsePwdRedEnvelopeItem(
			PoolNode[Index], "RandomItems.Pool[" + std::to_string(Index) + "]"));
	}

	std::vector<size_t> Indexes(Pool.size());
	for (size_t Index = 0; Index < Indexes.size(); ++Index)
	{
		Indexes[Index] = Index;
	}
	std::shuffle(Indexes.begin(), Indexes.end(), GetPwdRedEnvelopeRandomEngine());
	Result.reserve(Result.size() + static_cast<size_t>(Pick));
	for (int Index = 0; Index < Pick; ++Index)
	{
		Result.push_back(ResolvePwdRedEnvelopeItem(Pool[Indexes[Index]]));
	}
	return Result;
}

static void NotifyPwdRedEnvelopeReward(
	std::shared_ptr<ClientNode> Client,
	const PwdRedEnvelopeRewardResult& Reward)
{
	if (!Reward.NotifyReward)
	{
		return;
	}

	std::vector<std::string> RewardTexts;
	if (Reward.Experience > 0) RewardTexts.push_back("经验×" + std::to_string(Reward.Experience));
	if (Reward.SuperMoney > 0) RewardTexts.push_back("点券×" + std::to_string(Reward.SuperMoney));
	if (Reward.Charm > 0) RewardTexts.push_back("魅力×" + std::to_string(Reward.Charm));
	if (Reward.TotalHonor > 0) RewardTexts.push_back("荣誉×" + std::to_string(Reward.TotalHonor));
	for (const PwdRedEnvelopeGrantedItem& Item : Reward.Items)
	{
		if (!Item.Granted)
		{
			continue;
		}
		RewardTexts.push_back(Item.DatabaseName + "×" + std::to_string(Item.GrantedItemNum));
	}

	const std::string FirstPrefix = "兑换成功，获得：";
	const std::string ContinuePrefix = "继续获得：";
	std::string Message = FirstPrefix;
	bool HasRewardInMessage = false;
	for (const std::string& RewardText : RewardTexts)
	{
		const std::string Separator = HasRewardInMessage ? "，" : "";
		if (Message.size() + Separator.size() + RewardText.size() > PwdRedEnvelopeMaxReasonBytes)
		{
			ResponseStartGame(Client, Message.c_str());
			Message = ContinuePrefix;
			HasRewardInMessage = false;
		}
		if (HasRewardInMessage)
		{
			Message += "，";
		}
		Message += RewardText;
		HasRewardInMessage = true;
	}

	if (!HasRewardInMessage)
	{
		Message = "兑换成功";
	}
	ResponseStartGame(Client, Message.c_str());
}
}

BOOL SendPwdRedEnvelope(
	std::shared_ptr<ClientNode> Client,
	int KeyIndex,
	PwdRedEnvelopeRewardResult& RewardResult)

{

	char FilePath[MAX_PATH];

	//printf("KeyIndex:%d \n", KeyIndex);

	sprintf_s(FilePath, ".\\CdkAward\\%d.yml", KeyIndex);

	try

	{

		YAML::Node config = YAML::LoadFile(FilePath);

		PwdRedEnvelopeRewardResult ResolvedReward;

		ResolvedReward.Experience = config["Experience"].as<int>();

		ResolvedReward.SuperMoney = ResolvePwdRedEnvelopeSuperMoney(
			ParsePwdRedEnvelopeNumberRange(config["SuperMoney"], "SuperMoney", 0));

		ResolvedReward.Charm = config["Charm"].as<int>();

		ResolvedReward.TotalHonor = config["TotalHonor"].as<int>();

		if (ResolvedReward.Experience < 0 || ResolvedReward.Charm < 0 || ResolvedReward.TotalHonor < 0)
		{
			throw std::runtime_error("Experience/Charm/TotalHonor 不能小于 0");
		}

		if (config["NotifyReward"])
		{
			ResolvedReward.NotifyReward = config["NotifyReward"].as<bool>();
		}

		ResolvedReward.Items = ResolvePwdRedEnvelopeItems(config);

		ValidatePwdRedEnvelopeRewardNotice(ResolvedReward);

		DBConnection myDBConnection(player); auto conn = myDBConnection.getConnection(); if (!conn) return FALSE;

		SelectClientExp(Client);

		if (ResolvedReward.SuperMoney > 0 &&
			Client->SuperMoney > (std::numeric_limits<int>::max)() - ResolvedReward.SuperMoney)
		{
			throw std::runtime_error("SuperMoney 超出可用范围");
		}

		if (ResolvedReward.Charm > 0 &&
			Client->Charm > (std::numeric_limits<int>::max)() - ResolvedReward.Charm)
		{
			throw std::runtime_error("Charm 超出可用范围");
		}

		if (ResolvedReward.TotalHonor > 0 &&
			Client->TotalHonor > (std::numeric_limits<int>::max)() - ResolvedReward.TotalHonor)
		{
			throw std::runtime_error("TotalHonor 超出可用范围");
		}

		//Client->Experience += ResolvedReward.Experience;

		Client->Experience = (Client->Experience > UINT_MAX - ResolvedReward.Experience) ?
			UINT_MAX : Client->Experience + ResolvedReward.Experience;

		Client->SuperMoney += ResolvedReward.SuperMoney;

		Client->TotalHonor += ResolvedReward.TotalHonor;

		AddCharmAndSync(Client, ResolvedReward.Charm, false);



		UpdateClientBase(Client);

		NotifyClientUpdateMoneyExp(Client);

		const size_t AllItem = ResolvedReward.Items.size();

		std::vector<char> SkipNotify(AllItem, 0);

		conn->setAutoCommit(false);

		try

		{

			for (size_t Index = 0; Index < AllItem; ++Index)

			{

				PwdRedEnvelopeGrantedItem& GrantedItem = ResolvedReward.Items[Index];

				UINT ItemCfgType = GetItemType(GrantedItem.Item.ItemID);

				if ((ItemCfgType == EAIT_CAR || ItemCfgType == EAIT_SKIN || ItemCfgType == EAIT_CLOTHES) &&
					PlayerDB_HasItem(Client->Uin, GrantedItem.Item.ItemID))

				{

					int OldAvailPeriod = PlayerDB_GetItemAvailPeriod(Client->Uin, GrantedItem.Item.ItemID);

					if (OldAvailPeriod <= 0)

					{

						SkipNotify[Index] = 1;

						GrantedItem.Granted = false;

					}

				}

				GrantedItem.Item.ItemNum = PlayerDB_AddItem1(
					Client,
					Client->Uin,
					GrantedItem.Item.ItemID,
					GrantedItem.GrantedItemNum,
					GrantedItem.Item.AvailPeriod,
					0,
					conn);

			}

			conn->commit();

			conn->setAutoCommit(true);

		}

		catch (...)

		{

			try

			{

				conn->rollback();

				conn->setAutoCommit(true);

			}

			catch (...)

			{

			}

			throw;

		}

		std::vector<ItemInfo> NotifyItems;

		NotifyItems.reserve(AllItem);

		for (size_t Index = 0; Index < AllItem; ++Index)

		{

			if (SkipNotify[Index])

			{

				continue;

			}

			PwdRedEnvelopeGrantedItem& GrantedItem = ResolvedReward.Items[Index];

			UINT ItemCfgType = GetItemType(GrantedItem.Item.ItemID);

			if (ItemCfgType == EAIT_CAR || ItemCfgType == EAIT_SKIN || ItemCfgType == EAIT_CLOTHES)

			{

				GrantedItem.Item.AvailPeriod = PlayerDB_GetItemAvailPeriod(Client->Uin, GrantedItem.Item.ItemID);

			}

			NotifyItems.push_back(GrantedItem.Item);

		}

		if (!NotifyItems.empty())

		{

			NotifyClientAddItem(Client, static_cast<UINT>(NotifyItems.size()), NotifyItems);

		}

		RewardResult = std::move(ResolvedReward);

		return TRUE;

	}

	catch (const std::exception& e)

	{

		std::cerr << "Cdk奖励配置或发放异常: " << e.what() << std::endl;

	}

	catch (...)

	{

		printf("Cdk奖励配置或发放异常 请检查!");

	}

	return FALSE;

}



// 函数用于检查字符串是否全为数字

bool isNumeric(const char* str) {

	while (*str != '\0') {

		if (!std::isdigit(*str)) {

			return false;

		}

		str++;

	}

	return true;

}



bool isNumeric1(const std::string& str) {

	// 定义匹配的正则表达式

	std::regex pattern("^[0-9]{5,6}$");



	// 进行匹配

	return std::regex_match(str, pattern);

}



int SendAnyItem(std::shared_ptr<ClientNode> Client, char cdk[]) {

	// Helper function to parse item info from token

	auto parseItemInfo = [](const char* substr, UINT& Itemid, UINT& ItemNum) -> bool {

		if ((std::strlen(substr) == 5 || std::strlen(substr) == 6) && isNumeric(substr)) {

			Itemid = std::strtoul(substr, nullptr, 10);

			return true;

		}

		return false;

		};

	char* context = nullptr; // 上下文指针

	char* token = strtok_s(cdk, "a",&context);

	bool all = false;

	UINT uin = 0;

	UINT Itemid = 0;

	UINT ItemNum = 0;



	if (!token) {

		ResponseStartGame(Client, "输入格式错误!");

		return -1;

	}

	char* substr = token + 4;

	if (isNumeric(substr)) {

		uin = std::strtoul(substr, nullptr, 10);

		token = strtok_s(nullptr, "a", &context);



		if (token && parseItemInfo(token, Itemid, ItemNum)) {

			token = strtok_s(nullptr, "a", &context);

			if (token && isNumeric(token)) {

				ItemNum = std::strtoul(token, nullptr, 10);

			}

			else {

				ResponseStartGame(Client, "输入格式错误!");

				return -1;

			}

		}

		else {

			ResponseStartGame(Client, "输入格式错误!");

			return -1;

		}

	}

	else if (std::strcmp(substr, "one") == 0) {

		all = true;

		token = strtok_s(nullptr, "a", &context);



		if (token && parseItemInfo(token, Itemid, ItemNum)) {

			token = strtok_s(nullptr, "a", &context);

			if (token && isNumeric(token)) {

				ItemNum = std::strtoul(token, nullptr, 10);

			}

			else {

				ResponseStartGame(Client, "输入格式错误!");

				return -1;

			}

		}

		else {

			ResponseStartGame(Client, "输入格式错误!");

			return -1;

		}

	}

	else {

		ResponseStartGame(Client, "输入格式错误!");

		return -1;

	}



	ItemInfo TempItem = { 0 };

	TempItem.ItemID = Itemid;

	TempItem.ItemType = 0;

	TempItem.ItemNum = (ItemNum == 0) ? 1 : ItemNum;

	TempItem.AvailPeriod = (ItemNum == 0) ? -1 : 0;



	if (all) {

		try {

			DBConnection myDBConnection(player);

			auto conn = myDBConnection.getConnection();

			if (!conn) return -1;



			conn->setAutoCommit(false);



			std::unique_ptr<sql::PreparedStatement> prep_stmt(conn->prepareStatement("SELECT Uin FROM Baseinfo;"));

			std::unique_ptr<sql::ResultSet> res(prep_stmt->executeQuery());

			prep_stmt.reset();

			while (res->next()) {

				UINT one = res->getUInt("uin");

				PlayerDB_AddItem5(one, TempItem.ItemID, TempItem.ItemNum, TempItem.AvailPeriod, 0, conn);

			}

			conn->commit();

			conn->setAutoCommit(true);

			res.reset();

		}

		catch (const std::exception& e) {

			printf("SendAnyItem Error: %s\n", e.what());

			return -1;

		}

	}

	else {

		auto client = GetClient(uin);

		if (client) {

			TempItem.ItemNum = PlayerDB_AddItem2(client, client->Uin, TempItem.ItemID, TempItem.ItemNum, TempItem.AvailPeriod, 0);

			if (Uinew) {

				NotifyClientAddItemNew(client, 1, { TempItem });

			}

			else {

				NotifyClientAddItem(client, 1, { TempItem });

			}



		}

		else {

			TempItem.ItemNum = PlayerDB_AddItem4(uin, TempItem.ItemID, TempItem.ItemNum, TempItem.AvailPeriod, 0);

		}

	}



	return 1;

}



void RequestSendPwdRedEnvelope(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)

{

	BYTE* p = Body;

	char cdk[64] = { 0 };

	char exchangesuccess = 0;

	int KeyIndex = 0;

	int KeyType = 0;

	int KeyPrice = 0;

	UINT Uin = Read32(p);

	UINT Time = Read32(p);

	USHORT ContentLen = Read16(p);



	if (ContentLen <= sizeof(cdk)) {

		memcpy(cdk, p, ContentLen);

	}

	else {

		return;

	}

	// 获取开始时间点

	auto start = std::chrono::high_resolution_clock::now();



	try

	{

		//give10001a127748a100

		//giveonea127748a100

		if (strncmp(cdk, "give", 4) == 0 && Client->admin == 1) {

			if (SendAnyItem(Client, cdk) > 0) {

				ResponseSendPwdRedEnvelope(Client, 0);

			}

			return;

		}

	}

	catch (const std::exception& e)

	{

		printf(e.what());

		printf("SendAnyItem Error\n");

	}



	if (isLog == 1) {

		auto ServerLogger = spdlog::get("SpeedServer_logger");

		ServerLogger->info("[红包口令][Uin:{:d}][Content:{:s}]", Uin, cdk);

		ServerLogger->flush();

	}



	DBConnection myDBConnection(usr); auto conn = myDBConnection.getConnection(); if (!conn) return;

	try

	{

		std::unique_ptr<sql::PreparedStatement> prep_stmt(conn->prepareStatement("select KeyValue,KeyIndex,KeyType,KeyPrice from CdkInfo where KeyValue =?;"));

		prep_stmt->clearParameters();

		prep_stmt->setString(1, cdk);

		// 执行查询

		std::unique_ptr<sql::ResultSet> res(prep_stmt->executeQuery());

		prep_stmt.reset();

		// 处理结果

		if (res->rowsCount() > 0) {

			res->next();

			exchangesuccess = 1;

			KeyIndex = res->getUInt("KeyIndex");

			KeyType = res->getUInt("KeyType");

			KeyPrice = res->getUInt("KeyPrice");

		}

		else {

			exchangesuccess = 0;

		}

		res.reset();





		char hasAward = 0;

		if (exchangesuccess)

		{

			std::unique_ptr<sql::PreparedStatement> prep_stmt(conn->prepareStatement("SELECT 1 FROM CdkRecord Where Uin=? and KeyIndex=?;"));

			prep_stmt->clearParameters();

			prep_stmt->setUInt(1, Client->Uin);

			prep_stmt->setUInt(2, KeyIndex);

			// 执行查询

			std::unique_ptr<sql::ResultSet> res(prep_stmt->executeQuery());

			prep_stmt.reset();

			// 处理结果

			while (res->next()) {

				hasAward = 1;

				break;

			}

			res.reset();



			if (hasAward)

			{

				ResponseStartGame(Client, "你已使用过该Cdk!");

				return;

			}



			PwdRedEnvelopeRewardResult RewardResult;

			BOOL SendOk = SendPwdRedEnvelope(Client, KeyIndex, RewardResult);

			if (SendOk)

			{

				std::unique_ptr<sql::PreparedStatement> prep_stmt(conn->prepareStatement("INSERT INTO CdkRecord VALUES(?, ?,?,?);"));

				prep_stmt->clearParameters();

				prep_stmt->setUInt(1, Client->Uin);

				prep_stmt->setUInt(2, KeyIndex);

				prep_stmt->setString(3, cdk);

				prep_stmt->setUInt(4, KeyPrice);

				prep_stmt->executeUpdate();

				prep_stmt.reset();

				if (KeyType == 1)

				{

					std::unique_ptr<sql::PreparedStatement> prep_stmt(conn->prepareStatement("DELETE FROM CdkInfo  WHERE KeyIndex=?;"));

					prep_stmt->clearParameters();

					prep_stmt->setUInt(1, KeyIndex);

					prep_stmt->executeUpdate();

					prep_stmt.reset();

				}



				// 获取结束时间点

				auto end = std::chrono::high_resolution_clock::now();



				// 计算时间差

				auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);



				if (QQS_ShouldPrintDebugUin10001(Client->Uin))
				{
					std::cout << "Uin: " << Client->Uin << " CDK:" << cdk << " 兑换成功，消耗时间：" << duration.count() << " 毫秒" << std::endl;
				}



				//printf("Uin:%d CDK:%s 兑换成功，消耗时间：%d 毫秒\n", Client->Uin, cdk, duration.count());

				ResponseSendPwdRedEnvelope(Client, 0);

				NotifyPwdRedEnvelopeReward(Client, RewardResult);



			}

			else

			{

				if (QQS_ShouldPrintDebugUin10001(Client->Uin))
				{
					printf("Uin:%d CDK:%s KeyIndex:%d 兑换异常\n", Client->Uin, cdk, KeyIndex);
				}

				ResponseStartGame(Client, "兑换异常 请联系管理员!");

			}

		}

		else

		{

			ResponseSendPwdRedEnvelope(Client, 1);

			ResponseStartGame(Client, "CDK已使用或不存在!");

		}





	}

	catch (const std::exception& e)

	{

		std::cerr << e.what() << "RequestSendPwdRedEnvelope Error" << std::endl;

		//throw;关闭

	}

	catch (...)

	{

		printf("RequestSendPwdRedEnvelope error\n");

		//throw;关闭

	}

}







void RequestCheckName(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)

{

	BYTE* p = Body;

	UINT Uin = Read32(p);

	UINT Time = Read32(p);

	char NickName[17];

	std::string newname = "";

	BOOL isNameExist = 0;

	memcpy(NickName, p, 17);

	newname = G2U(NickName);

	UINT ItemNum = 0;



	ItemNum = PlayerDB_GetItemNum(Client->Uin, 10595);

	if (ItemNum <= 0)

	{

		ResponseStartGame(Client, "请购买更名卡!");

		return;

	}



	std::vector<std::string> conditionValues;

	conditionValues.push_back(newname);

	std::vector<int> resultRow = executeQueryRow("SELECT 1 FROM BaseInfo Where NickName=?;", "RequestCheckName", conditionValues);

	if (resultRow.size() >= 1) {

		isNameExist = 1;

	}



	if (isNameExist != 0)

	{

		ResponseStartGame(Client, "用户名已存在!");

	}

	else {

		PlayerDB_UpNickName(Client->Uin, newname);

		ResponseStartGame(Client, "用户名修改成功!");

		NotifyUseItemResult2(Client, 10595, 1);

	}

}





void ResponseBatchDeleteItem(std::shared_ptr<ClientNode> Client, UINT* ItemID, int ItemNum)

{

	if (deleteflag == 1) {

		ResponseStartGame(Client, "目前不允许删除宝贝哦！");

		return;

	}



	std::vector<BYTE> buf(819200); BYTE* p = buf.data(); size_t len;



	for (size_t i = 0; i < ItemNum; i++)

	{

		if (isLog) {

			auto ServerLogger = spdlog::get("SpeedServer_logger");

			ServerLogger->info("[删除道具：][Uin:{:d}][道具ID:{:d}]", Client->Uin, ItemID[i]);

			ServerLogger->flush();

		}

		PlayerDB_DeleteItem(Client->Uin, ItemID[i]);

	}



	Write16(p, 0); //ResultID

	Write32(p, Client->Uin); //Uin

	Write32(p, ItemNum); //SuccessDeleteItemNum

	for (int i = 0; i < ItemNum; i++)

	{

		Write32(p, ItemID[i]); //SuccessDeleteItemID[]

	}

	Write32(p, 0); //FailDeleteItemNum



	len = p - buf.data();

	SendToClient(Client, 21035, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);

}

void RequestBatchDeleteItem(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)

{

	BYTE* p = Body;

	UINT ItemID[200] = { 0 };

	UINT Uin = Read32(p);

	UINT Time = Read32(p);

	int ItemNum = Read32(p);

	ItemNum = ItemNum > 200 ? 200 : ItemNum;

	for (int i = 0; i < ItemNum; i++)

	{

		ItemID[i] = Read32(p);

		//printf("ItemID: %d\n", ItemID[i]);

	}

	ResponseBatchDeleteItem(Client, ItemID, ItemNum);

}



