static int STC_YInt(const YAML::Node& node, const char* key, int def)
{
	if (!node || !node[key]) return def;
	try { return node[key].as<int>(); } catch (...) { return def; }
}

static int STC_YIntAny(const YAML::Node& node, std::initializer_list<const char*> keys, int def)
{
	for (const char* k : keys)
	{
		int old = def;
		int v = STC_YInt(node, k, old);
		if (v != old || (node && node[k])) return v;
	}
	return def;
}

void LoadSupremeTreasureExchangeShopCommonBox()
{
	static bool loaded = false;
	if (loaded) return;
	loaded = true;
	std::vector<CarTreasureInfo> rows;
	try
	{
		YAML::Node root = YAML::LoadFile(".\\24251\\SupremeTreasure.yml");
		YAML::Node act = root["activity"];
		if (act)
		{
			g_SupremeTreasureExchangeBeginTime = static_cast<DWORD>(STC_YIntAny(act, { "begin", "BeginTime" }, static_cast<int>(g_SupremeTreasureExchangeBeginTime)));
			g_SupremeTreasureExchangeEndTime = static_cast<DWORD>(STC_YIntAny(act, { "end", "EndTime" }, static_cast<int>(g_SupremeTreasureExchangeEndTime)));
		}
		YAML::Node itemCfg = root["PlayerItems"];
		if (itemCfg)
		{
			g_SupremeTreasureScoreItemID = static_cast<UINT>(STC_YIntAny(itemCfg, { "scoreItem", "ItemID" }, static_cast<int>(g_SupremeTreasureScoreItemID)));
			g_SupremeTreasureBestExchangeItemID = static_cast<UINT>(STC_YIntAny(itemCfg, { "crystalItem", "BestExchangeItemID" }, static_cast<int>(g_SupremeTreasureBestExchangeItemID)));
			g_SupremeTreasureBestItemTransformScore = STC_YIntAny(itemCfg, { "transformScore", "BestItemTransformScore" }, g_SupremeTreasureBestItemTransformScore);
		}
		YAML::Node shop = root["shop"] ? root["shop"] : root["ExchangeShop"];
		if (shop && shop.IsSequence())
		{
			for (size_t i = 0; i < shop.size(); ++i)
			{
				YAML::Node n = shop[i];
				CarTreasureInfo row;
				row.AwardIdx = STC_YIntAny(n, { "awardIdx", "AwardIdx" }, static_cast<int>(i + 1));
				row.PosKey = STC_YIntAny(n, { "pos", "PosKey" }, static_cast<int>(i + 1));
				row.PieceItemID = STC_YIntAny(n, { "cost", "CostItemID" }, 94880);
				row.ExchangePieceNum = STC_YIntAny(n, { "price", "CostNum" }, 1);
				row.ItemId = STC_YIntAny(n, { "item", "ItemID" }, 0);
				row.ItemNum = STC_YIntAny(n, { "num", "ItemNum" }, 1);
				row.AvailPeriod = STC_YIntAny(n, { "period", "AvailPeriod" }, 0);
				row.ItemType = STC_YIntAny(n, { "type", "ItemType" }, 2);
				row.CanExchange = STC_YIntAny(n, { "limit", "Limit", "CanExchange", "MaxExchangeNum" }, 1);
				row.ResultID = STC_YIntAny(n, { "resultID", "ResultID" }, 11498);
				row.LabelStatus = STC_YIntAny(n, { "label", "LabelStatus" }, 0);
				row.OtherAttribute = STC_YIntAny(n, { "tailFlag", "TailFlag", "MoreFlag" }, 0);
				row.GroupIndex = STC_YIntAny(n, { "tabId", "TabID", "GroupIndex" }, (i < 4 ? 1 : 2));
				row.SelectCarType = STC_YIntAny(n, { "sort", "Sort", "DisplayOrder", "TailSort" }, 0);
				if (row.ItemId) rows.push_back(row);
			}
		}
	}
	catch (const std::exception& e)
	{
		QQS_DebugPrintf10001("[SupremeTreasure][CommonBox] load .\\24251\\SupremeTreasure.yml failed, use defaults: %s\n", e.what());
	}
	if (rows.empty())
	{
		QQS_DebugPrintf10001("[SupremeTreasure][CommonBox] no ExchangeShop rows in .\\24251\\SupremeTreasure.yml, use fallback Type=%u\n", kSupremeTreasureExchangeType);
		CarTreasureInfo row;
		row.AwardIdx = 1; row.PosKey = 1; row.PieceItemID = 144343; row.ExchangePieceNum = 30; row.ItemId = 98263; row.ItemNum = 1; row.AvailPeriod = -1; row.ItemType = 1; row.CanExchange = 1; row.ResultID = 11498; row.GroupIndex = 1; row.SelectCarType = 100; rows.push_back(row);
		row.AwardIdx = 2; row.PosKey = 2; row.PieceItemID = 144343; row.ExchangePieceNum = 30; row.ItemId = 109563; row.ItemNum = 1; row.AvailPeriod = -1; row.ItemType = 1; row.CanExchange = 1; row.ResultID = 11498; row.GroupIndex = 1; row.SelectCarType = 96; rows.push_back(row);
		row.AwardIdx = 3; row.PosKey = 3; row.PieceItemID = 144343; row.ExchangePieceNum = 30; row.ItemId = 115166; row.ItemNum = 1; row.AvailPeriod = -1; row.ItemType = 1; row.CanExchange = 1; row.ResultID = 11498; row.GroupIndex = 1; row.SelectCarType = 95; rows.push_back(row);
		row.AwardIdx = 4; row.PosKey = 4; row.PieceItemID = 144343; row.ExchangePieceNum = 30; row.ItemId = 119059; row.ItemNum = 1; row.AvailPeriod = -1; row.ItemType = 1; row.CanExchange = 1; row.ResultID = 11498; row.GroupIndex = 1; row.SelectCarType = 94; rows.push_back(row);
		row.AwardIdx = 5; row.PosKey = 5; row.PieceItemID = 94880; row.ExchangePieceNum = 100; row.ItemId = 148391; row.ItemNum = 500; row.AvailPeriod = 0; row.ItemType = 1; row.CanExchange = 9999; row.ResultID = 11498; row.GroupIndex = 2; row.SelectCarType = 85; rows.push_back(row);
		row.AwardIdx = 6; row.PosKey = 6; row.PieceItemID = 94880; row.ExchangePieceNum = 20; row.ItemId = 148391; row.ItemNum = 100; row.AvailPeriod = 0; row.ItemType = 1; row.CanExchange = 9999; row.ResultID = 11498; row.OtherAttribute = 2; row.GroupIndex = 2; row.SelectCarType = 84; rows.push_back(row);
	}
	CommonBoxAwards[kSupremeTreasureExchangeType] = rows;
	QQS_DebugPrintf10001("[SupremeTreasure][CommonBox] loaded config path=.\\24251\\SupremeTreasure.yml exchange rows=%zu Type=%u\n", rows.size(), kSupremeTreasureExchangeType);
}


