void ResponseDoShopExchange(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)

{

	std::vector<BYTE> buf(819200); BYTE* p = buf.data();

	//BYTE* p = buf;

	size_t len;

	

	int AwardIndex = 0;

	/*char* pMsg = EByteToHexUA2((const unsigned char*)Body, BodyLen);

	printf("ResponseDoShopExchange	Hex:%s\n", pMsg);*/



	UINT Uin = Read32(Body);

	UINT Time = Read32(Body);

	// ExchangeInfo

	len = Read16(Body);

	UINT ItemID = Read32(Body);

	UINT ItemNum = Read32(Body);

	UINT AvailPeriod = Read32(Body);

	UINT CostExchangeItemNum = Read32(Body);

	BYTE Flag = Read8(Body);

	BYTE ExchangeShopType = Read8(Body);



	if (!isDBtHasItem(Client, MagicExchangeShopItemId, CostExchangeItemNum))

	{

		ResponseStartGame(Client, "道具不足!");

		return;

	}



	NotifyUseItemResult2(Client, MagicExchangeShopItemId, CostExchangeItemNum);





	Write16(p, 0); // ResultID

	{			   // AwardItemInfo

		BYTE* pAwardItemInfo = p;

		Write16(pAwardItemInfo, 0); // len



		Write32(pAwardItemInfo, 0); // Exp

		Write32(pAwardItemInfo, 0); // Money

		Write32(pAwardItemInfo, 0); // SuperMoney

		Write16(pAwardItemInfo, 0); // ItemNum

		for (size_t i = 0; i < 0; i++)

		{ // ItemInfo

			BYTE* pItemInfo = pAwardItemInfo;

			Write16(pItemInfo, 0); // len



			Write32(pItemInfo, 0); // ItemID

			Write32(pItemInfo, 0); // ItemNum

			Write32(pItemInfo, 0); // AvailPeriod

			Write8(pItemInfo, 0);  // Status

			Write32(pItemInfo, 0); // ObtainTime

			Write32(pItemInfo, 0); // OtherAttribute

			Write16(pItemInfo, 0); // ItemType



			len = pItemInfo - pAwardItemInfo;

			Set16(pAwardItemInfo, (WORD)len);

			pAwardItemInfo += len;

		}

		Write32(pAwardItemInfo, 0); // Coupons

		Write32(pAwardItemInfo, 0); // GuildPoint

		Write32(pAwardItemInfo, 0); // LuckMoney

		Write8(pAwardItemInfo, 0);	// ExtendInfoNum

		for (size_t i = 0; i < 0; i++)

		{ // ExtendInfoAward

			BYTE* pExtendInfoAward = pAwardItemInfo;

			Write16(pExtendInfoAward, 0); // len



			Write16(pExtendInfoAward, 0); // Key

			Write32(pExtendInfoAward, 0); // AddValue

			Write32(pExtendInfoAward, 0); // TotalValue

			Write8(pExtendInfoAward, 0);  // ShowPriority

			Write16(pExtendInfoAward, 0); // BuyNeedScore

			Write8(pExtendInfoAward, 0);  // OneMatchMaxNum



			len = pExtendInfoAward - pAwardItemInfo;

			Set16(pAwardItemInfo, (WORD)len);

			pAwardItemInfo += len;

		}

		Write32(pAwardItemInfo, 0); // SpeedCoin



		len = pAwardItemInfo - p;

		Set16(p, (WORD)len);

		p += len;

	}

	{ // ExchangeInfo

		BYTE* pExchangeInfo = p;

		Write16(pExchangeInfo, 0); // len



		Write32(pExchangeInfo, ItemID);				 // ItemID

		Write32(pExchangeInfo, ItemNum);			 // ItemNum

		Write32(pExchangeInfo, AvailPeriod);		 // AvailPeriod

		Write32(pExchangeInfo, CostExchangeItemNum); // CostExchangeItemNum

		Write8(pExchangeInfo, Flag);				 // Flag



		len = pExchangeInfo - p;

		Set16(p, (WORD)len);

		p += len;

	}

	Write8(p, ExchangeShopType); // ExchangeShopType

	//Write8(p, 0); // ExchangeShopType





	ItemInfo Item = { 0 };

	Item.ItemNum = PlayerDB_AddItem2(Client, Client->Uin, ItemID, ItemNum, AvailPeriod, 0);

	Item.ItemID = ItemID;

	Item.AvailPeriod = AvailPeriod;

	Item.ObtainTime = 0xFFFF;

	NotifyClientAddItem(Client, 1, { Item });



	if (AvailPeriod != 0) {

		PlayerDB_InsertMagicShopInfo(Uin, ItemID);

	}



	len = p - buf.data();

	SendToClient(Client, 24787, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);

}



void RequestGetMagicHouseInfo(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)

{



	/*char* pMsg = EByteToHexUA2((const unsigned char*)Body, BodyLen);

	printf("ResponseGetMagicHouseInfo	Hex:%s\n", pMsg);*/



	std::vector<BYTE> buf(819200); BYTE* p = buf.data();

	//BYTE* p = buf;

	size_t len;

	UINT Uin = Read32(Body);

	UINT Time = Read32(Body);

	UINT MagicHouseID = Read32(Body);

	



	std::unordered_map<int, int> Items;



	PlayerDB_GetMagicFormationNum(Uin, Items);



	Write32(p, Uin);		// Uin

	Write16(p, 0);			// ResultID

	Write8(p, 1);			// OpenStat

	Write8(p, 0);			// ReceiveAllAward

	Write32(p, 1678084039); // OpenStartTime  开放开始时间

	Write32(p, 3382237639); // OpenEndTime    打开结束时间

	Write16(p, MagicFormationBoxs.size());			// AwardNums

	for (size_t i = 0; i < MagicFormationBoxs.size(); i++)

	{ // AwardItemInfo

		BYTE* pAwardItemInfo = p;

		Write16(pAwardItemInfo, 0); // len



		Write32(pAwardItemInfo, MagicFormationBoxs[i]->ItemID); // ItemID

		Write32(pAwardItemInfo, MagicFormationBoxs[i]->ItemNum);		// ItemNums

		Write32(pAwardItemInfo, MagicFormationBoxs[i]->AvailPeriod);	// AvailPeriod

		auto iter = Items.find(MagicFormationBoxs[i]->ItemID);

		if (iter != Items.end()) {

			Write16(pAwardItemInfo, 1);		// Received    被承认的

		}

		else

		{

			Write16(pAwardItemInfo, 0);		// Received    被承认的

		}

		Write16(pAwardItemInfo, i);		// AwardIndex

		Write16(pAwardItemInfo, 0);		// ItemType



		len = pAwardItemInfo - p;

		Set16(p, (WORD)len);

		p += len;

	}

	Write32(p, MagicShop[1]);			  // CostCallOnItemNums  限时折扣张数 开启需要的道具数量

	Write32(p, MagicHouseID); // MagicHouseID

	Write32(p, 0);			  // TimeRemain 折扣多少秒后消失

	Write32(p, 0);			  // SaveItemNum //福利 总共节省召唤卡 张数

	Write8(p, 1);			  // TipsFlag 未知 不是1 会出现 福利提示

	Write32(p, MagicShop[1]);			  // CostCallOnItemNumsBeforDiscount 本次参与需要的召唤卡数量

	Write32(p, MagicShop[0]);		  // CallOnItemID



	len = p - buf.data();

	SendToClient(Client, 24470, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);

}



static void NotifyPetStrengthenCardChange529(
	std::shared_ptr<ClientNode> Client,
	UINT ItemID,
	INT CurrentItemNum)
{
	if (!Client || ItemID == 0 || CurrentItemNum < 0)
		return;

	std::vector<BYTE> buf(128);
	BYTE* p = buf.data();
	BYTE* const body = p;
	Write16(p, 0); // CNotifyClientAddItemPara selfLen
	Write32(p, Client->Uin);
	Write32(p, Client->Uin); // SrcUin
	Write16(p, 1); // ItemNum
	{
		BYTE* const item = p;
		Write16(p, 0);
		Write32(p, ItemID);
		Write32(p, static_cast<UINT>(CurrentItemNum));
		Write32(p, 0); // AvailPeriod
		Write8(p, 0);  // Status
		Write32(p, static_cast<DWORD>(time(nullptr))); // ObtainTime
		Write32(p, 0); // OtherAttribute
		Write16(p, 0); // ItemType
		Set16(item, static_cast<WORD>(p - item));
	}
	Write16(p, 0); // AttachLen
	Write16(p, 0); // AddKartNum
	Write8(p, 0);  // IncRedPacketNum
	const size_t len = static_cast<size_t>(p - body);
	Set16(body, static_cast<WORD>(len));
	SendToClient(Client, 529, body + sizeof(USHORT),
		static_cast<DWORD>(len - sizeof(USHORT)),
		Client->ConnID, FE_PLAYER, Client->ConnID, Notify, 1);
}

void RequestPetStrengthen(std::shared_ptr<ClientNode> Client, BYTE* Body, size_t BodyLen)
{
	if (!Client || !Body || BodyLen < 14 || !Client->IsLogin)
		return;

	BYTE* p = Body;
	BYTE* const end = Body + BodyLen;
	USHORT wireLen = 0;
	if (BodyLen >= 16)
	{
		BYTE* afterLength = p;
		wireLen = Read16(afterLength);
		if (wireLen == BodyLen || wireLen + sizeof(USHORT) == BodyLen)
			p = afterLength;
	}
	if (p + 14 > end)
	{
		QQS_DebugPrintf10001("[PET-STRENG-REQ] malformed Uin=%u BodyLen=%zu WireLen=%u\n",
			Client->Uin, BodyLen, wireLen);
		ResponsePetStrengthen(Client, 10356);
		return;
	}

	const UINT requestUin = Read32(p);
	(void)Read32(p); // Time
	const UINT petID = Read32(p);
	const UINT type = Read8(p);
	UINT batch = Read8(p);
	if (batch == 0)
		batch = 1;

	UINT cardID = 0;
	UINT maxBatch = 0;
	UINT failAwardExp = 0;
	if (!QQSPetConfig::GetStrengthRuntimeRules(cardID, maxBatch, failAwardExp))
	{
		QQS_DebugPrintf10001("[PET-STRENG-GUARD] runtime rules unavailable Uin=%u PetID=%u\n",
			Client->Uin, petID);
		ResponsePetStrengthen(Client, 10356, 0, type);
		return;
	}
	if (batch > maxBatch)
		batch = maxBatch;

	if (requestUin != Client->Uin || petID == 0 || type != 0 ||
		!QQSPetConfig::HasStrength(petID))
	{
		QQS_DebugPrintf10001(
			"[PET-STRENG-GUARD] rejected RequestUin=%u AuthUin=%u PetID=%u Type=%u Batch=%u\n",
			requestUin, Client->Uin, petID, type, batch);
		ResponsePetStrengthen(Client, 10356, 0, type);
		return;
	}

	PetInfo targetPet{};
	if (!QQS_LoadPetInfo(Client->Uin, petID, targetPet))
	{
		QQS_DebugPrintf10001("[PET-STRENG-GUARD] unowned/missing pet Uin=%u PetID=%u\n",
			Client->Uin, petID);
		ResponsePetStrengthen(Client, 10356, 0, type);
		return;
	}

	UINT fullLevel = 0;
	if (!QQSPetConfig::GetStrengthFullLevel(petID, fullLevel) ||
		targetPet.StrengLevel >= fullLevel)
	{
		QQS_DebugPrintf10001(
			"[PET-STRENG-REQ] full/missing level Uin=%u PetID=%u Current=%u Full=%u\n",
			Client->Uin, petID, targetPet.StrengLevel, fullLevel);
		ResponsePetStrengthen(Client, 10356, 0, type, &targetPet);
		return;
	}

	for (UINT attempt = 0; attempt < batch; ++attempt)
	{
		const UINT oldLevel = targetPet.StrengLevel;
		const UINT nextLevel = oldLevel + 1;
		UINT succProb = 0;
		UINT useCardNum = 0;
		UINT costSuperMoney = 0;
		if (!QQSPetConfig::GetStrengthLevelRule(
			petID, nextLevel, succProb, useCardNum, costSuperMoney))
		{
			QQS_DebugPrintf10001(
				"[PET-STRENG-GUARD] missing level rule Uin=%u PetID=%u NextLevel=%u\n",
				Client->Uin, petID, nextLevel);
			ResponsePetStrengthen(Client, 10356, 0, type, &targetPet);
			break;
		}

		const UINT roll = succProb >= 10000 ? 0 : static_cast<UINT>(rand() % 10000);
		const bool succeeded = succProb >= 10000 || roll < succProb;
		PetStrengthenApplyResult applyResult{};
		if (!PlayerDB_ApplyPetStrengthenAttempt(
			Client->Uin,
			petID,
			oldLevel,
			cardID,
			useCardNum,
			costSuperMoney,
			succeeded,
			failAwardExp,
			applyResult))
		{
			QQS_LoadPetInfo(Client->Uin, petID, targetPet);
			SelectClientExp(Client);
			QQS_DebugPrintf10001(
				"[PET-STRENG-GUARD] transaction rejected Uin=%u PetID=%u Code=%u CardID=%u Need=%u Cost=%u\n",
				Client->Uin, petID, applyResult.Code, cardID, useCardNum, costSuperMoney);
			ResponsePetStrengthen(Client, 10356, 0, type, &targetPet);
			break;
		}

		targetPet.StrengLevel = applyResult.NewStrengLevel;
		PetInfo committedPet{};
		if (QQS_LoadPetInfo(Client->Uin, petID, committedPet))
			targetPet = committedPet;

		bool activePet = false;
		{
			std::unique_lock<std::shared_mutex> lock(Client->mtx);
			Client->SuperMoney = applyResult.NewSuperMoney;
			Client->Experience = applyResult.NewExperience;
			activePet = (Client->PetID == petID) || (Client->Pet && Client->Pet->ID == petID);
			if (activePet)
			{
				if (!Client->Pet)
					Client->Pet = std::make_shared<PetInfo>();
				*Client->Pet = targetPet;
				Client->PetID = petID;
				Client->PetStatus = static_cast<char>(targetPet.Status);
			}
		}

		NotifyClientUpdateMoney(Client);
		if (applyResult.CardNumAfter >= 0)
			NotifyPetStrengthenCardChange529(Client, cardID, applyResult.CardNumAfter);

		const UINT resultID = succeeded ? 0 : 10356;
		QQS_DebugPrintf10001(
			"[PET-STRENG-REQ] Uin=%u PetID=%u Batch=%u Attempt=%u OldLevel=%u NextLevel=%u "
			"SuccProb=%u Roll=%u Card=%u Cost=%u Result=%u NewLevel=%u\n",
			Client->Uin, petID, batch, attempt + 1, oldLevel, nextLevel,
			succProb, roll, useCardNum, costSuperMoney, resultID, targetPet.StrengLevel);

		if (succeeded && activePet)
			NotifyPetEvolution(Client, resultID, static_cast<UCHAR>(targetPet.Status));
		ResponsePetStrengthen(Client, resultID, useCardNum, type, &targetPet);
		if (succeeded)
			break;
	}
}

void ResponsePetStrengthen(
	std::shared_ptr<ClientNode> Client,
	UINT Result,
	UINT UseItemNum,
	UINT Type,
	const PetInfo* TargetPet)
{
	if (!Client)
		return;

	UINT cardID = 0;
	UINT maxBatch = 0;
	UINT failAwardExp = 0;
	QQSPetConfig::GetStrengthRuntimeRules(cardID, maxBatch, failAwardExp);
	const PetInfo* responsePet = TargetPet ? TargetPet :
		(Client->Pet ? Client->Pet.get() : nullptr);

	std::vector<BYTE> buf(256);
	BYTE* p = buf.data();
	Write32(p, Client->Uin);
	Write32(p, Result);
	Write32(p, responsePet ? responsePet->StrengLevel : 0);
	{
		BYTE* const failAward = p;
		Write16(p, 0);
		const bool hasFailAwardItem = Result != 0 && cardID != 0 && UseItemNum > 0;
		const UINT awardedExp = Result != 0 && UseItemNum > 0 ? failAwardExp : 0;
		Write32(p, 0); // AwardMoney
		Write32(p, Client->Money);
		Write32(p, 0); // AwardSuperMoney
		Write32(p, Client->SuperMoney);
		Write32(p, awardedExp);
		Write32(p, Client->Experience);
		Write32(p, hasFailAwardItem ? 1 : 0);
		if (hasFailAwardItem)
		{
			BYTE* const item = p;
			Write16(p, 0);
			Write32(p, cardID);
			Write32(p, UseItemNum);
			Write32(p, 0); // AvailPeriod
			Write8(p, 0);  // Status
			WriteUn(p, static_cast<DWORD>(time(nullptr)));
			Write32(p, 0); // OtherAttribute
			Write16(p, 0); // ItemType
			Set16(item, static_cast<WORD>(p - item));
		}
		Write32(p, 0); // AwardCoupons
		Write32(p, 0); // TotalCoupons
		Write32(p, 0); // AwardLuckMoney
		Write32(p, 0); // TotalLuckMoney
		Write32(p, 0); // AwardTeamWorkExp
		Write32(p, 0); // TotalTeamWorkExp
		Write32(p, 0); // AwardwlCash
		Write32(p, 0); // AwardwlCrystal
		Write32(p, 0); // AwardwlDegree
		Write32(p, 0); // chumcircleActivity
		Write32(p, 0); // Guildscore
		Write16(p, 0); // AppellcationID
		Write16(p, 0); // ScoreJingJi
		Write8(p, 0);  // ExtendInfoNum
		Write32(p, 0); // LiveExp
		Write32(p, 0); // AwardSpeedCoin
		Write32(p, 0); // TotalSpeedCoin
		Set16(failAward, static_cast<WORD>(p - failAward));
	}
	Write8(p, static_cast<UCHAR>(Type));
	WriteUn(p, responsePet ? responsePet->ID : 0);
	Write32(p, 0); // BeginDate
	Write32(p, 0); // BeginTime

	const DWORD len = static_cast<DWORD>(p - buf.data());
	QQS_DebugPrintf10001(
		"[PET-STRENG-RSP] Uin=%u Result=%u PetID=%u Level=%u UseCard=%u PayloadLen=%u\n",
		Client->Uin, Result, responsePet ? responsePet->ID : 0,
		responsePet ? responsePet->StrengLevel : 0, UseItemNum, len);
	// The encrypted MSGHEAD BodyLen is the CResponsePetStrengthenPara selfLen.
	SendToClient(Client, 20101, buf.data(), len,
		Client->ConnID, FE_PLAYER, Client->ConnID, Response, 1);
}

time_t StringToTimeStamp2(const char* str) {

	struct tm tm_;

	int year, month, day, hour, minute, second;

	sscanf_s(str, "%d-%d-%d %d:%d:%d", &year, &month, &day, &hour, &minute, &second);

	tm_.tm_year = year - 1900;

	tm_.tm_mon = month - 1;

	tm_.tm_mday = day;

	tm_.tm_hour = hour;

	tm_.tm_min = minute;

	tm_.tm_sec = second;

	tm_.tm_isdst = 0;

	time_t timeStamp = mktime(&tm_);

	return timeStamp;

}



void NotifyClientSucessAuction(std::shared_ptr<ClientNode> Client, UCHAR CommodityId, int BidPrice, int ItemId, int ItemAvailPeriod, int ItemNumber)//拍卖成功

{

	std::vector<BYTE> buf(819200); BYTE* p = buf.data(); size_t len;



	Write32(p, Client->Uin); //Uin

	{ //UnpayCommodity

		BYTE* pUnpayCommodity = p;

		Write16(pUnpayCommodity, 0); //len



		Write32(pUnpayCommodity, 0); //AuctionId

		Write8(pUnpayCommodity, CommodityId); //CommodityId

		Write32(pUnpayCommodity, BidPrice); //BidPrice

		Write32(pUnpayCommodity, 0); //BidTime

		Write32(pUnpayCommodity, ItemId); //ItemId

		Write32(pUnpayCommodity, ItemAvailPeriod); //ItemAvailPeriod

		Write32(pUnpayCommodity, ItemNumber); //ItemNumber

		Write8(pUnpayCommodity, 0); //AuctionType



		len = pUnpayCommodity - p;

		Set16(p, (WORD)len);

		p += len;

	}



	len = p - buf.data();

	SendToClient(Client, 11417, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Notify);

}





void CheckAuctionTime()

{

	if (AuctionConfig->Open != 1)

	{

		return;

	}



	time_t curTm = time(0);

	time_t timeStamp;

	int BidPrice = 0;

	int BidUin = 0;



	std::vector<int> conditionValues;

	std::vector<int> resultRow;

	for (int i = 0; i < AuctionConfig->AuctionItemNum; i++) {

		timeStamp = StringToTimeStamp2(AuctionConfig->AuctionItems[i].Time.c_str());

		if (curTm >= timeStamp)

		{

			conditionValues.clear();

			resultRow.clear();

			BidPrice = 0;

			BidUin = 0;

			conditionValues.push_back(AuctionConfig->AuctionItems[i].CommodityId);

			resultRow = executeQueryRow("SELECT BidPrice,BidUin  FROM AuctionInfo  WHERE CommodityId=?;", "CheckAuctionTime", conditionValues);

			if (resultRow.size() >= 2) {

				BidPrice = resultRow[0];

				BidUin = resultRow[1];

			}



			if (BidUin > 10000)

			{

				PlayerDB_InsertAuctionUnPayInfo(BidUin, BidPrice, AuctionConfig->AuctionItems[i]);



				PlayerDB_DeleteAuctionInfo(AuctionConfig->AuctionItems[i].CommodityId);



				std::shared_ptr<ClientNode> DstClient = GetClient(BidUin);

				if (DstClient)

				{

					NotifyClientSucessAuction(DstClient, AuctionConfig->AuctionItems[i].CommodityId, BidPrice, AuctionConfig->AuctionItems[i].ItemID, AuctionConfig->AuctionItems[i].AvailPeriod, AuctionConfig->AuctionItems[i].ItemNum);

				}

				BidPrice = 0;

				BidUin = 0;

			}

		}

	}



}



void ResponseGetAuctionCfg(std::shared_ptr<ClientNode> Client, UINT Uin)

{

	std::vector<BYTE> buf(819200); BYTE* p = buf.data(); size_t len;



	Write32(p, Uin); //Uin

	Write16(p, 0); //Result

	Write8(p, AuctionConfig->Open); //HasAuctionCfg

	for (size_t i = 0; i < AuctionConfig->Open; i++)

	{ //AuctionCfg

		BYTE* pAuctionCfg = p;

		Write16(pAuctionCfg, 0); //len



		Write32(pAuctionCfg, 0); //Version

		Write32(pAuctionCfg, 0); //AuctionId

		Write32(pAuctionCfg, 0); //BeginTime

		Write32(pAuctionCfg, 0); //CalcTime

		Write32(pAuctionCfg, 0); //EndTime

		Write8(pAuctionCfg, AuctionConfig->AuctionItemNum); //CommodityNumber

		for (size_t j = 0; j < AuctionConfig->AuctionItemNum; j++)

		{ //CommodityCfg

			BYTE* pCommodityCfg = pAuctionCfg;

			Write16(pCommodityCfg, 0); //len



			Write32(pCommodityCfg, AuctionConfig->AuctionItems[j].ItemID); //ItemId

			Write32(pCommodityCfg, AuctionConfig->AuctionItems[j].AvailPeriod); //ItemAvailPeriod

			Write32(pCommodityCfg, AuctionConfig->AuctionItems[j].ItemNum); //ItemNumber

			Write32(pCommodityCfg, AuctionConfig->AuctionItems[j].StartingPrice); //StartingPrice 

			Write32(pCommodityCfg, AuctionConfig->AuctionItems[j].IncreasePrice); //IncreasePrice 

			Write8(pCommodityCfg, AuctionConfig->AuctionItems[j].CommodityId); //CommodityId

			Write8(pCommodityCfg, 0); //DescLen



			len = pCommodityCfg - pAuctionCfg;

			Set16(pAuctionCfg, (WORD)len);

			pAuctionCfg += len;

		}

		Write32(pAuctionCfg, 0); //PreviewTime

		Write8(pAuctionCfg, 0); //AuctionType



		len = pAuctionCfg - p;

		Set16(p, (WORD)len);

		p += len;

	}

	Write8(p, AuctionConfig->Open); //HasBulletin 

	for (size_t i = 0; i < AuctionConfig->Open; i++)

	{ //Bulletin

		BYTE* pBulletin = p;

		Write16(pBulletin, 0); //len



		Write32(pBulletin, 0); //Version

		Write8(pBulletin, AuctionConfig->Content.length()); //ContentLen

		memcpy(pBulletin, AuctionConfig->Content.c_str(), AuctionConfig->Content.length());

		pBulletin += AuctionConfig->Content.length();

		len = pBulletin - p;

		Set16(p, (WORD)len);

		p += len;

	}

	Write32(p, 0); //LeftTime 

	Write8(p, AuctionConfig->Open); //hasBegan 

	Write32(p, 0); //QBCouponsID

	Write8(p, 0); //LastAuctionType



	len = p - buf.data();

	SendToClient(Client, 11411, buf.data(), len, Client->ConnID, FE_PLAYER, 1, Response);

}



