void ResponseC2SGetTimesExperienceInfo(
	std::shared_ptr<ClientNode> Client,
	BYTE* Body,
	size_t BodyLen)
{
	// d249 sends Uin + Time and retries this request after five minutes when no
	// response arrives. The official response is exactly ten big-endian U32
	// fields; all-zero values mean that the feature is inactive for this player.
	if (!Client || !Body || BodyLen < 8)
	{
		QQS_DebugPrintf10001(
			"[TIMES-EXP-20042] reject malformed request Uin=%u BodyLen=%llu expected>=8\n",
			Client ? Client->Uin : 0,
			static_cast<unsigned long long>(BodyLen));
		return;
	}

	BYTE* request = Body;
	const UINT requestUin = Read32(request);
	const UINT requestTime = Read32(request);
	BYTE response[40] = {};

	QQS_DebugPrintf10001(
		"[TIMES-EXP-20042] send inactive state Uin=%u RequestUin=%u Time=%u PayloadLen=%zu\n",
		Client->Uin,
		requestUin,
		requestTime,
		sizeof(response));
	SendToClient(
		Client,
		20042,
		response,
		static_cast<DWORD>(sizeof(response)),
		Client->ConnID,
		FE_PLAYER,
		Client->ConnID,
		Response);
}
